import React, { useEffect, useState, useRef, useCallback } from 'react';
import { Sidebar } from './components/Sidebar';
import { VideoPlayer } from './components/VideoPlayer';
import { ChannelGrid } from './components/ChannelGrid';
import { ScheduleList } from './components/ScheduleList';
import { FavoritesBar } from './components/FavoritesBar'; 
import { AiChatPet } from './components/AiChatPet';
import { AlarmModal } from './components/AlarmModal';
import { fetchCountries, fetchChannelsByCountry, fetchRadioStations, parseM3U } from './services/iptvService';
import { Country, Channel, AppTheme, Reminder, AppSettings } from './types';
import { Menu, RefreshCw, CalendarClock, Tv, Sparkles, History, Shuffle } from 'lucide-react';

const THEMES: AppTheme[] = [
  {
    id: 'glass',
    name: '星际深邃 (Deep Space)',
    type: 'glass',
    styles: {
      bgMain: 'bg-[#020617]', 
      bgSidebar: 'bg-slate-950/40 backdrop-blur-3xl border-r border-white/10',
      textMain: 'text-white drop-shadow-md',
      textDim: 'text-slate-400',
      border: 'border-white/10',
      card: 'bg-white/5 hover:bg-white/10 backdrop-blur-md border border-white/5 hover:border-cyan-500/50 transition-all duration-500',
      cardHover: 'hover:-translate-y-2 shadow-2xl shadow-cyan-500/10',
      button: 'bg-white/5 hover:bg-white/15 text-white backdrop-blur-sm border border-white/10',
      buttonActive: 'bg-cyan-500 text-white border-cyan-400 shadow-[0_0_20px_rgba(6,182,212,0.4)]',
      buttonPrimary: 'bg-gradient-to-r from-cyan-500 to-blue-600 text-white shadow-lg shadow-cyan-500/20 hover:shadow-cyan-500/40',
      input: 'bg-slate-900/50 border-white/10 text-white placeholder:text-slate-500 focus:border-cyan-500/50',
      font: 'font-sans',
      layoutShape: 'rounded-[1.5rem]',
      shadow: 'shadow-2xl',
      accentColor: '#06b6d4',
      bgPattern: ''
    }
  },
  {
    id: 'cartoon',
    name: '糖果世界 (Candy)',
    type: 'cartoon',
    styles: {
      bgMain: 'bg-[#FFEBEE]', 
      bgSidebar: 'bg-[#F48FB1] border-r-4 border-black', 
      textMain: 'text-slate-900 font-extrabold',
      textDim: 'text-slate-700 font-bold',
      border: 'border-4 border-black',
      card: 'bg-white border-4 border-black shadow-[6px_6px_0px_0px_rgba(0,0,0,1)] transition-transform',
      cardHover: 'hover:-translate-y-1 hover:shadow-[10px_10px_0px_0px_rgba(0,0,0,1)] hover:rotate-1',
      button: 'bg-white border-4 border-black text-black shadow-[4px_4px_0px_0px_rgba(0,0,0,1)] active:translate-x-[4px] active:translate-y-[4px] active:shadow-none rounded-2xl',
      buttonActive: 'bg-[#00D2FF] text-white border-4 border-black', 
      buttonPrimary: 'bg-[#FF4081] text-white border-4 border-black shadow-[4px_4px_0px_0px_rgba(0,0,0,1)] hover:bg-[#F50057]', 
      input: 'bg-white border-4 border-black text-black shadow-[inset_3px_3px_0px_0px_rgba(0,0,0,0.1)]',
      font: 'font-[Fredoka,sans-serif]',
      layoutShape: 'rounded-[1.5rem]', 
      shadow: 'shadow-[8px_8px_0px_0px_rgba(0,0,0,1)]',
      accentColor: '#FF4081',
      bgPattern: 'bg-dot-pattern'
    }
  },
  {
    id: 'web95',
    name: '经典 95 (Retro)',
    type: 'web95',
    styles: {
      bgMain: 'bg-[#008080]', 
      bgSidebar: 'bg-[#c0c0c0] border-r-2 border-r-black border-t-white',
      textMain: 'text-black',
      textDim: 'text-gray-700',
      border: 'border-2 border-t-white border-l-white border-b-black border-r-black', 
      card: 'bg-[#c0c0c0] border-2 border-t-white border-l-white border-b-black border-r-black',
      cardHover: '',
      button: 'bg-[#c0c0c0] border-2 border-t-white border-l-white border-b-black border-r-black active:border-t-black active:border-l-black active:border-b-white active:border-r-white text-black',
      buttonActive: 'bg-[#c0c0c0] border-2 border-t-black border-l-black border-b-white border-r-white text-black font-bold',
      buttonPrimary: 'bg-[#000080] text-white border-2 border-t-white border-l-white border-b-black border-r-black',
      input: 'bg-white border-2 border-t-black border-l-black border-b-white border-r-white text-black font-mono',
      font: 'font-mono',
      layoutShape: 'rounded-none',
      shadow: '',
      accentColor: '#000080',
      bgPattern: ''
    }
  }
];

const CUSTOM_COUNTRY: Country = { name: '导入频道 (Custom)', code: 'CUSTOM', languages: [], flag: '📂' };
const FAVORITES_COUNTRY: Country = { name: '我的收藏 (Favorites)', code: 'FAVORITES', languages: [], flag: '⭐' };

const App: React.FC = () => {
  const [isAppReady, setIsAppReady] = useState(false);
  const [countries, setCountries] = useState<Country[]>([]);
  const [selectedCountry, setSelectedCountry] = useState<Country | null>(null);
  const [channels, setChannels] = useState<Channel[]>([]);
  const [currentChannel, setCurrentChannel] = useState<Channel | null>(null);
  const [history, setHistory] = useState<Channel[]>([]);
  const [customChannels, setCustomChannels] = useState<Channel[]>([]);

  const [isSticky, setIsSticky] = useState(false);
  const [stickyEnabled, setStickyEnabled] = useState(true);
  const playerMarkerRef = useRef<HTMLDivElement>(null);

  const [loadingCountries, setLoadingCountries] = useState(true);
  const [loadingChannels, setLoadingChannels] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [mode, setMode] = useState<'tv' | 'radio'>('tv');
  const [showSchedule, setShowSchedule] = useState(false);
  const [activeReminder, setActiveReminder] = useState<Reminder | null>(null);
  const [settings, setSettings] = useState<AppSettings>({ enableSound: true });

  const [favorites, setFavorites] = useState<Channel[]>([]);
  const [reminders, setReminders] = useState<Reminder[]>([]);
  const [currentTheme, setCurrentTheme] = useState<AppTheme>(THEMES[0]);

  const audioCtxRef = useRef<AudioContext | null>(null);

  const playUiSound = useCallback(() => {
      if (!settings.enableSound) return;
      try {
          if (!audioCtxRef.current) {
              audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
          }
          const ctx = audioCtxRef.current;
          if (ctx.state === 'suspended') ctx.resume();
          const osc = ctx.createOscillator();
          const gain = ctx.createGain();
          osc.connect(gain); gain.connect(ctx.destination);
          osc.type = 'sine'; osc.frequency.setValueAtTime(600, ctx.currentTime);
          osc.frequency.exponentialRampToValueAtTime(100, ctx.currentTime + 0.1);
          gain.gain.setValueAtTime(0.05, ctx.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.1);
          osc.start(); osc.stop(ctx.currentTime + 0.1);
      } catch (e) {}
  }, [settings.enableSound]);

  useEffect(() => {
      const handleGlobalClick = (e: MouseEvent) => {
          const target = e.target as HTMLElement;
          const interactive = target.closest('button') || target.closest('a') || target.closest('input') || target.closest('[role="button"]');
          if (interactive) playUiSound();
      };
      window.addEventListener('click', handleGlobalClick, true); 
      return () => window.removeEventListener('click', handleGlobalClick, true);
  }, [playUiSound]);

  useEffect(() => {
      const observer = new IntersectionObserver(
          ([entry]) => {
              if (!stickyEnabled) { setIsSticky(false); return; }
              setIsSticky(!entry.isIntersecting);
          },
          { threshold: 0, rootMargin: "-100px 0px 0px 0px" } 
      );
      if (playerMarkerRef.current) observer.observe(playerMarkerRef.current);
      return () => observer.disconnect();
  }, [stickyEnabled]);

  useEffect(() => {
      try {
          const savedFavs = localStorage.getItem('global_favorites');
          if (savedFavs) setFavorites(JSON.parse(savedFavs));
          const savedRems = localStorage.getItem('global_reminders');
          if (savedRems) setReminders(JSON.parse(savedRems));
          const savedHist = localStorage.getItem('global_history');
          if (savedHist) setHistory(JSON.parse(savedHist));
      } catch (e) { console.warn(e); }
      setIsAppReady(true);
  }, []);

  useEffect(() => {
      if (isAppReady) {
        localStorage.setItem('global_favorites', JSON.stringify(favorites));
        localStorage.setItem('global_reminders', JSON.stringify(reminders));
        localStorage.setItem('global_history', JSON.stringify(history));
      }
  }, [favorites, reminders, history, isAppReady]);

  useEffect(() => {
    if (selectedCountry?.code === 'FAVORITES') {
        setChannels(favorites.filter(c => (c.type || 'tv') === mode));
    }
  }, [favorites, selectedCountry, mode]);

  const loadCountries = async () => {
    try {
      setLoadingCountries(true);
      const data = await fetchCountries();
      setCountries([FAVORITES_COUNTRY, ...data]);
      let defaultCountry = data.find(c => c.code === 'US') || data[0];
      if (defaultCountry) setSelectedCountry(defaultCountry);
      else setSelectedCountry(FAVORITES_COUNTRY);
    } catch (err) {
      setCountries([FAVORITES_COUNTRY]);
      setSelectedCountry(FAVORITES_COUNTRY);
    } finally {
      setLoadingCountries(false);
    }
  };

  useEffect(() => { if (isAppReady) loadCountries(); }, [isAppReady]);

  const loadContent = async (refresh = false) => {
    if (!selectedCountry) return;
    if (selectedCountry.code === 'CUSTOM') { setChannels(customChannels); return; }
    if (selectedCountry.code === 'FAVORITES') { setChannels(favorites.filter(c => (c.type || 'tv') === mode)); return; }

    setLoadingChannels(true);
    if (!refresh) setChannels([]);
    try {
        let data: Channel[] = [];
        if (mode === 'tv') data = await fetchChannelsByCountry(selectedCountry.code, refresh);
        else data = await fetchRadioStations(selectedCountry.code, refresh);
        setChannels(data);
    } catch (err) { setChannels([]); } 
    finally { setLoadingChannels(false); }
  };

  useEffect(() => { loadContent(); }, [selectedCountry, mode]);

  const handleChannelSelect = (channel: Channel) => {
      setCurrentChannel(channel);
      setHistory(prev => {
          const filtered = prev.filter(c => c.id !== channel.id);
          return [channel, ...filtered].slice(0, 10);
      });
      window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleShuffle = () => {
      if (channels.length === 0) return;
      const randomIdx = Math.floor(Math.random() * channels.length);
      handleChannelSelect(channels[randomIdx]);
  };

  if (!isAppReady || !currentTheme) return <div className="flex h-screen w-full items-center justify-center bg-black text-white">初始化中...</div>;

  return (
    <div className={`flex h-screen ${currentTheme.styles.bgMain} ${currentTheme.styles.bgPattern} ${currentTheme.styles.font} overflow-hidden transition-colors duration-700 relative`}>
      <div className="bg-noise"></div>

      <Sidebar 
        countries={countries}
        selectedCountry={selectedCountry}
        onSelectCountry={(c) => { setSelectedCountry(c); setSidebarOpen(false); }}
        isOpen={sidebarOpen}
        onClose={() => setSidebarOpen(false)}
        mode={mode}
        onModeChange={(m) => { setMode(m); setSidebarOpen(false); }}
        themes={THEMES}
        currentTheme={currentTheme}
        onThemeChange={setCurrentTheme}
        favorites={favorites}
        onSelectFavorite={handleChannelSelect}
        onImportM3U={(content) => {
            const parsed = parseM3U(content);
            setCustomChannels(parsed.map(c => ({...c, type: 'tv'})));
            if (!countries.find(c => c.code === 'CUSTOM')) setCountries(prev => [CUSTOM_COUNTRY, ...prev]);
            setSelectedCountry(CUSTOM_COUNTRY);
        }}
        settings={settings}
        onToggleSound={() => setSettings(prev => ({ ...prev, enableSound: !prev.enableSound }))}
        reminders={reminders}
        onDeleteReminder={(id) => setReminders(prev => prev.filter(r => r.id !== id))}
        onPlayReminder={(id) => {
            let ch = channels.find(c => c.id === id) || favorites.find(c => c.id === id);
            if (ch) handleChannelSelect(ch);
        }}
        history={history}
      />

      <main className="flex-1 flex flex-col h-full overflow-hidden relative z-10">
        <header className={`md:hidden ${currentTheme.styles.bgSidebar} border-b ${currentTheme.styles.border} p-4 flex items-center justify-between shrink-0 z-30`}>
            <button onClick={() => setSidebarOpen(true)} className={currentTheme.styles.textMain}><Menu className="w-6 h-6" /></button>
            <h1 className={`text-lg font-bold ${currentTheme.styles.textMain}`}>全球实时看和听</h1>
            <button onClick={() => loadContent(true)} className={currentTheme.styles.textMain}><RefreshCw className={`w-5 h-5 ${loadingChannels ? 'animate-spin' : ''}`} /></button>
        </header>

        <div className={`flex-1 overflow-y-auto ${currentTheme.type === 'web95' ? 'scrollbar-web95' : 'scrollbar-thin'}`}>
            <div className={`w-full relative py-8 px-4 md:px-12 shadow-2xl ${currentTheme.type === 'glass' ? 'bg-black/40' : 'bg-black/10'} border-b ${currentTheme.styles.border}`}>
                <div 
                    className="absolute inset-0 opacity-20 pointer-events-none transition-colors duration-1000 blur-[120px] animate-pulse-glow"
                    style={{ background: `radial-gradient(circle at 30% 30%, ${currentTheme.styles.accentColor} 0%, transparent 60%)` }}
                ></div>

                <div className="max-w-[1600px] mx-auto relative z-10">
                    <div className="flex flex-col md:flex-row md:items-end justify-between mb-8 gap-4">
                        <div className="flex items-center gap-5">
                            <div className={`p-4 rounded-[1.5rem] ${currentTheme.styles.card} shadow-2xl border-0`}>
                                <div className="text-2xl">{selectedCountry?.flag || '🌍'}</div>
                            </div>
                            <div>
                                <h2 className={`text-4xl md:text-5xl font-black tracking-tighter bg-gradient-to-br from-white via-white to-white/30 bg-clip-text text-transparent drop-shadow-2xl ${currentTheme.type !== 'glass' ? 'text-current bg-none' : ''}`}>
                                    {selectedCountry ? selectedCountry.name : '探索世界'}
                                </h2>
                                <div className="flex items-center gap-3 mt-2">
                                    <span className={`px-3 py-1 text-[10px] font-black uppercase tracking-[0.2em] ${currentTheme.styles.buttonActive} rounded-full`}>
                                        {mode.toUpperCase()} LIVE
                                    </span>
                                    <p className={`text-xs font-bold ${currentTheme.styles.textDim} opacity-80`}>
                                        {channels.length} 个实时信号已连接
                                    </p>
                                </div>
                            </div>
                        </div>
                        <div className="flex gap-2">
                            <button onClick={handleShuffle} className={`px-6 py-3 ${currentTheme.styles.buttonPrimary} ${currentTheme.styles.layoutShape} text-sm flex items-center gap-2 font-bold group transition-all`}>
                                <Shuffle className="w-4 h-4 group-hover:rotate-180 transition-transform duration-500" /> 随机漫游
                            </button>
                            <button onClick={() => loadContent(true)} className={`px-6 py-3 ${currentTheme.styles.button} ${currentTheme.styles.layoutShape} text-sm flex items-center gap-2 font-bold`}>
                                <RefreshCw className={`w-4 h-4 ${loadingChannels ? 'animate-spin' : ''}`} /> 刷新线路
                            </button>
                        </div>
                    </div>

                    <FavoritesBar favorites={favorites} currentChannel={currentChannel} onSelectChannel={handleChannelSelect} theme={currentTheme} mode={mode} />

                    <div ref={playerMarkerRef} className="w-full h-1"></div>

                    <div className="mt-6 relative">
                        <VideoPlayer 
                            channel={currentChannel} 
                            country={selectedCountry} 
                            theme={currentTheme} 
                            isFavorite={!!currentChannel && favorites.some(c => c.id === currentChannel.id)} 
                            onToggleFavorite={() => {
                                if (!currentChannel) return;
                                setFavorites(prev => {
                                    const exists = prev.some(c => c.id === currentChannel.id);
                                    if (exists) return prev.filter(c => c.id !== currentChannel.id);
                                    return [...prev, { ...currentChannel, type: currentChannel.type || mode }];
                                });
                            }} 
                            onAddReminder={(ch, time) => {
                                setReminders(prev => [...prev, { id: Math.random().toString(36).substr(2, 9), channelId: ch.id, channelName: ch.name, timeStr: time, created: Date.now() }]);
                                alert(`已设置提醒: ${ch.name} @ ${time}`);
                            }} 
                            settings={settings} 
                            isSticky={isSticky}
                            onCloseSticky={() => setStickyEnabled(false)}
                        />
                    </div>
                </div>
            </div>

            <div className="max-w-[1600px] mx-auto p-6 md:p-12">
                <div className="flex items-center justify-between mb-8">
                    <div className="flex items-center gap-4">
                        <div className={`w-1.5 h-10 ${currentTheme.styles.accentColor === '#000000' ? 'bg-black' : currentTheme.styles.buttonPrimary} rounded-full`}></div>
                        <h3 className={`text-2xl font-black ${currentTheme.styles.textMain} tracking-tight`}>频道目录</h3>
                    </div>
                    {history.length > 0 && (
                         <div className={`hidden md:flex items-center gap-2 text-xs font-bold ${currentTheme.styles.textDim}`}>
                            <History className="w-3.5 h-3.5" /> 最近看过
                         </div>
                    )}
                </div>

                <ChannelGrid channels={channels} currentChannel={currentChannel} onSelectChannel={handleChannelSelect} loading={loadingChannels} mode={mode} theme={currentTheme} favorites={favorites} onToggleFavorite={(channel) => {
                     setFavorites(prev => {
                        const exists = prev.some(c => c.id === channel.id);
                        if (exists) return prev.filter(c => c.id !== channel.id);
                        return [...prev, { ...channel, type: channel.type || mode }];
                    });
                }} />
            </div>
        </div>
      </main>

      <ScheduleList reminders={reminders} isOpen={showSchedule} onClose={() => setShowSchedule(false)} onDelete={(id) => setReminders(prev => prev.filter(r => r.id !== id))} theme={currentTheme} onPlayChannel={(id) => {
          let ch = channels.find(c => c.id === id) || favorites.find(c => c.id === id);
          if (ch) handleChannelSelect(ch);
      }} allChannels={[...channels, ...favorites]} />

      <AlarmModal reminder={activeReminder} onClose={() => setActiveReminder(null)} onWatch={(id) => {
           let ch = channels.find(c => c.id === id) || favorites.find(c => c.id === id);
           if (ch) handleChannelSelect(ch);
           setActiveReminder(null);
      }} theme={currentTheme} />

      <AiChatPet theme={currentTheme} currentChannels={channels} onSelectChannel={handleChannelSelect} />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Country, AppTheme, Channel, AppSettings, Reminder } from '../types';
import { Search, Globe, X, Tv, Radio, Palette, Star, Upload, Volume2, VolumeX, Settings, ChevronDown, ChevronUp, CalendarClock, Trash2, Play, Music, Plus, History } from 'lucide-react';

interface SidebarProps {
  countries: Country[];
  selectedCountry: Country | null;
  onSelectCountry: (country: Country) => void;
  isOpen: boolean;
  onClose: () => void;
  mode: 'tv' | 'radio';
  onModeChange: (mode: 'tv' | 'radio') => void;
  themes: AppTheme[];
  currentTheme: AppTheme;
  onThemeChange: (theme: AppTheme) => void;
  favorites: Channel[];
  onSelectFavorite: (channel: Channel) => void;
  onImportM3U: (content: string) => void;
  settings: AppSettings;
  onToggleSound: () => void;
  reminders: Reminder[];
  onDeleteReminder: (id: string) => void;
  onPlayReminder: (channelId: string) => void;
  history: Channel[];
}

export const Sidebar: React.FC<SidebarProps> = ({ 
    countries, 
    selectedCountry, 
    onSelectCountry,
    isOpen,
    onClose,
    mode,
    onModeChange,
    themes,
    currentTheme,
    onThemeChange,
    favorites,
    onSelectFavorite,
    onImportM3U,
    settings,
    onToggleSound,
    reminders,
    onDeleteReminder,
    onPlayReminder,
    history
}) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [showThemes, setShowThemes] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [activeTab, setActiveTab] = useState<'favorites' | 'history' | 'schedule' | null>('favorites');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const filteredCountries = useMemo(() => {
    if (!searchQuery) return countries;
    const lowerQ = searchQuery.toLowerCase();
    return countries.filter(c => 
      c.name.toLowerCase().includes(lowerQ) || 
      c.code.toLowerCase().includes(lowerQ)
    );
  }, [countries, searchQuery]);

  const modeFavorites = useMemo(() => favorites.filter(c => (c.type || 'tv') === mode), [favorites, mode]);
  const modeHistory = useMemo(() => history.filter(c => (c.type || 'tv') === mode), [history, mode]);

  const { styles } = currentTheme;

  return (
    <>
        {isOpen && <div className="fixed inset-0 bg-black/70 z-40 md:hidden backdrop-blur-md" onClick={onClose} />}

        <aside className={`
            fixed md:relative z-50 h-full ${styles.bgSidebar} w-80 flex flex-col
            transition-transform duration-500 ease-in-out
            ${isOpen ? 'translate-x-0' : '-translate-x-full md:translate-x-0'}
            ${styles.shadow}
        `}>

        <div className={`p-6 border-b ${styles.border} flex items-center justify-between shrink-0`}>
            <div className={`flex items-center gap-3 ${styles.textMain}`}>
                <div className={`p-2 ${styles.buttonPrimary} rounded-xl shadow-lg`}>
                    <Globe className="w-5 h-5" />
                </div>
                <h1 className="text-xl font-black tracking-tighter">全球看听</h1>
            </div>
            <button onClick={onClose} className={`md:hidden ${styles.textDim}`}>
                <X className="w-6 h-6" />
            </button>
        </div>

        <div className="p-6 pb-2 space-y-4 shrink-0">
            <div className={`flex p-1 ${styles.layoutShape} ${currentTheme.type === 'web95' ? styles.border : 'bg-black/20'}`}>
                <button 
                    onClick={() => onModeChange('tv')}
                    className={`flex-1 flex items-center justify-center gap-2 py-2.5 ${styles.layoutShape} text-xs font-black transition-all ${mode === 'tv' ? styles.buttonActive : styles.textDim}`}
                >
                    <Tv className="w-4 h-4" /> 电视
                </button>
                <button 
                    onClick={() => onModeChange('radio')}
                    className={`flex-1 flex items-center justify-center gap-2 py-2.5 ${styles.layoutShape} text-xs font-black transition-all ${mode === 'radio' ? styles.buttonActive : styles.textDim}`}
                >
                    <Radio className="w-4 h-4" /> 广播
                </button>
            </div>

            <div className="flex gap-1">
                {(['favorites', 'history', 'schedule'] as const).map((tab) => (
                    <button 
                        key={tab}
                        onClick={() => setActiveTab(activeTab === tab ? null : tab)}
                        className={`flex-1 flex flex-col items-center justify-center py-2 ${styles.layoutShape} transition-all border ${activeTab === tab ? styles.buttonActive : `${styles.button} opacity-60`}`}
                    >
                        {tab === 'favorites' && <Star className="w-4 h-4 mb-1" />}
                        {tab === 'history' && <History className="w-4 h-4 mb-1" />}
                        {tab === 'schedule' && <CalendarClock className="w-4 h-4 mb-1" />}
                        <span className="text-[9px] font-bold uppercase">{tab === 'favorites' ? '收藏' : tab === 'history' ? '历史' : '提醒'}</span>
                    </button>
                ))}
            </div>

            {activeTab && (
                <div className={`p-2 ${styles.card} ${styles.layoutShape} space-y-1 max-h-56 overflow-y-auto ${currentTheme.type === 'web95' ? 'scrollbar-web95' : 'scrollbar-thin'} animate-in slide-in-from-top-2 duration-300`}>
                    {activeTab === 'favorites' && (
                        modeFavorites.length > 0 ? modeFavorites.map(ch => (
