};

import React, { useState, useMemo } from 'react';
import { Channel, AppTheme } from '../types';
import { Tv, Search, ImageOff, Radio, Star, Play, Tag, HelpCircle, Activity } from 'lucide-react';

interface ChannelGridProps {
  channels: Channel[];
  currentChannel: Channel | null;
  onSelectChannel: (channel: Channel) => void;
  loading: boolean;
  mode: 'tv' | 'radio';
  theme: AppTheme;
  favorites: Channel[];
  onToggleFavorite: (channel: Channel) => void;
}

export const ChannelGrid: React.FC<ChannelGridProps> = ({ 
    channels, 
    currentChannel, 
    onSelectChannel,
    loading,
    mode,
    theme,
    favorites,
    onToggleFavorite
}) => {
  const [filter, setFilter] = useState('');
  const { styles } = theme;

  const filteredChannels = useMemo(() => {
    if (!filter) return channels;
    const q = filter.toLowerCase();
    return channels.filter(c => 
        c.name.toLowerCase().includes(q) || 
        (c.group && c.group.toLowerCase().includes(q))
    );
  }, [channels, filter]);

  const groupedChannels = useMemo(() => {
      if (filter) return null;
      const groups: Record<string, Channel[]> = {};
      filteredChannels.forEach(c => {
          let groupName = c.group ? c.group.split(';')[0].trim() : '其他频道';
          if (!groups[groupName]) groups[groupName] = [];
          groups[groupName].push(c);
      });
      return Object.entries(groups).sort((a, b) => a[0].localeCompare(b[0]));
  }, [filteredChannels, filter]);

  if (loading) {
    return (
      <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 2xl:grid-cols-8 gap-6 animate-pulse">
        {Array.from({ length: 24 }).map((_, i) => (
            <div key={i} className={`h-32 ${styles.card} ${styles.layoutShape} opacity-40`}></div>
        ))}
      </div>
    );
  }

  return (
    <div className="space-y-12">
      <div className={`sticky top-0 z-30 flex items-center gap-4 p-4 ${styles.layoutShape} ${styles.border} ${styles.bgSidebar} shadow-2xl backdrop-blur-3xl bg-opacity-90 transition-all`}>
        <Search className={`w-5 h-5 ${styles.textDim}`} />
        <input 
            type="text"
            placeholder={`智能检索: 在 ${channels.length} 个${mode === 'tv' ? '频道' : '电台'}中快速查找...`}
            className={`bg-transparent border-none focus:outline-none text-base font-medium w-full placeholder:opacity-40 ${styles.textMain}`}
            value={filter}
            onChange={(e) => setFilter(e.target.value)}
        />
        {filter && (
            <button onClick={() => setFilter('')} className={`text-xs font-bold ${styles.textDim} hover:${styles.textMain}`}>清除</button>
        )}
      </div>

      <div className="min-h-[400px]">
          {groupedChannels ? (
              <div className="space-y-16">
                  {groupedChannels.map(([groupName, groupItems]) => (
                      <div key={groupName} className="space-y-6">
                          <div className={`flex items-end gap-3 pb-4 border-b ${styles.border}`}>
                              <h4 className={`text-2xl font-black ${styles.textMain} tracking-tighter uppercase`}>
                                  {groupName}
                              </h4>
                              <div className={`flex items-center gap-1 px-3 py-1 rounded-full bg-white/5 text-[10px] font-black ${styles.textDim}`}>
                                  <Activity className="w-3 h-3" /> {groupItems.length}
                              </div>
                          </div>

                          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 2xl:grid-cols-8 gap-5">
                              {groupItems.map(channel => (
                                  <ChannelCard 
                                      key={channel.id} 
                                      channel={channel} 
                                      isActive={currentChannel?.id === channel.id}
                                      onSelectChannel={onSelectChannel} 
                                      isFavorite={favorites.some(f => f.id === channel.id)} 
                                      onToggleFavorite={onToggleFavorite} 
                                      mode={mode} 
                                      styles={styles}
                                  />
                              ))}
                          </div>
                      </div>
                  ))}
              </div>
          ) : (
              <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 2xl:grid-cols-8 gap-5">
                {filteredChannels.length > 0 ? (
                    filteredChannels.map(channel => (
                        <ChannelCard 
                            key={channel.id} 
                            channel={channel} 
                            isActive={currentChannel?.id === channel.id}
                            onSelectChannel={onSelectChannel} 
                            isFavorite={favorites.some(f => f.id === channel.id)} 
                            onToggleFavorite={onToggleFavorite} 
                            mode={mode} 
                            styles={styles}
                        />
                    ))
                ) : (
                    <div className={`col-span-full py-24 text-center ${styles.textDim}`}>
                        <HelpCircle className="w-16 h-16 mx-auto mb-6 opacity-10" />
                        <p className="text-xl font-bold">没有找到匹配的结果</p>
                        <p className="text-sm mt-2 opacity-50">尝试搜索更简洁的关键词</p>
                    </div>
                )}
              </div>
          )}
      </div>
    </div>
  );
};

