            <div className="flex items-center gap-2">
                <span className={`text-xl`}>{selectedCountry?.flag || '🌍'}</span>
                <span className={`text-sm font-black ${currentTheme.styles.textMain}`}>{selectedCountry?.name || '探索中...'}</span>
            </div>

            <div className={`flex items-center gap-4 ${currentTheme.styles.textMain}`}>
                <div className={`flex items-center gap-2 px-3 py-1.5 rounded-full bg-black/40 border ${currentTheme.styles.border} shadow-inner`}>
                    <div className="w-1.5 h-1.5 rounded-full bg-cyan-400 animate-pulse"></div>
                    <Clock className="w-3.5 h-3.5 opacity-60" />
                    <span className="text-[11px] font-mono font-black tracking-wider w-16 text-center">{localTime}</span>
                </div>
                <button onClick={() => loadContent(true)} className={`p-2 hover:bg-white/10 rounded-xl transition-all ${loadingChannels ? 'animate-spin' : ''}`}><RefreshCw className="w-4 h-4" /></button>
            </div>
        </header>

        <div className={`flex-1 overflow-y-auto ${currentTheme.type === 'web95' ? 'scrollbar-web95' : 'scrollbar-thin'}`}>
            <div className={`w-full relative py-12 px-6 md:px-12 shadow-2xl ${currentTheme.type === 'glass' ? 'bg-black/20' : 'bg-black/5'} border-b ${currentTheme.styles.border}`}>
                <div 
                    className="absolute inset-0 opacity-20 pointer-events-none transition-colors duration-1000 blur-[120px] animate-pulse-glow"
                    style={{ background: `radial-gradient(circle at 50% 50%, ${currentTheme.styles.accentColor} 0%, transparent 70%)` }}
                ></div>

                <div className="max-w-[1400px] mx-auto relative z-10">
                    <div className="flex flex-col md:flex-row md:items-end justify-between mb-10 gap-6">
                        <div className="space-y-4">
                            <h2 className={`text-5xl md:text-7xl font-black tracking-tighter bg-gradient-to-br from-white via-white to-white/30 bg-clip-text text-transparent drop-shadow-2xl ${currentTheme.type !== 'glass' ? 'text-current bg-none' : ''}`}>
                                {selectedCountry ? selectedCountry.name : 'WORLDWIDE'}
                            </h2>
                            <div className="flex items-center gap-3 flex-wrap">
                                <span className={`px-4 py-1.5 text-[10px] font-black uppercase tracking-[0.2em] ${currentTheme.styles.buttonActive} rounded-full shadow-lg`}>
                                    {mode.toUpperCase()} LIVE
                                </span>
                                <div className={`flex items-center gap-2 text-xs font-bold ${currentTheme.styles.textDim} bg-white/5 px-3 py-1.5 rounded-full border ${currentTheme.styles.border}`}>
                                    <div className="w-1.5 h-1.5 rounded-full bg-green-500"></div>
                                    <span>{channels.length} 条可用线路</span>
                                </div>
                            </div>
                        </div>
                        <div className="flex gap-3">
                            <button onClick={handleShuffle} className={`px-8 py-4 ${currentTheme.styles.buttonPrimary} ${currentTheme.styles.layoutShape} text-sm flex items-center gap-3 font-black group transition-all`}>
                                <Shuffle className="w-4 h-4 group-hover:rotate-180 transition-transform duration-500" /> 随机探索
                            </button>
                        </div>
                    </div>

                    <FavoritesBar favorites={favorites} currentChannel={currentChannel} onSelectChannel={handleChannelSelect} theme={currentTheme} mode={mode} />

                    <div ref={playerMarkerRef} className="w-full h-1"></div>

                    <div className="mt-8 relative">
                        <VideoPlayer 
                            channel={currentChannel} 
                            country={selectedCountry} 
                            theme={currentTheme} 
                            isFavorite={!!currentChannel && favorites.some(c => c.id === currentChannel.id)} 
                            onToggleFavorite={() => {
                                if (!currentChannel) return;
                                setFavorites(prev => {
                                    const exists = prev.some(c => c.id === currentChannel.id);
                                    if (exists) return prev.filter(c => c.id !== currentChannel.id);
                                    return [...prev, { ...currentChannel, type: currentChannel.type || mode }];
                                });
                            }} 
                            onAddReminder={(ch, time) => {
                                setReminders(prev => [...prev, { id: Math.random().toString(36).substr(2, 9), channelId: ch.id, channelName: ch.name, timeStr: time, created: Date.now() }]);
                                alert(`已设置提醒: ${ch.name} @ ${time}`);
                            }} 
                            settings={settings} 
                            isSticky={isSticky}
                            onCloseSticky={() => setStickyEnabled(false)}
                        />
                    </div>
                </div>
            </div>

            <div className="max-w-[1400px] mx-auto p-8 md:p-12 pb-32">
                <div className="flex items-center justify-between mb-10">
                    <div className="flex items-center gap-4">
                        <div className={`w-2 h-10 ${currentTheme.styles.accentColor === '#000000' ? 'bg-black' : currentTheme.styles.buttonPrimary} rounded-full`}></div>
                        <h3 className={`text-3xl font-black ${currentTheme.styles.textMain} tracking-tighter`}>在线频道目录</h3>
                    </div>
                    {history.length > 0 && (
                         <div className={`hidden md:flex items-center gap-2 text-xs font-black uppercase tracking-widest ${currentTheme.styles.textDim}`}>
                            <History className="w-4 h-4" /> 播放足迹
                         </div>
                    )}
                </div>

                <ChannelGrid channels={channels} currentChannel={currentChannel} onSelectChannel={handleChannelSelect} loading={loadingChannels} mode={mode} theme={currentTheme} favorites={favorites} onToggleFavorite={(channel) => {
                     setFavorites(prev => {
                        const exists = prev.some(c => c.id === channel.id);
                        if (exists) return prev.filter(c => c.id !== channel.id);
                        return [...prev, { ...channel, type: channel.type || mode }];
                    });
                }} />
            </div>
        </div>
      </main>

      <ScheduleList reminders={reminders} isOpen={showSchedule} onClose={() => setShowSchedule(false)} onDelete={(id) => setReminders(prev => prev.filter(r => r.id !== id))} theme={currentTheme} onPlayChannel={(id) => {
          let ch = channels.find(c => c.id === id) || favorites.find(c => c.id === id);
          if (ch) handleChannelSelect(ch);
      }} allChannels={[...channels, ...favorites]} />

      <AlarmModal reminder={activeReminder} onClose={() => setActiveReminder(null)} onWatch={(id) => {
           let ch = channels.find(c => c.id === id) || favorites.find(c => c.id === id);
           if (ch) handleChannelSelect(ch);
           setActiveReminder(null);
      }} theme={currentTheme} />

      <AiChatPet theme={currentTheme} currentChannels={channels} onSelectChannel={handleChannelSelect} />
    </div>
  );
};

export default App;

