            <div className="flex items-center gap-6">
                <button onClick={() => setSidebarOpen(true)} className="md:hidden p-2"><Menu className="w-5 h-5 text-white" /></button>
                <div className="flex items-center gap-2">
                    <span className="text-xl">{selectedCountry?.flag}</span>
                    <h1 className="text-lg font-black tracking-tighter text-white uppercase">{selectedCountry?.name}</h1>
                </div>
            </div>

            <div className="flex items-center gap-6">
                {/* 数字化时间模块 */}
                <div className="hidden sm:flex items-center gap-4 bg-white/5 border border-white/10 px-4 py-2 rounded-full">
                    <div className="flex items-center gap-2">
