                        <span className="text-[10px] font-black text-cyan-400 tracking-widest uppercase">Live Signal</span>
                    </div>
                    <div className="w-[1px] h-3 bg-white/10"></div>
                    <div className="flex items-center gap-2 font-mono text-white font-bold">
                        <Clock className="w-3 h-3 opacity-40" />
                        <span>{localTime}</span>
                    </div>
                </div>
                <button onClick={() => loadContent(true)} className={`p-2 hover:bg-white/10 rounded-full transition-all ${loadingChannels ? 'animate-spin' : ''}`}>
                    <RefreshCw className="w-4 h-4 text-white/60" />
                </button>
            </div>
        </header>

        <div className={`flex-1 overflow-y-auto scrollbar-thin`}>
            {/* 核心播放区域 - 剧院模式 */}
            <section className="relative w-full px-8 py-10 max-w-[1400px] mx-auto">
                <div className="grid grid-cols-1 lg:grid-cols-12 gap-10 items-start">
