                                </div>
                            </div>
                        </div>

                        <button onClick={() => handleChannelSelect(channels[Math.floor(Math.random()*channels.length)])} 
                                className="w-full py-6 bg-cyan-500 hover:bg-cyan-400 text-black font-black uppercase tracking-widest rounded-2xl flex items-center justify-center gap-3 transition-all active:scale-95 shadow-[0_10px_30px_rgba(6,182,212,0.3)]">
                            <Shuffle className="w-5 h-5" /> 随机漫游
                        </button>

                        <div className={`${styles.card} p-6 ${styles.layoutShape}`}>
                            <h3 className="text-xs font-black text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                                <History className="w-3 h-3" /> 最近观看
