import React, { useState, useMemo } from 'react';
import { Channel, AppTheme } from '../types';
import { Tv, Search, Radio, Star, Play, Activity, Globe2 } from 'lucide-react';

interface ChannelGridProps {
  channels: Channel[];
  currentChannel: Channel | null;
  onSelectChannel: (channel: Channel) => void;
  loading: boolean;
  mode: 'tv' | 'radio';
  theme: AppTheme;
  favorites: Channel[];
  onToggleFavorite: (channel: Channel) => void;
}

export const ChannelGrid: React.FC<ChannelGridProps> = ({ 
    channels, currentChannel, onSelectChannel, loading, mode, theme, favorites, onToggleFavorite
}) => {
  const [filter, setFilter] = useState('');
  const { styles } = theme;

  const filteredChannels = useMemo(() => {
    if (!filter) return channels;
    const q = filter.toLowerCase();
    return channels.filter(c => c.name.toLowerCase().includes(q) || (c.group && c.group.toLowerCase().includes(q)));
  }, [channels, filter]);

  if (loading) {
    return (
      <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-6 xl:grid-cols-8 gap-4">
        {Array.from({ length: 16 }).map((_, i) => (
            <div key={i} className={`h-32 bg-white/5 rounded-2xl animate-pulse`}></div>
        ))}
      </div>
    );
  }

  return (
    <div className="space-y-12">
      {/* 极简搜索框 */}
      <div className="flex items-center gap-4 p-5 bg-white/5 border border-white/10 rounded-2xl backdrop-blur-3xl shadow-2xl">
        <Search className="w-5 h-5 text-cyan-500" />
        <input 
            type="text"
            placeholder="输入频道关键词，极速搜索信号..."
            className="bg-transparent border-none focus:outline-none text-white font-bold w-full placeholder:text-gray-600"
            value={filter}
            onChange={(e) => setFilter(e.target.value)}
        />
      </div>

      <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-6 xl:grid-cols-8 gap-5">
          {filteredChannels.map(channel => {
              const isActive = currentChannel?.id === channel.id;
              const isFav = favorites.some(f => f.id === channel.id);

              return (
                  <div
                      key={channel.id}
                      onClick={() => onSelectChannel(channel)}
                      className={`
                        group relative p-5 flex flex-col items-center justify-center text-center transition-all duration-500 cursor-pointer
                        rounded-2xl border backdrop-blur-md
                        ${isActive 
                            ? 'bg-cyan-500 border-cyan-400 shadow-[0_15px_40px_rgba(6,182,212,0.3)] -translate-y-2' 
                            : 'bg-white/5 border-white/5 hover:bg-white/10 hover:border-white/20 hover:-translate-y-1'}
                      `}
                  >
                      <div className={`w-12 h-12 mb-4 rounded-xl flex items-center justify-center overflow-hidden transition-transform group-hover:scale-110 ${isActive ? 'bg-black/20' : 'bg-black/40'}`}>
                          {channel.logo ? (
                              <img src={channel.logo} className="w-full h-full object-contain p-2" loading="lazy" />
                          ) : (
                              mode === 'tv' ? <Tv className="w-5 h-5 opacity-40" /> : <Radio className="w-5 h-5 opacity-40" />
                          )}
                      </div>

                      <span className={`text-xs font-black tracking-tight line-clamp-2 ${isActive ? 'text-black' : 'text-white'}`}>
                          {channel.name}
                      </span>

                      {isActive && (
                          <div className="absolute -top-1 -right-1">
                              <span className="flex h-3 w-3">
                                  <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-white opacity-75"></span>
