                                    <span className={`${styles.textMain} font-black text-xl`}>{channels.length} Nodes</span>
                                </div>
                                <div className="flex justify-between items-center">
                                    <span className={`${styles.textDim} font-bold`}>实时时区</span>
                                    <span className={`font-mono font-black ${styles.textMain}`} style={{ color: styles.accentColor }}>
                                      GMT {(new Date().getTimezoneOffset() / -60) > 0 ? '+' : ''}{new Date().getTimezoneOffset() / -60}
                                    </span>
                                </div>
                            </div>
                        </div>

                        <button onClick={() => handleChannelSelect(channels[Math.floor(Math.random()*channels.length)])} 
                                className={`w-full py-6 ${styles.buttonPrimary} ${styles.layoutShape} ${styles.shadow} flex items-center justify-center gap-4 transition-all active:scale-95 group`}>
                            <Shuffle className="w-6 h-6 group-hover:rotate-180 transition-transform duration-700" />
                            <span className="text-sm font-black uppercase tracking-widest">Surprise Me / 随机漫游</span>
                        </button>

                        <div className={`${styles.card} p-8 ${styles.layoutShape} ${styles.shadow}`}>
                            <h3 className={`text-xs font-black uppercase tracking-[0.3em] mb-6 opacity-40 ${styles.textMain} flex items-center gap-2`}>
                                <History className="w-4 h-4" /> History / 播放足迹
                            </h3>
                            <div className="space-y-4">
                                {history.length > 0 ? history.map(h => (
                                    <div key={h.id} onClick={() => handleChannelSelect(h)} className={`flex items-center gap-4 p-3 hover:bg-white/5 rounded-xl cursor-pointer group transition-all`}>
                                        <div className={`w-10 h-10 rounded-lg bg-black/20 flex items-center justify-center shrink-0 overflow-hidden border ${styles.border}`}>
                                            {h.logo ? <img src={h.logo} className="w-full h-full object-contain p-1" /> : <Tv className="w-4 h-4 opacity-30" />}
                                        </div>
                                        <span className={`font-bold truncate text-sm ${styles.textMain}`}>{h.name}</span>
                                    </div>
                                )) : <p className={`text-sm italic opacity-30 ${styles.textMain}`}>暂无记录</p>}
                            </div>
                        </div>
                    </div>
                </div>
            </section>

            <section className={`px-6 md:px-12 py-24 bg-black/5 border-t ${styles.border}`}>
                <div className="max-w-[1500px] mx-auto">
                    <div className="flex items-center gap-6 mb-16">
                        <div className="w-2 h-12 rounded-full" style={{ backgroundColor: styles.accentColor }}></div>
                        <h2 className={`text-4xl md:text-5xl font-black tracking-tighter uppercase italic ${styles.textMain}`}>Signal Directory</h2>
                    </div>

                    <ChannelGrid 
                        channels={channels} currentChannel={currentChannel} 
                        onSelectChannel={handleChannelSelect} loading={loadingChannels}
                        mode={mode} theme={currentTheme} favorites={favorites} onToggleFavorite={() => {}}
                    />
                </div>
            </section>
        </div>
      </main>

      <AiChatPet theme={currentTheme} currentChannels={channels} onSelectChannel={handleChannelSelect} />
    </div>
  );
};

