const FAVORITES_COUNTRY: Country = { name: '我的收藏', code: 'FAVORITES', languages: [], flag: '⭐' };

const App: React.FC = () => {
  const [isAppReady, setIsAppReady] = useState(false);
  const [countries, setCountries] = useState<Country[]>([]);
  const [selectedCountry, setSelectedCountry] = useState<Country | null>(null);
  const [channels, setChannels] = useState<Channel[]>([]);
  const [currentChannel, setCurrentChannel] = useState<Channel | null>(null);
  const [history, setHistory] = useState<Channel[]>([]);
  const [localTime, setLocalTime] = useState('');
  const [loadingChannels, setLoadingChannels] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [mode, setMode] = useState<'tv' | 'radio'>('tv');
  const [favorites, setFavorites] = useState<Channel[]>([]);
  const [reminders, setReminders] = useState<Reminder[]>([]);
  const [currentTheme, setCurrentTheme] = useState<AppTheme>(THEMES[0]);
  const [settings, setSettings] = useState<AppSettings>({ enableSound: true });

  useEffect(() => {
    const timer = setInterval(() => {
      const tz = (selectedCountry && selectedCountry.code !== 'FAVORITES') ? getTimezone(selectedCountry.code) : 'UTC';
      const now = new Date();
      setLocalTime(new Intl.DateTimeFormat('zh-CN', {
        hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false, timeZone: tz
      }).format(now));
    }, 1000);
    return () => clearInterval(timer);
  }, [selectedCountry]);

  useEffect(() => {
    const init = async () => {
      try {
        const data = await fetchCountries();
        setCountries([FAVORITES_COUNTRY, ...data]);
        setSelectedCountry(data.find(c => c.code === 'US') || data[0]);

        const savedFavs = localStorage.getItem('global_favorites');
        if (savedFavs) setFavorites(JSON.parse(savedFavs));
        setIsAppReady(true);
      } catch (e) {}
    };
    init();
  }, []);

  const loadContent = async (refresh = false) => {
    if (!selectedCountry) return;
    setLoadingChannels(true);
    try {
      let data = mode === 'tv' 
        ? await fetchChannelsByCountry(selectedCountry.code, refresh)
        : await fetchRadioStations(selectedCountry.code, refresh);
      setChannels(data);
    } catch (err) {} 
    finally { setLoadingChannels(false); }
  };

  useEffect(() => { if (isAppReady) loadContent(); }, [selectedCountry, mode, isAppReady]);

  const handleChannelSelect = (channel: Channel) => {
    setCurrentChannel(channel);
    setHistory(prev => [channel, ...prev.filter(c => c.id !== channel.id)].slice(0, 10));
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  if (!isAppReady) return <div className="h-screen w-full bg-[#050508] flex items-center justify-center text-cyan-500 font-mono animate-pulse uppercase tracking-widest">BOOTING SYSTEM...</div>;

  const { styles } = currentTheme;

  return (
    <div className={`flex h-screen w-full ${styles.bgMain} ${styles.bgPattern} ${styles.font} overflow-hidden transition-all duration-1000 relative`}>
      <div className="bg-noise"></div>

      <Sidebar 
        countries={countries} selectedCountry={selectedCountry} onSelectCountry={setSelectedCountry}
        isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} mode={mode} onModeChange={setMode}
        themes={THEMES} currentTheme={currentTheme} onThemeChange={setCurrentTheme}
        favorites={favorites} onSelectFavorite={handleChannelSelect} history={history}
        onImportM3U={() => {}} settings={settings} onToggleSound={() => {}} reminders={reminders}
        onDeleteReminder={() => {}} onPlayReminder={() => {}}
      />

      <main className="flex-1 flex flex-col h-full min-w-0 relative z-10">
        <header className={`shrink-0 px-8 py-5 flex items-center justify-between border-b ${styles.border} ${styles.bgSidebar} backdrop-blur-3xl`}>
            <div className="flex items-center gap-6">
                <button onClick={() => setSidebarOpen(true)} className={`md:hidden p-2 rounded-xl hover:bg-white/10 ${styles.textMain}`}><Menu className="w-7 h-7" /></button>
                <div className="flex items-center gap-4">
                    <span className="text-3xl drop-shadow-lg">{selectedCountry?.flag}</span>
                    <h1 className={`text-xl md:text-2xl font-black tracking-tighter uppercase italic ${styles.textMain}`}>
                        {selectedCountry?.name}
                    </h1>
                </div>
            </div>

            <div className="flex items-center gap-6">
                <div className={`hidden sm:flex items-center gap-4 ${styles.card} px-6 py-3 ${styles.layoutShape} ${styles.shadow}`}>
                    <div className="flex items-center gap-2">
                        <div className={`w-2.5 h-2.5 rounded-full animate-pulse`} style={{ backgroundColor: styles.accentColor }}></div>
                        <span className={`text-[12px] font-black tracking-[0.2em] uppercase opacity-70 ${styles.textMain}`}>SIGNAL ONLINE</span>
                    </div>
                    <div className={`w-[1px] h-4 ${styles.border} opacity-50`}></div>
                    <div className={`flex items-center gap-3 font-mono font-black ${styles.textMain}`}>
                        <Clock className="w-4 h-4 opacity-50" />
                        <span className="text-sm">{localTime}</span>
                    </div>
                </div>
                <button onClick={() => loadContent(true)} className={`p-3 rounded-full hover:bg-white/10 transition-all ${styles.textMain} ${loadingChannels ? 'animate-spin' : ''}`}>
                    <RefreshCw className="w-6 h-6" />
                </button>
            </div>
        </header>

        <div className={`flex-1 overflow-y-auto ${currentTheme.type === 'web95' ? 'scrollbar-web95' : 'scrollbar-thin'}`}>
            <section className="relative w-full px-6 md:px-12 py-12 max-w-[1600px] mx-auto">
                <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 lg:gap-16 items-start">
                    {/* 核心播放区域 */}
                    <div className="lg:col-span-8 space-y-12">
                        <div className={`${styles.shadow} ${styles.layoutShape} overflow-hidden border ${styles.border} relative group`}>
                          <VideoPlayer 
                              channel={currentChannel} country={selectedCountry} theme={currentTheme}
                              isFavorite={!!currentChannel && favorites.some(f => f.id === currentChannel.id)}
                              onToggleFavorite={() => {}} onAddReminder={() => {}}
                          />
                        </div>
                        <FavoritesBar favorites={favorites} currentChannel={currentChannel} onSelectChannel={handleChannelSelect} theme={currentTheme} mode={mode} />
                    </div>

                    {/* 状态看板 Bento Boxes */}
                    <div className="lg:col-span-4 space-y-8">
                        <div className={`${styles.card} p-10 ${styles.layoutShape} ${styles.shadow} relative overflow-hidden group`}>
                            <div className="absolute top-0 right-0 p-6 opacity-5 group-hover:scale-110 transition-transform">
                                <Zap className="w-16 h-16" />
                            </div>
                            <h3 className={`text-xs font-black uppercase tracking-[0.4em] mb-8 opacity-40 ${styles.textMain}`}>Live Node Status</h3>
                            <div className="space-y-8">
                                <div className="flex justify-between items-center">
                                    <span className={`${styles.textDim} font-black uppercase text-[11px]`}>Available Streams</span>
                                    <span className={`${styles.textMain} font-black text-2xl tracking-tighter`}>{channels.length} Nodes</span>
                                </div>
                                <div className="flex justify-between items-center">
                                    <span className={`${styles.textDim} font-black uppercase text-[11px]`}>Active Timezone</span>
                                    <span className={`font-mono font-black text-lg ${styles.textMain}`} style={{ color: styles.accentColor }}>
                                      GMT {(new Date().getTimezoneOffset() / -60) > 0 ? '+' : ''}{new Date().getTimezoneOffset() / -60}
                                    </span>
                                </div>
                            </div>
                        </div>

                        <button onClick={() => handleChannelSelect(channels[Math.floor(Math.random()*channels.length)])} 
                                className={`w-full py-8 ${styles.buttonPrimary} ${styles.layoutShape} ${styles.shadow} flex items-center justify-center gap-6 transition-all active:scale-95 group`}>
                            <Shuffle className="w-8 h-8 group-hover:rotate-180 transition-transform duration-700" />
                            <span className="text-md font-black uppercase tracking-[0.2em]">Random Signal / 随机漫游</span>
                        </button>

                        <div className={`${styles.card} p-10 ${styles.layoutShape} ${styles.shadow}`}>
                            <h3 className={`text-xs font-black uppercase tracking-[0.4em] mb-8 opacity-40 ${styles.textMain} flex items-center gap-3`}>
                                <History className="w-5 h-5" /> Recent Activity
                            </h3>
                            <div className="space-y-5">
                                {history.length > 0 ? history.map(h => (
                                    <div key={h.id} onClick={() => handleChannelSelect(h)} className={`flex items-center gap-5 p-4 hover:bg-white/5 rounded-2xl cursor-pointer group transition-all border border-transparent hover:border-white/5`}>
                                        <div className={`w-12 h-12 rounded-xl bg-black/40 flex items-center justify-center shrink-0 overflow-hidden border ${styles.border} group-hover:scale-110 transition-transform`}>
                                            {h.logo ? <img src={h.logo} className="w-full h-full object-contain p-2" /> : <Tv className="w-5 h-5 opacity-30" />}
                                        </div>
                                        <div className="flex flex-col">
                                          <span className={`font-black truncate text-sm uppercase ${styles.textMain}`}>{h.name}</span>
                                          <span className="text-[10px] text-gray-600 font-bold uppercase tracking-widest">{h.group || 'Public Stream'}</span>
                                        </div>
                                    </div>
                                )) : <p className={`text-sm italic opacity-30 ${styles.textMain} py-4`}>暂无记录</p>}
                            </div>
                        </div>
                    </div>
                </div>
            </section>

            {/* 底部目录 Bento Grid */}
            <section className={`px-6 md:px-12 py-32 bg-black/5 border-t ${styles.border}`}>
                <div className="max-w-[1600px] mx-auto">
                    <div className="flex items-center gap-8 mb-20">
                        <div className="w-3 h-16 rounded-full" style={{ backgroundColor: styles.accentColor }}></div>
                        <div>
                          <h2 className={`text-5xl md:text-7xl font-black tracking-tighter uppercase italic ${styles.textMain} leading-none`}>Signal Directory</h2>
                          <p className={`mt-2 text-sm font-bold opacity-30 uppercase tracking-[0.5em] ${styles.textMain}`}>Real-time broadcasting hub</p>
                        </div>
                    </div>

                    <ChannelGrid 
                        channels={channels} currentChannel={currentChannel} 
                        onSelectChannel={handleChannelSelect} loading={loadingChannels}
                        mode={mode} theme={currentTheme} favorites={favorites} onToggleFavorite={() => {}}
                    />
                </div>
            </section>
        </div>
      </main>

      <AiChatPet theme={currentTheme} currentChannels={channels} onSelectChannel={handleChannelSelect} />
    </div>
  );
};

export default App;

