const FAVORITES_COUNTRY: Country = { name: '我的收藏', code: 'FAVORITES', languages: [], flag: '⭐' };

const App: React.FC = () => {
  const [isAppReady, setIsAppReady] = useState(false);
  const [countries, setCountries] = useState<Country[]>([]);
  const [selectedCountry, setSelectedCountry] = useState<Country | null>(null);
  const [channels, setChannels] = useState<Channel[]>([]);
  const [currentChannel, setCurrentChannel] = useState<Channel | null>(null);
  const [history, setHistory] = useState<Channel[]>([]);
  const [localTime, setLocalTime] = useState('');
  const [loadingChannels, setLoadingChannels] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [mode, setMode] = useState<'tv' | 'radio'>('tv');
  const [favorites, setFavorites] = useState<Channel[]>([]);
  const [reminders, setReminders] = useState<Reminder[]>([]);
  const [currentTheme, setCurrentTheme] = useState<AppTheme>(THEMES[0]);
  const [settings, setSettings] = useState<AppSettings>({ enableSound: true });

  useEffect(() => {
    const timer = setInterval(() => {
      const tz = (selectedCountry && selectedCountry.code !== 'FAVORITES') ? getTimezone(selectedCountry.code) : 'UTC';
      const now = new Date();
      setLocalTime(new Intl.DateTimeFormat('zh-CN', {
        hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false, timeZone: tz
      }).format(now));
    }, 1000);
    return () => clearInterval(timer);
  }, [selectedCountry]);

  useEffect(() => {
    const init = async () => {
      try {
        const data = await fetchCountries();
        setCountries([FAVORITES_COUNTRY, ...data]);
        setSelectedCountry(data.find(c => c.code === 'US') || data[0]);
        const savedFavs = localStorage.getItem('global_favorites');
        if (savedFavs) setFavorites(JSON.parse(savedFavs));
        setIsAppReady(true);
      } catch (e) {}
    };
    init();
  }, []);

  const loadContent = async (refresh = false) => {
    if (!selectedCountry) return;
    setLoadingChannels(true);
    try {
      let data = mode === 'tv' 
        ? await fetchChannelsByCountry(selectedCountry.code, refresh)
        : await fetchRadioStations(selectedCountry.code, refresh);
      setChannels(data);
    } catch (err) {} 
    finally { setLoadingChannels(false); }
  };

  useEffect(() => { if (isAppReady) loadContent(); }, [selectedCountry, mode, isAppReady]);

  const handleChannelSelect = (channel: Channel) => {
    setCurrentChannel(channel);
    setHistory(prev => [channel, ...prev.filter(c => c.id !== channel.id)].slice(0, 10));
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  if (!isAppReady) return (
    <div className="h-screen w-full bg-[#050508] flex flex-col items-center justify-center">
      <div className="w-12 h-12 border-4 border-cyan-500/20 border-t-cyan-500 rounded-full animate-spin mb-4"></div>
      <div className="text-cyan-500 font-mono text-xs animate-pulse tracking-[0.3em] uppercase">Initializing Core...</div>
    </div>
  );

  const { styles } = currentTheme;

  return (
    <div className={`flex h-screen w-full ${styles.bgMain} ${styles.bgPattern} ${styles.font} overflow-hidden transition-colors duration-700 relative`}>
      <div className="bg-noise"></div>

      <Sidebar 
        countries={countries} selectedCountry={selectedCountry} onSelectCountry={setSelectedCountry}
        isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} mode={mode} onModeChange={setMode}
        themes={THEMES} currentTheme={currentTheme} onThemeChange={setCurrentTheme}
        favorites={favorites} onSelectFavorite={handleChannelSelect} history={history}
        onImportM3U={() => {}} settings={settings} onToggleSound={() => {}} reminders={reminders}
        onDeleteReminder={() => {}} onPlayReminder={() => {}}
      />

      <main className="flex-1 flex flex-col h-full min-w-0 relative z-10">
        <header className={`shrink-0 px-6 py-4 md:px-10 flex items-center justify-between border-b ${styles.border} ${styles.bgSidebar} backdrop-blur-3xl`}>
            <div className="flex items-center gap-5 min-w-0">
                <button onClick={() => setSidebarOpen(true)} className={`md:hidden p-2 rounded-xl hover:bg-white/10 ${styles.textMain}`}><Menu className="w-6 h-6" /></button>
                <div className="flex items-center gap-3 truncate">
                    <span className="text-3xl shrink-0">{selectedCountry?.flag}</span>
                    <h1 className={`text-xl md:text-2xl font-black truncate uppercase italic tracking-tighter ${styles.textMain}`}>
                        {selectedCountry?.name}
                    </h1>
                </div>
            </div>

            <div className="flex items-center gap-5 shrink-0 ml-4">
                <div className={`hidden sm:flex items-center gap-3 ${styles.card} px-5 py-2.5 ${styles.layoutShape} ${styles.shadow}`}>
                    <div className={`w-2 h-2 rounded-full animate-pulse`} style={{ backgroundColor: styles.accentColor }}></div>
                    <div className={`flex items-center gap-2 font-mono font-black ${styles.textMain}`}>
                        <Clock className="w-3.5 h-3.5 opacity-40" />
                        <span className="text-xs">{localTime}</span>
                    </div>
                </div>
                <button onClick={() => loadContent(true)} className={`p-2.5 rounded-full hover:bg-white/10 transition-all ${styles.textMain} ${loadingChannels ? 'animate-spin' : ''}`}>
                    <RefreshCw className="w-5 h-5" />
                </button>
            </div>
        </header>

        <div className={`flex-1 overflow-y-auto ${currentTheme.type === 'web95' ? 'scrollbar-web95' : 'scrollbar-thin'}`}>
            <section className="relative w-full px-4 md:px-10 py-8 max-w-[1600px] mx-auto">
                <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 md:gap-10 items-start">
                    {/* 核心播放区域 */}
                    <div className="lg:col-span-8 space-y-8 min-w-0">
                        <div className={`${styles.shadow} ${styles.layoutShape} overflow-hidden border ${styles.border} bg-black ring-1 ring-white/5`}>
                          <VideoPlayer 
                              channel={currentChannel} country={selectedCountry} theme={currentTheme}
                              isFavorite={!!currentChannel && favorites.some(f => f.id === currentChannel.id)}
                              onToggleFavorite={() => {}} onAddReminder={() => {}}
                          />
                        </div>
                        <FavoritesBar favorites={favorites} currentChannel={currentChannel} onSelectChannel={handleChannelSelect} theme={currentTheme} mode={mode} />
                    </div>

                    {/* 状态看板 Bento Boxes */}
                    <div className="lg:col-span-4 space-y-6 min-w-0 overflow-hidden">
                        <div className={`${styles.card} p-8 ${styles.layoutShape} ${styles.shadow} relative overflow-hidden group min-w-0`}>
                            <h3 className={`text-[10px] font-black uppercase tracking-[0.3em] mb-6 opacity-40 ${styles.textMain}`}>Live Station Info</h3>
                            <div className="space-y-6 min-w-0">
                                <div className="flex justify-between items-center gap-4 min-w-0">
                                    <span className={`${styles.textDim} font-bold text-xs uppercase shrink-0`}>Streams</span>
                                    <span className={`${styles.textMain} font-black text-xl truncate`}>{channels.length} Nodes</span>
                                </div>
                                <div className="flex justify-between items-center gap-4 min-w-0">
                                    <span className={`${styles.textDim} font-bold text-xs uppercase shrink-0`}>Current Zone</span>
                                    <span className={`font-mono font-black text-sm truncate ${styles.textMain}`} style={{ color: styles.accentColor }}>
                                      GMT {(new Date().getTimezoneOffset() / -60) > 0 ? '+' : ''}{new Date().getTimezoneOffset() / -60}
                                    </span>
                                </div>
                            </div>
                        </div>

                        <button onClick={() => handleChannelSelect(channels[Math.floor(Math.random()*channels.length)])} 
                                className={`w-full py-6 ${styles.buttonPrimary} ${styles.layoutShape} ${styles.shadow} flex items-center justify-center gap-4 transition-all active:scale-95 group overflow-hidden`}>
                            <Shuffle className="w-5 h-5 group-hover:rotate-180 transition-transform duration-500" />
                            <span className="text-xs font-black uppercase tracking-widest truncate">Random Channel</span>
                        </button>

                        <div className={`${styles.card} p-8 ${styles.layoutShape} ${styles.shadow} min-w-0`}>
                            <h3 className={`text-[10px] font-black uppercase tracking-[0.3em] mb-6 opacity-40 ${styles.textMain} flex items-center gap-2`}>
                                <History className="w-3.5 h-3.5" /> Recent Footprints
                            </h3>
                            <div className="space-y-4 min-w-0">
                                {history.length > 0 ? history.map(h => (
                                    <div key={h.id} onClick={() => handleChannelSelect(h)} className={`flex items-center gap-4 p-3 hover:bg-white/5 rounded-xl cursor-pointer group transition-all min-w-0`}>
                                        <div className={`w-10 h-10 rounded-lg bg-black/40 flex items-center justify-center shrink-0 overflow-hidden border ${styles.border} group-hover:scale-105 transition-transform`}>
                                            {h.logo ? <img src={h.logo} className="w-full h-full object-contain p-1" alt="" /> : <Tv className="w-4 h-4 opacity-20" />}
                                        </div>
                                        <div className="flex flex-col min-w-0 flex-1">
                                          <span className={`font-black truncate text-xs uppercase ${styles.textMain}`}>{h.name}</span>
                                          <span className="text-[9px] text-gray-600 font-bold uppercase truncate tracking-tight">{h.group || 'Universal'}</span>
                                        </div>
                                        <ChevronRight className={`w-3 h-3 ${styles.textDim} opacity-0 group-hover:opacity-100 -translate-x-2 group-hover:translate-x-0 transition-all`} />
                                    </div>
                                )) : <p className={`text-xs italic opacity-30 ${styles.textMain} py-4`}>No history available</p>}
                            </div>
                        </div>
                    </div>
                </div>
            </section>

            <section className={`px-4 md:px-10 py-24 bg-black/5 border-t ${styles.border}`}>
                <div className="max-w-[1600px] mx-auto">
                    <div className="flex items-baseline gap-6 mb-16">
                        <div className="w-2.5 h-10 rounded-full shrink-0" style={{ backgroundColor: styles.accentColor }}></div>
                        <div className="min-w-0">
                          <h2 className={`text-4xl md:text-6xl font-black tracking-tighter uppercase italic ${styles.textMain} leading-none truncate`}>Signal Directory</h2>
                        </div>
                    </div>

                    <ChannelGrid 
                        channels={channels} currentChannel={currentChannel} 
                        onSelectChannel={handleChannelSelect} loading={loadingChannels}
                        mode={mode} theme={currentTheme} favorites={favorites} onToggleFavorite={() => {}}
                    />
                </div>
            </section>
        </div>
      </main>

      <AiChatPet theme={currentTheme} currentChannels={channels} onSelectChannel={handleChannelSelect} />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Country, AppTheme, Channel, AppSettings, Reminder } from '../types';
import { Search, Globe, X, Tv, Radio, Palette, Star, Upload, Volume2, VolumeX, Settings, ChevronDown, ChevronUp, CalendarClock, Trash2, Play, Music, Plus, History } from 'lucide-react';

interface SidebarProps {
  countries: Country[];
  selectedCountry: Country | null;
  onSelectCountry: (country: Country) => void;
  isOpen: boolean;
  onClose: () => void;
  mode: 'tv' | 'radio';
  onModeChange: (mode: 'tv' | 'radio') => void;
  themes: AppTheme[];
  currentTheme: AppTheme;
  onThemeChange: (theme: AppTheme) => void;
  favorites: Channel[];
  onSelectFavorite: (channel: Channel) => void;
  onImportM3U: (content: string) => void;
  settings: AppSettings;
  onToggleSound: () => void;
  reminders: Reminder[];
  onDeleteReminder: (id: string) => void;
  onPlayReminder: (channelId: string) => void;
  history: Channel[];
}

export const Sidebar: React.FC<SidebarProps> = ({ 
    countries, 
    selectedCountry, 
    onSelectCountry,
    isOpen,
    onClose,
    mode,
    onModeChange,
    themes,
    currentTheme,
    onThemeChange,
    favorites,
    onSelectFavorite,
    onImportM3U,
    settings,
    onToggleSound,
    reminders,
    onDeleteReminder,
    onPlayReminder,
    history
}) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [showThemes, setShowThemes] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [activeTab, setActiveTab] = useState<'favorites' | 'history' | 'schedule' | null>('favorites');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const filteredCountries = useMemo(() => {
    if (!searchQuery) return countries;
    const lowerQ = searchQuery.toLowerCase();
    return countries.filter(c => 
      c.name.toLowerCase().includes(lowerQ) || 
      c.code.toLowerCase().includes(lowerQ)
    );
  }, [countries, searchQuery]);

  const modeFavorites = useMemo(() => favorites.filter(c => (c.type || 'tv') === mode), [favorites, mode]);
  const modeHistory = useMemo(() => history.filter(c => (c.type || 'tv') === mode), [history, mode]);

  const { styles } = currentTheme;

  return (
    <>
        {isOpen && <div className="fixed inset-0 bg-black/80 z-40 md:hidden backdrop-blur-xl" onClick={onClose} />}

        <aside className={`
            fixed md:relative z-50 h-full ${styles.bgSidebar} w-80 flex flex-col min-w-0
            transition-transform duration-500 ease-in-out
            ${isOpen ? 'translate-x-0' : '-translate-x-full md:translate-x-0'}
            ${styles.shadow}
        `}>

        <div className={`p-6 border-b ${styles.border} flex items-center justify-between shrink-0 min-w-0`}>
            <div className={`flex items-center gap-3 ${styles.textMain} min-w-0`}>
                <div className={`p-2 ${styles.buttonPrimary} rounded-xl shadow-lg shrink-0`}>
                    <Globe className="w-5 h-5" />
                </div>
                <h1 className="text-xl font-black tracking-tighter truncate uppercase italic">Live Hub</h1>
            </div>
            <button onClick={onClose} className={`md:hidden ${styles.textDim} p-1`}>
                <X className="w-6 h-6" />
            </button>
        </div>

        <div className="p-5 pb-2 space-y-4 shrink-0">
            <div className={`flex p-1 ${styles.layoutShape} ${currentTheme.type === 'web95' ? styles.border : 'bg-black/20'}`}>
                <button 
                    onClick={() => onModeChange('tv')}
                    className={`flex-1 flex items-center justify-center gap-2 py-2.5 ${styles.layoutShape} text-xs font-black transition-all ${mode === 'tv' ? styles.buttonActive : styles.textDim}`}
                >
                    <Tv className="w-4 h-4" /> TV
                </button>
                <button 
                    onClick={() => onModeChange('radio')}
                    className={`flex-1 flex items-center justify-center gap-2 py-2.5 ${styles.layoutShape} text-xs font-black transition-all ${mode === 'radio' ? styles.buttonActive : styles.textDim}`}
                >
                    <Radio className="w-4 h-4" /> FM
                </button>
            </div>

            <div className="flex gap-1">
                {(['favorites', 'history', 'schedule'] as const).map((tab) => (
                    <button 
                        key={tab}
                        onClick={() => setActiveTab(activeTab === tab ? null : tab)}
                        className={`flex-1 flex flex-col items-center justify-center py-2 ${styles.layoutShape} transition-all border ${activeTab === tab ? styles.buttonActive : `${styles.button} opacity-40`}`}
                    >
                        {tab === 'favorites' && <Star className="w-3.5 h-3.5 mb-1" />}
                        {tab === 'history' && <History className="w-3.5 h-3.5 mb-1" />}
                        {tab === 'schedule' && <CalendarClock className="w-3.5 h-3.5 mb-1" />}
                        <span className="text-[9px] font-black uppercase tracking-tighter">{tab === 'favorites' ? 'Fav' : tab === 'history' ? 'Past' : 'Plan'}</span>
                    </button>
                ))}
            </div>

            {activeTab && (
                <div className={`p-1.5 ${styles.card} ${styles.layoutShape} space-y-1 max-h-56 overflow-y-auto ${currentTheme.type === 'web95' ? 'scrollbar-web95' : 'scrollbar-thin'} animate-in slide-in-from-top-2 duration-300 min-w-0`}>
                    {activeTab === 'favorites' && (
                        modeFavorites.length > 0 ? modeFavorites.map(ch => (
                            <button key={ch.id} onClick={() => { onSelectFavorite(ch); if (window.innerWidth < 768) onClose(); }} className={`w-full flex items-center gap-3 p-2.5 ${styles.layoutShape} hover:bg-white/10 text-left group min-w-0`}>
                                <div className="w-7 h-7 rounded bg-black/40 shrink-0 flex items-center justify-center overflow-hidden">
                                    {ch.logo ? <img src={ch.logo} className="w-full h-full object-contain" /> : <Tv className="w-3.5 h-3.5 opacity-20" />}
                                </div>
                                <span className={`text-[11px] font-black truncate flex-1 uppercase tracking-tight ${styles.textMain}`}>{ch.name}</span>
                            </button>
                        )) : <p className="text-[10px] text-center p-6 opacity-30 font-bold uppercase italic">Empty Star</p>
                    )}
                    {/* ... (history and schedule content trimmed similarly) */}
                </div>
            )}
        </div>

        <div className={`flex-1 overflow-y-auto px-5 space-y-1.5 ${currentTheme.type === 'web95' ? 'scrollbar-web95' : 'scrollbar-thin'}`}>
            <div className={`sticky top-0 z-10 pt-2 pb-3 ${styles.bgSidebar}`}>
                <div className={`relative ${styles.input} ${styles.layoutShape} ${styles.border} flex items-center px-4 py-2.5 shadow-inner min-w-0`}>
                    <Search className={`w-4 h-4 ${styles.textDim} shrink-0`} />
                    <input 
                        type="text" 
                        placeholder="SEARCH REGION..." 
                        className="bg-transparent border-none focus:outline-none text-xs w-full ml-3 font-black uppercase tracking-widest placeholder:opacity-30"
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                    />
                </div>
            </div>

            <div className="space-y-1 pb-6 min-w-0">
                {filteredCountries.map(country => (
                    <button
                        key={country.code}
                        onClick={() => { onSelectCountry(country); if (window.innerWidth < 768) onClose(); }}
                        className={`
                            w-full flex items-center gap-4 p-3 ${styles.layoutShape} transition-all min-w-0
                            ${selectedCountry?.code === country.code 
                                ? styles.buttonActive
                                : `${styles.textDim} hover:bg-white/5`
                            }
                        `}
                    >
                        <span className="text-2xl shrink-0 drop-shadow-md">{country.flag}</span>
                        <span className="text-xs font-black truncate uppercase tracking-tight flex-1 text-left">{country.name}</span>
                        {selectedCountry?.code === country.code && (
                            <div className="ml-auto w-1.5 h-1.5 rounded-full bg-white shadow-lg animate-pulse"></div>
                        )}
                    </button>
                ))}
            </div>
        </div>

        <div className={`p-5 border-t ${styles.border} bg-black/10 space-y-3 shrink-0`}>
            <button onClick={() => fileInputRef.current?.click()} className={`w-full flex items-center justify-center gap-2 py-3 ${styles.layoutShape} ${styles.border} ${styles.button} text-[10px] font-black uppercase tracking-widest transition-all hover:scale-[1.02]`}>
                <Upload className="w-3.5 h-3.5" /> Import Playlist
            </button>
            <input type="file" accept=".m3u,.m3u8" ref={fileInputRef} className="hidden" onChange={(e) => {
                const f = e.target.files?.[0];
                if (!f) return;
                const r = new FileReader();
                r.onload = (ev) => { if (ev.target?.result) onImportM3U(ev.target.result as string); };
                r.readAsText(f);
                e.target.value = '';
            }} />

            <div className="flex gap-2">
                <button onClick={() => { setShowSettings(!showSettings); setShowThemes(false); }} className={`flex-1 flex items-center justify-center gap-2 py-2.5 text-xs font-bold ${styles.button} ${styles.border} ${styles.layoutShape} ${showSettings ? styles.buttonActive : ''}`}>
                    <Settings className="w-4 h-4" />
                </button>
                <button onClick={() => { setShowThemes(!showThemes); setShowSettings(false); }} className={`flex-1 flex items-center justify-center gap-2 py-2.5 text-xs font-bold ${styles.button} ${styles.border} ${styles.layoutShape} ${showThemes ? styles.buttonActive : ''}`}>
                    <Palette className="w-4 h-4" />
                </button>
            </div>

            {showThemes && (
                 <div className={`p-2 ${styles.card} ${styles.layoutShape} border ${styles.border} space-y-1 max-h-48 overflow-y-auto scrollbar-none`}>
                    {themes.map(t => (
                        <button key={t.id} onClick={() => { onThemeChange(t); setShowThemes(false); }} className={`w-full text-left px-3 py-2.5 text-[9px] font-black uppercase tracking-widest ${styles.layoutShape} ${currentTheme.id === t.id ? styles.buttonActive : 'hover:bg-white/5 opacity-60 hover:opacity-100'}`}>
                            {t.name}
                        </button>
                    ))}
                 </div>
            )}
        </div>
      </aside>
    </>
  );
};

