const FAVORITES_COUNTRY: Country = { name: '我的收藏', code: 'FAVORITES', languages: [], flag: '⭐' };

const App: React.FC = () => {
  const [isAppReady, setIsAppReady] = useState(false);
  const [countries, setCountries] = useState<Country[]>([]);
  const [selectedCountry, setSelectedCountry] = useState<Country | null>(null);
  const [channels, setChannels] = useState<Channel[]>([]);
  const [currentChannel, setCurrentChannel] = useState<Channel | null>(null);
  const [history, setHistory] = useState<Channel[]>([]);
  const [localTime, setLocalTime] = useState('');
  const [loadingChannels, setLoadingChannels] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [mode, setMode] = useState<'tv' | 'radio'>('tv');
  const [favorites, setFavorites] = useState<Channel[]>([]);
  const [reminders, setReminders] = useState<Reminder[]>([]);
  const [currentTheme, setCurrentTheme] = useState<AppTheme>(THEMES[0]);
  const [settings, setSettings] = useState<AppSettings>({ enableSound: true });

  useEffect(() => {
    const timer = setInterval(() => {
      const tz = (selectedCountry && selectedCountry.code !== 'FAVORITES') ? getTimezone(selectedCountry.code) : 'UTC';
      const now = new Date();
      setLocalTime(new Intl.DateTimeFormat('zh-CN', {
        hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false, timeZone: tz
      }).format(now));
    }, 1000);
    return () => clearInterval(timer);
  }, [selectedCountry]);

  useEffect(() => {
    const init = async () => {
      try {
        const data = await fetchCountries();
        setCountries([FAVORITES_COUNTRY, ...data]);
        setSelectedCountry(data.find(c => c.code === 'US') || data[0]);
        const savedFavs = localStorage.getItem('global_favorites');
        if (savedFavs) setFavorites(JSON.parse(savedFavs));
        setIsAppReady(true);
      } catch (e) {}
    };
    init();
  }, []);

  const loadContent = async (refresh = false) => {
    if (!selectedCountry) return;
    setLoadingChannels(true);
    try {
      let data = mode === 'tv' 
        ? await fetchChannelsByCountry(selectedCountry.code, refresh)
        : await fetchRadioStations(selectedCountry.code, refresh);
      setChannels(data);
    } catch (err) {} 
    finally { setLoadingChannels(false); }
  };

  useEffect(() => { if (isAppReady) loadContent(); }, [selectedCountry, mode, isAppReady]);

  const handleChannelSelect = (channel: Channel) => {
    setCurrentChannel(channel);
    setHistory(prev => [channel, ...prev.filter(c => c.id !== channel.id)].slice(0, 10));
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  if (!isAppReady) return (
    <div className="h-screen w-full bg-[#050508] flex flex-col items-center justify-center">
      <div className="w-12 h-12 border-4 border-cyan-500/20 border-t-cyan-500 rounded-full animate-spin mb-4"></div>
      <div className="text-cyan-500 font-mono text-xs animate-pulse tracking-[0.3em] uppercase">正在初始化核心系统...</div>
    </div>
  );

  const { styles } = currentTheme;

  return (
    <div className={`flex h-screen w-full ${styles.bgMain} ${styles.bgPattern} ${styles.font} overflow-hidden transition-colors duration-700 relative`}>
      <div className="bg-noise"></div>

      <Sidebar 
        countries={countries} selectedCountry={selectedCountry} onSelectCountry={setSelectedCountry}
        isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} mode={mode} onModeChange={setMode}
        themes={THEMES} currentTheme={currentTheme} onThemeChange={setCurrentTheme}
        favorites={favorites} onSelectFavorite={handleChannelSelect} history={history}
        onImportM3U={() => {}} settings={settings} onToggleSound={() => {}} reminders={reminders}
        onDeleteReminder={() => {}} onPlayReminder={() => {}}
      />

      <main className="flex-1 flex flex-col h-full min-w-0 relative z-10">
        <header className={`shrink-0 px-6 py-4 md:px-10 flex items-center justify-between border-b ${styles.border} ${styles.bgSidebar} backdrop-blur-3xl`}>
            <div className="flex items-center gap-5 min-w-0">
                <button onClick={() => setSidebarOpen(true)} className={`md:hidden p-2 rounded-xl hover:bg-white/10 ${styles.textMain}`}><Menu className="w-6 h-6" /></button>
                <div className="flex items-center gap-3 truncate">
                    <span className="text-3xl shrink-0">{selectedCountry?.flag}</span>
                    <h1 className={`text-xl md:text-2xl font-black truncate uppercase italic tracking-tighter ${styles.textMain}`}>
                        {selectedCountry?.name}
                    </h1>
                </div>
            </div>

            <div className="flex items-center gap-5 shrink-0 ml-4">
                <div className={`hidden sm:flex items-center gap-3 ${styles.card} px-5 py-2.5 ${styles.layoutShape} ${styles.shadow}`}>
                    <div className={`w-2 h-2 rounded-full animate-pulse`} style={{ backgroundColor: styles.accentColor }}></div>
                    <div className={`flex items-center gap-2 font-mono font-black ${styles.textMain}`}>
                        <Clock className="w-3.5 h-3.5 opacity-40" />
                        <span className="text-xs">{localTime}</span>
                    </div>
                </div>
                <button onClick={() => loadContent(true)} className={`p-2.5 rounded-full hover:bg-white/10 transition-all ${styles.textMain} ${loadingChannels ? 'animate-spin' : ''}`}>
                    <RefreshCw className="w-5 h-5" />
                </button>
            </div>
        </header>

        <div className={`flex-1 overflow-y-auto ${currentTheme.type === 'web95' ? 'scrollbar-web95' : 'scrollbar-thin'}`}>
            <section className="relative w-full px-4 md:px-10 py-8 max-w-[1600px] mx-auto">
                <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 md:gap-10 items-start">
                    {/* 核心播放区域 */}
                    <div className="lg:col-span-8 space-y-8 min-w-0">
                        <div className={`${styles.shadow} ${styles.layoutShape} overflow-hidden border ${styles.border} bg-black ring-1 ring-white/5`}>
                          <VideoPlayer 
                              channel={currentChannel} country={selectedCountry} theme={currentTheme}
                              isFavorite={!!currentChannel && favorites.some(f => f.id === currentChannel.id)}
                              onToggleFavorite={() => {}} onAddReminder={() => {}}
                          />
                        </div>
                        <FavoritesBar favorites={favorites} currentChannel={currentChannel} onSelectChannel={handleChannelSelect} theme={currentTheme} mode={mode} />
                    </div>

                    {/* 状态看板 Bento Boxes */}
                    <div className="lg:col-span-4 space-y-6 min-w-0 overflow-hidden">
                        <div className={`${styles.card} p-8 ${styles.layoutShape} ${styles.shadow} relative overflow-hidden group min-w-0`}>
                            <h3 className={`text-[10px] font-black uppercase tracking-[0.3em] mb-6 opacity-40 ${styles.textMain}`}>实时电台信息</h3>
                            <div className="space-y-6 min-w-0">
                                <div className="flex justify-between items-center gap-4 min-w-0">
                                    <span className={`${styles.textDim} font-bold text-xs uppercase shrink-0`}>可用流节点</span>
                                    <span className={`${styles.textMain} font-black text-xl truncate`}>{channels.length} Nodes</span>
                                </div>
                                <div className="flex justify-between items-center gap-4 min-w-0">
                                    <span className={`${styles.textDim} font-bold text-xs uppercase shrink-0`}>当前时区</span>
                                    <span className={`font-mono font-black text-sm truncate ${styles.textMain}`} style={{ color: styles.accentColor }}>
                                      GMT {(new Date().getTimezoneOffset() / -60) > 0 ? '+' : ''}{new Date().getTimezoneOffset() / -60}
                                    </span>
                                </div>
                            </div>
                        </div>

                        <button onClick={() => handleChannelSelect(channels[Math.floor(Math.random()*channels.length)])} 
                                className={`w-full py-6 ${styles.buttonPrimary} ${styles.layoutShape} ${styles.shadow} flex items-center justify-center gap-4 transition-all active:scale-95 group overflow-hidden`}>
                            <Shuffle className="w-5 h-5 group-hover:rotate-180 transition-transform duration-500" />
                            <span className="text-xs font-black uppercase tracking-widest truncate">随机漫游频道</span>
                        </button>

                        <div className={`${styles.card} p-8 ${styles.layoutShape} ${styles.shadow} min-w-0`}>
                            <h3 className={`text-[10px] font-black uppercase tracking-[0.3em] mb-6 opacity-40 ${styles.textMain} flex items-center gap-2`}>
                                <History className="w-3.5 h-3.5" /> 最近播放足迹
                            </h3>
                            <div className="space-y-4 min-w-0">
                                {history.length > 0 ? history.map(h => (
                                    <div key={h.id} onClick={() => handleChannelSelect(h)} className={`flex items-center gap-4 p-3 hover:bg-white/5 rounded-xl cursor-pointer group transition-all min-w-0`}>
                                        <div className={`w-10 h-10 rounded-lg bg-black/40 flex items-center justify-center shrink-0 overflow-hidden border ${styles.border} group-hover:scale-105 transition-transform`}>
                                            {h.logo ? <img src={h.logo} className="w-full h-full object-contain p-1" alt="" /> : <Tv className="w-4 h-4 opacity-20" />}
                                        </div>
                                        <div className="flex flex-col min-w-0 flex-1">
                                          <span className={`font-black truncate text-xs uppercase ${styles.textMain}`}>{h.name}</span>
                                          <span className="text-[9px] text-gray-600 font-bold uppercase truncate tracking-tight">{h.group || '通用信号'}</span>
                                        </div>
                                        <ChevronRight className={`w-3 h-3 ${styles.textDim} opacity-0 group-hover:opacity-100 -translate-x-2 group-hover:translate-x-0 transition-all`} />
                                    </div>
                                )) : <p className={`text-xs italic opacity-30 ${styles.textMain} py-4`}>暂无最近足迹</p>}
