import React, { useEffect, useRef, useState, useCallback } from 'react';
import Hls from 'hls.js';
import { Play, RefreshCw, Square, Star, Volume2, VolumeX, Maximize, Clock, Zap, Circle, Download } from 'lucide-react';
import { AppTheme, Channel, Country } from '../types';

interface VideoPlayerProps {
  channel: Channel | null;
  country: Country | null; 
  theme: AppTheme;
  isFavorite: boolean;
  onToggleFavorite: () => void;
}

export const VideoPlayer: React.FC<VideoPlayerProps> = ({ 
    channel, country, theme, isFavorite, onToggleFavorite
}) => {
  const [activePlayerIndex, setActivePlayerIndex] = useState(0);
  const videoRefs = [useRef<HTMLVideoElement>(null), useRef<HTMLVideoElement>(null)];
  const hlsRefs = useRef<(Hls | null)[]>([null, null]);
  const [loading, setLoading] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isMuted, setIsMuted] = useState(false);

  // 录屏相关状态
  const [isRecording, setIsRecording] = useState(false);
  const [recordingDuration, setRecordingDuration] = useState(0);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);
  const timerRef = useRef<number | null>(null);

  useEffect(() => {
    const url = channel?.url;
    if (!url) return;

    // 切换频道时停止当前录制
    if (isRecording) stopRecording();

    setLoading(true);
    const nextIndex = (activePlayerIndex + 1) % 2;
    const nextVideo = videoRefs[nextIndex].current;
    if (!nextVideo) return;

    if (hlsRefs.current[nextIndex]) {
        hlsRefs.current[nextIndex]?.destroy();
    }

    if (url.includes('.m3u8') && Hls.isSupported()) {
      const hls = new Hls();
      hlsRefs.current[nextIndex] = hls;
      hls.loadSource(url);
      hls.attachMedia(nextVideo);
      hls.on(Hls.Events.MANIFEST_PARSED, () => {
        nextVideo.play().catch(() => {});
        setLoading(false);
        setIsPlaying(true);
        setActivePlayerIndex(nextIndex);
      });
    } else {
      nextVideo.src = url;
      nextVideo.play().catch(() => {});
      setLoading(false);
      setIsPlaying(true);
      setActivePlayerIndex(nextIndex);
    }
  }, [channel?.url]);

  // 录屏逻辑
  const startRecording = () => {
    const video = videoRefs[activePlayerIndex].current;
    if (!video) return;

    try {
      // 从视频元素获取流
      const stream = (video as any).captureStream ? (video as any).captureStream() : (video as any).mozCaptureStream ? (video as any).mozCaptureStream() : null;
      if (!stream) {
        alert("当前浏览器不支持视频采集录制");
        return;
      }

      const recorder = new MediaRecorder(stream, { mimeType: 'video/webm;codecs=vp9,opus' });
      mediaRecorderRef.current = recorder;
      chunksRef.current = [];

      recorder.ondataavailable = (e) => {
        if (e.data.size > 0) chunksRef.current.push(e.data);
      };

      recorder.onstop = () => {
        const blob = new Blob(chunksRef.current, { type: 'video/webm' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `LiveHub_Record_${channel?.name || 'video'}_${new Date().getTime()}.webm`;
        a.click();
        URL.revokeObjectURL(url);
      };

      recorder.start();
      setIsRecording(true);
      setRecordingDuration(0);

      timerRef.current = window.setInterval(() => {
        setRecordingDuration(prev => prev + 1);
      }, 1000);
    } catch (err) {
      console.error("录制失败:", err);
      alert("录制启动失败，请确保频道已成功加载且浏览器版本支持。");
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      if (timerRef.current) clearInterval(timerRef.current);
    }
  };

  const formatDuration = (sec: number) => {
    const mins = Math.floor(sec / 60);
    const s = sec % 60;
    return `${mins.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  return (
    <div className="relative w-full group">
      {/* Ambilight 流光溢彩背景 */}
      <div className="absolute inset-0 -m-8 bg-cyan-500/10 blur-[80px] opacity-0 group-hover:opacity-100 transition-opacity duration-1000 pointer-events-none"></div>

      <div className="relative w-full aspect-video bg-black rounded-3xl overflow-hidden border border-white/10 shadow-[0_30px_100px_rgba(0,0,0,0.8)]">
        {[0, 1].map((index) => (
            <video
                key={index} ref={videoRefs[index]} playsInline muted={isMuted}
                className={`absolute inset-0 w-full h-full object-contain transition-opacity duration-1000 ${activePlayerIndex === index ? 'opacity-100' : 'opacity-0'}`}
            />
        ))}

        {/* 录制状态指示器 */}
        {isRecording && (
          <div className="absolute top-6 left-6 z-40 flex items-center gap-3 bg-black/40 backdrop-blur-md px-4 py-2 rounded-full border border-red-500/30 animate-in fade-in zoom-in duration-300">
             <div className="w-2.5 h-2.5 bg-red-600 rounded-full animate-pulse shadow-[0_0_10px_rgba(220,38,38,0.8)]"></div>
             <span className="text-white text-[10px] font-black tracking-widest uppercase">正在录制 / REC</span>
             <span className="text-red-400 font-mono text-xs font-bold border-l border-white/10 pl-3">{formatDuration(recordingDuration)}</span>
          </div>
        )}

        {loading && (
             <div className="absolute inset-0 flex items-center justify-center bg-black/60 backdrop-blur-sm z-20">
                <RefreshCw className="w-10 h-10 text-cyan-400 animate-spin" />
             </div>
        )}

        {/* 隐藏式控制栏 */}
        <div className="absolute inset-x-0 bottom-0 p-8 bg-gradient-to-t from-black via-black/40 to-transparent opacity-0 group-hover:opacity-100 transition-all duration-500 translate-y-4 group-hover:translate-y-0 z-30">
            <div className="flex items-center justify-between">
                <div className="flex items-center gap-6">
                    <button onClick={() => {
                        const v = videoRefs[activePlayerIndex].current;
                        if (isPlaying) v?.pause(); else v?.play();
                        setIsPlaying(!isPlaying);
                    }} className="w-14 h-14 bg-white text-black rounded-full flex items-center justify-center transition-transform hover:scale-110 active:scale-95 shadow-xl">
                        {isPlaying ? <Square className="w-5 h-5 fill-current" /> : <Play className="w-5 h-5 fill-current ml-1" />}
                    </button>
                    <div>
                        <h4 className="text-white font-black text-lg tracking-tight truncate max-w-[200px] md:max-w-md">{channel?.name || '等待选台中...'}</h4>
                        <div className="flex items-center gap-2 text-cyan-400 text-xs font-black uppercase tracking-widest">
                            <Zap className="w-3 h-3 fill-current" /> 信号已同步
                        </div>
                    </div>
                </div>

                <div className="flex items-center gap-3">
                    {/* 录屏按钮 */}
                    <button 
                        onClick={isRecording ? stopRecording : startRecording}
                        className={`p-3.5 rounded-xl transition-all flex items-center gap-2 ${isRecording ? 'bg-red-600 text-white shadow-[0_0_20px_rgba(220,38,38,0.4)]' : 'bg-white/10 hover:bg-white/20 text-white'}`}
                        title={isRecording ? "停止录制并保存" : "开始录制画面"}
                    >
                        <Circle className={`w-5 h-5 ${isRecording ? 'fill-current animate-pulse' : ''}`} />
                        {isRecording && <span className="text-[10px] font-black uppercase">停止录制</span>}
                    </button>

                    <button onClick={() => setIsMuted(!isMuted)} className="p-3.5 bg-white/10 hover:bg-white/20 rounded-xl text-white transition-colors" title={isMuted ? "取消静音" : "静音"}>
                        {isMuted ? <VolumeX className="w-5 h-5" /> : <Volume2 className="w-5 h-5" />}
                    </button>
                    <button onClick={() => videoRefs[activePlayerIndex].current?.requestFullscreen()} className="p-3.5 bg-white/10 hover:bg-white/20 rounded-xl text-white transition-colors" title="全屏观看">
                        <Maximize className="w-5 h-5" />
                    </button>
                </div>
            </div>
        </div>
      </div>
    </div>
