      });

      hls.on(Hls.Events.ERROR, (event, data) => {
        if (data.fatal) {
            console.error(`HLS 致命错误 (${data.type}):`, data.details);

            if (retryCountRef.current < MAX_RETRIES) {
                retryCountRef.current++;
                console.log(`正在进行第 ${retryCountRef.current} 次尝试重连...`);
                switch (data.type) {
                    case Hls.ErrorTypes.NETWORK_ERROR:
                        hls.startLoad();
                        break;
                    case Hls.ErrorTypes.MEDIA_ERROR:
                        hls.recoverMediaError();
                        break;
                    default:
                        setErrorState('fatal');
                        setLoading(false);
                        break;
                }
            } else {
                setErrorState(data.type === Hls.ErrorTypes.NETWORK_ERROR ? 'network' : 'fatal');
                setLoading(false);
                if (loadTimeoutRef.current) clearTimeout(loadTimeoutRef.current);
                hls.destroy();
            }
        }
      });
    } else {
      nextVideo.src = url;
      nextVideo.oncanplay = () => {
        if (loadTimeoutRef.current) clearTimeout(loadTimeoutRef.current);
        nextVideo.play().catch(() => {});
        setLoading(false);
        setIsPlaying(true);
        setErrorState('none');
        setActivePlayerIndex(nextIndex);
      };
      nextVideo.onerror = () => {
        setErrorState('network');
        setLoading(false);
      };
    }

    return () => {
        if (loadTimeoutRef.current) clearTimeout(loadTimeoutRef.current);
    };
  }, [channel?.url]);

  const startRecording = () => {
    const video = videoRefs[activePlayerIndex].current;
    if (!video || errorState !== 'none') return;
    try {
      const stream = (video as any).captureStream ? (video as any).captureStream() : (video as any).mozCaptureStream ? (video as any).mozCaptureStream() : null;
      if (!stream) return;
      const recorder = new MediaRecorder(stream, { mimeType: 'video/webm;codecs=vp9,opus' });
      mediaRecorderRef.current = recorder;
      chunksRef.current = [];
      recorder.ondataavailable = (e) => { if (e.data.size > 0) chunksRef.current.push(e.data); };
      recorder.onstop = () => {
        const blob = new Blob(chunksRef.current, { type: 'video/webm' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `Live_Record_${channel?.name}_${new Date().getTime()}.webm`;
        a.click();
      };
      recorder.start();
      setIsRecording(true);
      setRecordingDuration(0);
      recordingTimerRef.current = window.setInterval(() => setRecordingDuration(p => p + 1), 1000);
    } catch (err) {}
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      if (recordingTimerRef.current) clearInterval(recordingTimerRef.current);
    }
  };

  const { styles } = theme;

  return (
    <div className="relative w-full group select-none">
      <div className="absolute inset-0 -m-8 bg-cyan-500/5 blur-[100px] opacity-0 group-hover:opacity-100 transition-opacity duration-1000 pointer-events-none"></div>

      <div className={`relative w-full aspect-video bg-[#0a0a0a] rounded-3xl overflow-hidden border ${styles.border} shadow-[0_30px_100px_rgba(0,0,0,0.8)]`}>

        {/* 增强型错误反馈 UI */}
        {errorState !== 'none' && (
            <div className="absolute inset-0 z-40 flex flex-col items-center justify-center text-center p-10 bg-black/80 backdrop-blur-md">
                <div className="absolute inset-0 opacity-10 pointer-events-none overflow-hidden">
                    <div className="w-full h-full bg-[url('https://media.giphy.com/media/oEI9uWUeez9BK/giphy.gif')] bg-cover opacity-30 grayscale"></div>
                </div>
                <div className="relative z-10 flex flex-col items-center space-y-6 animate-in fade-in zoom-in duration-500">
                    <div className="w-20 h-20 rounded-full bg-white/5 flex items-center justify-center border border-white/10 shadow-[0_0_30px_rgba(245,158,11,0.2)]">
                        {errorState === 'network' ? <WifiOff className="w-10 h-10 text-amber-500" /> : <AlertTriangle className="w-10 h-10 text-red-500" />}
                    </div>
                    <div>
                        <h3 className="text-white font-black text-2xl uppercase italic tracking-tighter">
                            {errorState === 'network' ? '网络连接受阻' : errorState === 'timeout' ? '信号握手超时' : '该频率信号已丢失'}
                        </h3>
                        <p className="text-gray-400 text-xs mt-3 max-w-sm mx-auto leading-relaxed">
                            可能原因：该频道已下线、当前 IP 处于封锁区、或浏览器 CORS 跨域策略拦截。建议检查网络或使用「随机跳台」寻找可用信号。
                        </p>
                    </div>
                    <div className="flex gap-4">
                        <button 
