                        <button 
                            onClick={onAutoSkip} 
                            className="px-6 py-3 bg-white/5 text-white text-[10px] font-black uppercase rounded-full border border-white/10 hover:bg-white/10 transition-all flex items-center gap-2 active:scale-95"
                        >
                            <Shuffle className="w-3.5 h-3.5" /> 随机跳台
                        </button>
                    </div>
                </div>
            </div>
        )}

        {[0, 1].map((index) => (
            <video
                key={index} ref={videoRefs[index]} playsInline muted={isMuted}
                className={`absolute inset-0 w-full h-full object-contain transition-opacity duration-1000 ${activePlayerIndex === index && errorState === 'none' ? 'opacity-100' : 'opacity-0'}`}
            />
        ))}

        {/* 录制状态指示器 */}
        {isRecording && errorState === 'none' && (
          <div className="absolute top-6 left-6 z-40 flex items-center gap-3 bg-black/60 backdrop-blur-xl px-4 py-2 rounded-full border border-red-500/30">
             <div className="w-2.5 h-2.5 bg-red-600 rounded-full animate-pulse shadow-[0_0_15px_rgba(220,38,38,1)]"></div>
             <span className="text-white text-[10px] font-black tracking-widest uppercase">REC</span>
             <span className="text-red-400 font-mono text-xs font-bold border-l border-white/10 pl-3">
                 {Math.floor(recordingDuration/60).toString().padStart(2,'0')}:{(recordingDuration%60).toString().padStart(2,'0')}
             </span>
          </div>
        )}

        {loading && errorState === 'none' && (
             <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/60 backdrop-blur-md z-20 space-y-4">
                <div className="relative w-16 h-16">
                    <div className="absolute inset-0 border-4 border-cyan-500/20 rounded-full"></div>
                    <div className="absolute inset-0 border-4 border-t-cyan-500 rounded-full animate-spin"></div>
                </div>
                <div className="text-[10px] text-cyan-500 font-mono font-black uppercase tracking-[0.3em] animate-pulse">
                    正在捕获全球信号...
                </div>
             </div>
        )}

        {/* 控制面板 */}
        <div className={`absolute inset-x-0 bottom-0 p-8 bg-gradient-to-t from-black via-black/60 to-transparent transition-all duration-700 ${errorState !== 'none' ? 'opacity-20 pointer-events-none translate-y-4' : 'opacity-0 group-hover:opacity-100'}`}>
            <div className="flex flex-col md:flex-row items-center justify-between gap-4">
                <div className="flex items-center gap-6">
                    <button onClick={() => {
                        const v = videoRefs[activePlayerIndex].current;
                        if (isPlaying) v?.pause(); else v?.play();
                        setIsPlaying(!isPlaying);
                    }} className="w-14 h-14 bg-white text-black rounded-full flex items-center justify-center transition-all hover:scale-110 active:scale-95 shadow-2xl">
                        {isPlaying ? <Square className="w-5 h-5 fill-current" /> : <Play className="w-5 h-5 fill-current ml-1" />}
                    </button>
                    <div className="min-w-0">
                        <div className="flex items-center gap-2 mb-1">
                            <span className="px-2 py-0.5 bg-cyan-500 text-[9px] font-black text-black rounded-sm uppercase tracking-tighter">LIVE</span>
                            <h4 className="text-white font-black text-lg tracking-tight truncate max-w-[150px] md:max-w-md uppercase italic">
                                {channel?.name || '等待选台中...'}
                            </h4>
                        </div>
                        <div className="flex items-center gap-2 text-gray-500 text-[10px] font-bold uppercase tracking-widest">
                            <Zap className="w-3 h-3 text-cyan-400 fill-current" /> 
                            {channel?.group || '全球通用信道'} • {country?.name || '未知地域'}
                        </div>
                    </div>
                </div>

                <div className="flex items-center gap-3">
                    {/* 录制按钮 */}
                    <button onClick={isRecording ? stopRecording : startRecording} className={`p-3.5 rounded-xl transition-all ${isRecording ? 'bg-red-600 text-white shadow-[0_0_15px_rgba(220,38,38,0.3)]' : 'bg-white/10 text-white hover:bg-white/20'}`}>
                        <Circle className={`w-5 h-5 ${isRecording ? 'fill-current animate-pulse' : ''}`} />
                    </button>

                    {/* 音量滑块组合 */}
                    <div className="flex items-center group/vol">
                      <button onClick={() => setIsMuted(!isMuted)} className="p-3.5 bg-white/10 hover:bg-white/20 rounded-xl text-white transition-colors" title={isMuted ? "取消静音" : "静音"}>
                          {isMuted || volume === 0 ? <VolumeX className="w-5 h-5 text-red-400" /> : <Volume2 className="w-5 h-5" />}
                      </button>
                      <div className="w-0 overflow-hidden group-hover/vol:w-28 group-hover/vol:ml-3 transition-all duration-500 flex items-center">
                          <input 
                              type="range" min="0" max="1" step="0.01" 
                              value={isMuted ? 0 : volume}
                              onChange={(e) => {
                                  const v = parseFloat(e.target.value);
                                  setVolume(v);
                                  if (v > 0) setIsMuted(false);
                              }}
                              className="w-24 h-1.5 accent-cyan-500 bg-white/20 rounded-full appearance-none cursor-pointer"
                          />
                      </div>
                    </div>

                    <button onClick={() => videoRefs[activePlayerIndex].current?.requestFullscreen()} className="p-3.5 bg-white/10 hover:bg-white/20 rounded-xl text-white transition-colors">
                        <Maximize className="w-5 h-5" />
                    </button>
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useEffect, useRef, useState, useCallback } from 'react';
import Hls from 'hls.js';
import { Play, RefreshCw, Square, Star, Volume2, VolumeX, Maximize, Clock, Zap, Circle, AlertTriangle, Shuffle, WifiOff, Globe } from 'lucide-react';
import { AppTheme, Channel, Country } from '../types';

interface VideoPlayerProps {
  channel: Channel | null;
  country: Country | null; 
  theme: AppTheme;
  isFavorite: boolean;
  onToggleFavorite: () => void;
  onAutoSkip?: () => void; // 自动跳台回调
}

export const VideoPlayer: React.FC<VideoPlayerProps> = ({ 
    channel, country, theme, isFavorite, onToggleFavorite, onAutoSkip
}) => {
  const [activePlayerIndex, setActivePlayerIndex] = useState(0);
  const videoRefs = [useRef<HTMLVideoElement>(null), useRef<HTMLVideoElement>(null)];
  const hlsRefs = useRef<(Hls | null)[]>([null, null]);

  const [loading, setLoading] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const [volume, setVolume] = useState(1);
  const [errorState, setErrorState] = useState<'none' | 'timeout' | 'fatal' | 'network'>('none');
  const [errorDetail, setErrorDetail] = useState<string>('');
  const retryCountRef = useRef(0);
  const MAX_RETRIES = 3;

  // 录屏相关状态
  const [isRecording, setIsRecording] = useState(false);
  const [recordingDuration, setRecordingDuration] = useState(0);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);
  const recordingTimerRef = useRef<number | null>(null);

  // 超时监控
  const loadTimeoutRef = useRef<number | null>(null);

  const resetState = () => {
    setErrorState('none');
    setErrorDetail('');
    setLoading(true);
    retryCountRef.current = 0;
    if (loadTimeoutRef.current) clearTimeout(loadTimeoutRef.current);
  };

  // 同步音量到视频元素
  useEffect(() => {
    videoRefs.forEach(ref => {
      if (ref.current) {
        ref.current.volume = volume;
      }
    });
  }, [volume]);

  useEffect(() => {
    const url = channel?.url;
    if (!url) return;

    if (isRecording) stopRecording();
    resetState();

    const nextIndex = (activePlayerIndex + 1) % 2;
    const nextVideo = videoRefs[nextIndex].current;
    if (!nextVideo) return;

    // 清理旧实例
    if (hlsRefs.current[nextIndex]) {
        hlsRefs.current[nextIndex]?.destroy();
    }

    // 设置 15 秒加载超时
    loadTimeoutRef.current = window.setTimeout(() => {
        if (loading || !isPlaying) {
            setErrorState('timeout');
            setLoading(false);
        }
    }, 15000);

    if (url.includes('.m3u8') && Hls.isSupported()) {
      const hls = new Hls({
        maxBufferLength: 30,
        manifestLoadingTimeOut: 15000,
        levelLoadingTimeOut: 15000,
        manifestLoadingMaxRetry: 5,
        manifestLoadingRetryDelay: 2000, // 增加重试延迟
        levelLoadingMaxRetry: 5,
        enableWorker: true,
        xhrSetup: (xhr) => {
          xhr.withCredentials = false;
        }
      });
      hlsRefs.current[nextIndex] = hls;

      hls.loadSource(url);
      hls.attachMedia(nextVideo);

      hls.on(Hls.Events.MANIFEST_PARSED, () => {
        if (loadTimeoutRef.current) clearTimeout(loadTimeoutRef.current);
        nextVideo.play().catch(() => {});
        setLoading(false);
        setIsPlaying(true);
        setErrorState('none');
        setActivePlayerIndex(nextIndex);
        retryCountRef.current = 0;
      });

      hls.on(Hls.Events.ERROR, (event, data) => {
        if (data.fatal) {
            const detail = data.details || '';
            console.error(`HLS 致命错误 (${data.type}):`, detail);

            if (retryCountRef.current < MAX_RETRIES) {
                retryCountRef.current++;
                // 如果是 manifestLoadError，可能需要等待更久或特定的重试逻辑
                const delay = data.details === 'manifestLoadError' ? 2000 : 1000;

                setTimeout(() => {
                  if (!hlsRefs.current[nextIndex]) return;
                  switch (data.type) {
                      case Hls.ErrorTypes.NETWORK_ERROR:
                          hls.startLoad();
                          break;
                      case Hls.ErrorTypes.MEDIA_ERROR:
                          hls.recoverMediaError();
                          break;
                      default:
                          setErrorState('fatal');
                          setLoading(false);
                          break;
                  }
                }, delay);
            } else {
                setErrorState(data.type === Hls.ErrorTypes.NETWORK_ERROR ? 'network' : 'fatal');
                setErrorDetail(detail);
                setLoading(false);
                if (loadTimeoutRef.current) clearTimeout(loadTimeoutRef.current);
                hls.destroy();
            }
        }
      });
    } else {
      nextVideo.src = url;
      nextVideo.oncanplay = () => {
        if (loadTimeoutRef.current) clearTimeout(loadTimeoutRef.current);
        nextVideo.play().catch(() => {});
        setLoading(false);
        setIsPlaying(true);
        setErrorState('none');
        setActivePlayerIndex(nextIndex);
      };
      nextVideo.onerror = () => {
        setErrorState('network');
        setErrorDetail('Native video load error');
        setLoading(false);
      };
    }

    return () => {
        if (loadTimeoutRef.current) clearTimeout(loadTimeoutRef.current);
    };
  }, [channel?.url]);

  const startRecording = () => {
    const video = videoRefs[activePlayerIndex].current;
    if (!video || errorState !== 'none') return;
    try {
      const stream = (video as any).captureStream ? (video as any).captureStream() : (video as any).mozCaptureStream ? (video as any).mozCaptureStream() : null;
      if (!stream) return;
      const recorder = new MediaRecorder(stream, { mimeType: 'video/webm;codecs=vp9,opus' });
      mediaRecorderRef.current = recorder;
      chunksRef.current = [];
      recorder.ondataavailable = (e) => { if (e.data.size > 0) chunksRef.current.push(e.data); };
      recorder.onstop = () => {
        const blob = new Blob(chunksRef.current, { type: 'video/webm' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `Live_Record_${channel?.name}_${new Date().getTime()}.webm`;
        a.click();
      };
      recorder.start();
      setIsRecording(true);
      setRecordingDuration(0);
      recordingTimerRef.current = window.setInterval(() => setRecordingDuration(p => p + 1), 1000);
    } catch (err) {}
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      if (recordingTimerRef.current) clearInterval(recordingTimerRef.current);
    }
  };

  const { styles } = theme;

  const getErrorDisplay = () => {
      if (errorDetail === 'manifestLoadError') {
          return {
              title: '信道解析失败',
              desc: '当前直播源清单 (Manifest) 无法访问。这通常意味着该地址已被服务器关闭，或浏览器由于跨域 (CORS) 限制拦截了请求。'
          };
      }
      if (errorState === 'network') {
          return {
              title: '网络连接受阻',
              desc: '无法建立与直播服务器的连接。请检查您的网络环境，或尝试使用代理访问该地区的信号。'
          };
      }
      if (errorState === 'timeout') {
          return {
              title: '信号握手超时',
              desc: '服务器响应缓慢。直播流可能已经拥塞或由于地理位置过远导致延迟过高。'
          };
      }
      return {
          title: '频率信号丢失',
          desc: '该频率当前无法接收到有效载波。建议点击「随机跳台」寻找其他可用频道。'
      };
  };

  const display = getErrorDisplay();

  return (
    <div className="relative w-full group select-none">
      <div className="absolute inset-0 -m-8 bg-cyan-500/5 blur-[100px] opacity-0 group-hover:opacity-100 transition-opacity duration-1000 pointer-events-none"></div>

      <div className={`relative w-full aspect-video bg-[#0a0a0a] rounded-3xl overflow-hidden border ${styles.border} shadow-[0_30px_100px_rgba(0,0,0,0.8)]`}>

        {/* 增强型错误反馈 UI */}
        {errorState !== 'none' && (
            <div className="absolute inset-0 z-40 flex flex-col items-center justify-center text-center p-10 bg-black/85 backdrop-blur-xl">
                <div className="absolute inset-0 opacity-10 pointer-events-none overflow-hidden">
                    <div className="w-full h-full bg-[url('https://media.giphy.com/media/oEI9uWUeez9BK/giphy.gif')] bg-cover opacity-30 grayscale"></div>
                </div>
                <div className="relative z-10 flex flex-col items-center space-y-6 animate-in fade-in zoom-in duration-700">
                    <div className="w-24 h-24 rounded-full bg-white/5 flex items-center justify-center border border-white/10 shadow-[0_0_50px_rgba(6,182,212,0.15)] group/icon relative">
                        {errorDetail === 'manifestLoadError' ? <Globe className="w-12 h-12 text-cyan-400 animate-pulse" /> : errorState === 'network' ? <WifiOff className="w-12 h-12 text-amber-500" /> : <AlertTriangle className="w-12 h-12 text-red-500" />}
                        <div className="absolute -inset-2 rounded-full border border-white/5 animate-ping opacity-20"></div>
                    </div>
                    <div>
                        <h3 className="text-white font-black text-3xl uppercase italic tracking-tighter">
                            {display.title}
                        </h3>
                        <p className="text-gray-400 text-xs mt-4 max-w-sm mx-auto leading-relaxed font-medium">
                            {display.desc}
                        </p>
                        {errorDetail && (
                            <div className="mt-4 px-3 py-1 bg-white/5 rounded-md inline-block border border-white/10">
                                <span className="text-[10px] font-mono text-gray-500 uppercase tracking-tighter">DEBUG: {errorDetail}</span>
                            </div>
                        )}
                    </div>
                    <div className="flex gap-4 pt-4">
                        <button 
                            onClick={() => window.location.reload()} 
                            className="px-8 py-4 bg-white text-black text-[11px] font-black uppercase rounded-full hover:bg-cyan-400 transition-all shadow-2xl active:scale-95 flex items-center gap-2"
                        >
                            <RefreshCw className="w-3.5 h-3.5" /> 强制重连
                        </button>
                        <button 
                            onClick={onAutoSkip} 
                            className="px-8 py-4 bg-white/5 text-white text-[11px] font-black uppercase rounded-full border border-white/10 hover:bg-white/10 transition-all flex items-center gap-2 active:scale-95"
                        >
                            <Shuffle className="w-3.5 h-3.5" /> 随机跳台
                        </button>
                    </div>
                </div>
            </div>
        )}

        {[0, 1].map((index) => (
            <video
                key={index} ref={videoRefs[index]} playsInline muted={isMuted}
                className={`absolute inset-0 w-full h-full object-contain transition-opacity duration-1000 ${activePlayerIndex === index && errorState === 'none' ? 'opacity-100' : 'opacity-0'}`}
            />
        ))}

        {/* 录制状态指示器 */}
        {isRecording && errorState === 'none' && (
          <div className="absolute top-6 left-6 z-40 flex items-center gap-3 bg-black/60 backdrop-blur-xl px-4 py-2 rounded-full border border-red-500/30">
             <div className="w-2.5 h-2.5 bg-red-600 rounded-full animate-pulse shadow-[0_0_15px_rgba(220,38,38,1)]"></div>
             <span className="text-white text-[10px] font-black tracking-widest uppercase">REC</span>
             <span className="text-red-400 font-mono text-xs font-bold border-l border-white/10 pl-3">
                 {Math.floor(recordingDuration/60).toString().padStart(2,'0')}:{(recordingDuration%60).toString().padStart(2,'0')}
             </span>
          </div>
        )}

        {loading && errorState === 'none' && (
             <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/60 backdrop-blur-md z-20 space-y-4">
                <div className="relative w-16 h-16">
                    <div className="absolute inset-0 border-4 border-cyan-500/20 rounded-full"></div>
                    <div className="absolute inset-0 border-4 border-t-cyan-500 rounded-full animate-spin"></div>
                </div>
                <div className="text-[10px] text-cyan-500 font-mono font-black uppercase tracking-[0.3em] animate-pulse">
                    正在捕获全球信号...
                </div>
             </div>
        )}

        {/* 控制面板 */}
        <div className={`absolute inset-x-0 bottom-0 p-8 bg-gradient-to-t from-black via-black/60 to-transparent transition-all duration-700 ${errorState !== 'none' ? 'opacity-20 pointer-events-none translate-y-4' : 'opacity-0 group-hover:opacity-100'}`}>
            <div className="flex flex-col md:flex-row items-center justify-between gap-4">
                <div className="flex items-center gap-6">
                    <button onClick={() => {
                        const v = videoRefs[activePlayerIndex].current;
                        if (isPlaying) v?.pause(); else v?.play();
                        setIsPlaying(!isPlaying);
                    }} className="w-14 h-14 bg-white text-black rounded-full flex items-center justify-center transition-all hover:scale-110 active:scale-95 shadow-2xl">
                        {isPlaying ? <Square className="w-5 h-5 fill-current" /> : <Play className="w-5 h-5 fill-current ml-1" />}
                    </button>
                    <div className="min-w-0">
                        <div className="flex items-center gap-2 mb-1">
                            <span className="px-2 py-0.5 bg-cyan-500 text-[9px] font-black text-black rounded-sm uppercase tracking-tighter">LIVE</span>
                            <h4 className="text-white font-black text-lg tracking-tight truncate max-w-[150px] md:max-w-md uppercase italic">
                                {channel?.name || '等待选台中...'}
                            </h4>
                        </div>
                        <div className="flex items-center gap-2 text-gray-500 text-[10px] font-bold uppercase tracking-widest">
                            <Zap className="w-3 h-3 text-cyan-400 fill-current" /> 
                            {channel?.group || '全球通用信道'} • {country?.name || '未知地域'}
                        </div>
                    </div>
                </div>

                <div className="flex items-center gap-3">
                    {/* 录制按钮 */}
                    <button onClick={isRecording ? stopRecording : startRecording} className={`p-3.5 rounded-xl transition-all ${isRecording ? 'bg-red-600 text-white shadow-[0_0_15px_rgba(220,38,38,0.3)]' : 'bg-white/10 text-white hover:bg-white/20'}`}>
                        <Circle className={`w-5 h-5 ${isRecording ? 'fill-current animate-pulse' : ''}`} />
                    </button>

                    {/* 音量滑块组合 */}
                    <div className="flex items-center group/vol">
                      <button onClick={() => setIsMuted(!isMuted)} className="p-3.5 bg-white/10 hover:bg-white/20 rounded-xl text-white transition-colors" title={isMuted ? "取消静音" : "静音"}>
                          {isMuted || volume === 0 ? <VolumeX className="w-5 h-5 text-red-400" /> : <Volume2 className="w-5 h-5" />}
                      </button>
                      <div className="w-0 overflow-hidden group-hover/vol:w-28 group-hover/vol:ml-3 transition-all duration-500 flex items-center">
                          <input 
                              type="range" min="0" max="1" step="0.01" 
                              value={isMuted ? 0 : volume}
                              onChange={(e) => {
                                  const v = parseFloat(e.target.value);
                                  setVolume(v);
                                  if (v > 0) setIsMuted(false);
                              }}
                              className="w-24 h-1.5 accent-cyan-500 bg-white/20 rounded-full appearance-none cursor-pointer"
                          />
                      </div>
                    </div>

                    <button onClick={() => videoRefs[activePlayerIndex].current?.requestFullscreen()} className="p-3.5 bg-white/10 hover:bg-white/20 rounded-xl text-white transition-colors">
                        <Maximize className="w-5 h-5" />
                    </button>
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useEffect, useRef, useState, useCallback } from 'react';
import Hls from 'hls.js';
import { Play, RefreshCw, Square, Star, Volume2, VolumeX, Maximize, Clock, Zap, Circle, AlertTriangle, Shuffle, WifiOff, Globe, ShieldAlert } from 'lucide-react';
import { AppTheme, Channel, Country } from '../types';

interface VideoPlayerProps {
  channel: Channel | null;
  country: Country | null; 
  theme: AppTheme;
  isFavorite: boolean;
  onToggleFavorite: () => void;
  onAutoSkip?: () => void; // 自动跳台回调
}

export const VideoPlayer: React.FC<VideoPlayerProps> = ({ 
    channel, country, theme, isFavorite, onToggleFavorite, onAutoSkip
}) => {
  const [activePlayerIndex, setActivePlayerIndex] = useState(0);
  const videoRefs = [useRef<HTMLVideoElement>(null), useRef<HTMLVideoElement>(null)];
  const hlsRefs = useRef<(Hls | null)[]>([null, null]);

  const [loading, setLoading] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const [volume, setVolume] = useState(1);
  const [errorState, setErrorState] = useState<'none' | 'timeout' | 'fatal' | 'network'>('none');
  const [errorDetail, setErrorDetail] = useState<string>('');
  const retryCountRef = useRef(0);
  const MAX_RETRIES = 5; // 增加最大重试次数

  const [isRecording, setIsRecording] = useState(false);
  const [recordingDuration, setRecordingDuration] = useState(0);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);
  const recordingTimerRef = useRef<number | null>(null);

  const loadTimeoutRef = useRef<number | null>(null);

  const resetState = () => {
    setErrorState('none');
    setErrorDetail('');
    setLoading(true);
    retryCountRef.current = 0;
    if (loadTimeoutRef.current) clearTimeout(loadTimeoutRef.current);
  };

  useEffect(() => {
    videoRefs.forEach(ref => {
      if (ref.current) {
        ref.current.volume = volume;
      }
    });
  }, [volume]);

  useEffect(() => {
    const url = channel?.url;
    if (!url) return;

    if (isRecording) stopRecording();
    resetState();

    const nextIndex = (activePlayerIndex + 1) % 2;
    const nextVideo = videoRefs[nextIndex].current;
    if (!nextVideo) return;

    if (hlsRefs.current[nextIndex]) {
        hlsRefs.current[nextIndex]?.destroy();
    }

    // 设置更长的 20 秒加载超时
    loadTimeoutRef.current = window.setTimeout(() => {
        if (loading || !isPlaying) {
            setErrorState('timeout');
            setLoading(false);
        }
    }, 20000);

    if (url.includes('.m3u8') && Hls.isSupported()) {
      const hls = new Hls({
        maxBufferLength: 30,
        manifestLoadingTimeOut: 15000,
        manifestLoadingMaxRetry: 10, // 强化重试次数
        manifestLoadingRetryDelay: 1000,
        manifestLoadingMaxRetryTimeout: 64000,
        levelLoadingTimeOut: 15000,
        levelLoadingMaxRetry: 5,
        fragLoadingTimeOut: 20000,
        fragLoadingMaxRetry: 5,
        enableWorker: true,
        // 某些源需要特定的 xhr 配置来减少 manifestLoadError
        xhrSetup: (xhr, url) => {
          xhr.withCredentials = false;
        }
      });
      hlsRefs.current[nextIndex] = hls;

      hls.loadSource(url);
      hls.attachMedia(nextVideo);

      hls.on(Hls.Events.MANIFEST_PARSED, () => {
        if (loadTimeoutRef.current) clearTimeout(loadTimeoutRef.current);
        nextVideo.play().catch(() => {
            // 某些浏览器需要用户交互才能播放
            setIsPlaying(false);
        });
        setLoading(false);
        setIsPlaying(true);
        setErrorState('none');
        setActivePlayerIndex(nextIndex);
        retryCountRef.current = 0;
      });

      hls.on(Hls.Events.ERROR, (event, data) => {
        if (data.fatal) {
            const detail = data.details || '';
            console.error(`HLS ERROR [${data.type}]: ${detail}`, data);

            if (retryCountRef.current < MAX_RETRIES) {
                retryCountRef.current++;
                // 针对 manifestLoadError 引入指数退避
                const backoff = Math.pow(2, retryCountRef.current) * 500;

                setTimeout(() => {
                  if (!hlsRefs.current[nextIndex]) return;
                  switch (data.type) {
                      case Hls.ErrorTypes.NETWORK_ERROR:
                          console.log(`正在尝试第 ${retryCountRef.current} 次网络重连...`);
                          hls.startLoad();
                          break;
                      case Hls.ErrorTypes.MEDIA_ERROR:
                          hls.recoverMediaError();
                          break;
                      default:
                          setErrorState('fatal');
                          setLoading(false);
                          break;
                  }
                }, backoff);
            } else {
                setErrorState(data.type === Hls.ErrorTypes.NETWORK_ERROR ? 'network' : 'fatal');
                setErrorDetail(detail);
                setLoading(false);
                if (loadTimeoutRef.current) clearTimeout(loadTimeoutRef.current);
                hls.destroy();
            }
        }
      });
    } else {
      nextVideo.src = url;
      nextVideo.oncanplay = () => {
        if (loadTimeoutRef.current) clearTimeout(loadTimeoutRef.current);
        nextVideo.play().catch(() => { setIsPlaying(false); });
        setLoading(false);
        setIsPlaying(true);
        setErrorState('none');
        setActivePlayerIndex(nextIndex);
      };
      nextVideo.onerror = () => {
        setErrorState('network');
        setErrorDetail('Native video source failure');
        setLoading(false);
      };
    }

    return () => {
        if (loadTimeoutRef.current) clearTimeout(loadTimeoutRef.current);
    };
  }, [channel?.url]);

  const startRecording = () => {
    const video = videoRefs[activePlayerIndex].current;
    if (!video || errorState !== 'none') return;
    try {
      const stream = (video as any).captureStream ? (video as any).captureStream() : (video as any).mozCaptureStream ? (video as any).mozCaptureStream() : null;
      if (!stream) return;
      const recorder = new MediaRecorder(stream, { mimeType: 'video/webm;codecs=vp9,opus' });
      mediaRecorderRef.current = recorder;
      chunksRef.current = [];
      recorder.ondataavailable = (e) => { if (e.data.size > 0) chunksRef.current.push(e.data); };
      recorder.onstop = () => {
        const blob = new Blob(chunksRef.current, { type: 'video/webm' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `Live_Record_${channel?.name}_${new Date().getTime()}.webm`;
        a.click();
      };
      recorder.start();
      setIsRecording(true);
      setRecordingDuration(0);
      recordingTimerRef.current = window.setInterval(() => setRecordingDuration(p => p + 1), 1000);
    } catch (err) {}
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      if (recordingTimerRef.current) clearInterval(recordingTimerRef.current);
    }
  };

  const { styles } = theme;

  const getErrorDisplay = () => {
      if (errorDetail === 'manifestLoadError') {
          return {
              icon: <ShieldAlert className="w-12 h-12 text-rose-500" />,
              title: 'CORS 或 资源下线',
              desc: '直播服务器拒绝了连接请求 (manifestLoadError)。这通常是因为：1. 源地址已关闭；2. 跨域限制 (CORS)；3. 您当前所在地区的网络提供商拦截了该流地址。'
          };
      }
      if (errorState === 'network') {
          return {
              icon: <WifiOff className="w-12 h-12 text-amber-500" />,
              title: '主干节点响应失败',
              desc: '无法建立与目标服务器的有效握手。请检查本地网络连接，或尝试更换至其他节点频道。'
          };
      }
      if (errorState === 'timeout') {
          return {
              icon: <Clock className="w-12 h-12 text-cyan-500 animate-pulse" />,
              title: '信号握手超时',
              desc: '服务器响应时间过长，流媒体清单无法按时下载。该信道目前可能因并发过高而发生拥堵。'
          };
      }
      return {
          icon: <AlertTriangle className="w-12 h-12 text-red-500" />,
          title: '频率信号丢失',
          desc: '该频率当前无法接收到有效载波。建议点击「随机跳台」寻找其他可用频道。'
      };
  };

  const display = getErrorDisplay();

  return (
    <div className="relative w-full group select-none">
      <div className="absolute inset-0 -m-8 bg-cyan-500/5 blur-[100px] opacity-0 group-hover:opacity-100 transition-opacity duration-1000 pointer-events-none"></div>

      <div className={`relative w-full aspect-video bg-[#0a0a0a] rounded-3xl overflow-hidden border ${styles.border} shadow-[0_30px_100px_rgba(0,0,0,0.8)]`}>

        {/* 增强型自愈与错误反馈 UI */}
        {errorState !== 'none' && (
            <div className="absolute inset-0 z-40 flex flex-col items-center justify-center text-center p-10 bg-black/90 backdrop-blur-2xl">
                <div className="absolute inset-0 opacity-10 pointer-events-none overflow-hidden">
                    <div className="w-full h-full bg-[url('https://media.giphy.com/media/oEI9uWUeez9BK/giphy.gif')] bg-cover opacity-20 grayscale scale-150"></div>
                </div>
                <div className="relative z-10 flex flex-col items-center space-y-6 animate-in fade-in zoom-in slide-in-from-bottom-4 duration-700">
                    <div className="w-24 h-24 rounded-full bg-white/5 flex items-center justify-center border border-white/10 shadow-[0_0_60px_rgba(244,63,94,0.1)] group/icon relative">
                        {display.icon}
                        <div className="absolute -inset-4 rounded-full border border-white/5 animate-pulse opacity-20"></div>
                    </div>
                    <div>
                        <h3 className="text-white font-black text-3xl uppercase italic tracking-tighter">
                            {display.title}
                        </h3>
                        <p className="text-gray-400 text-xs mt-4 max-w-sm mx-auto leading-relaxed font-bold opacity-80">
                            {display.desc}
                        </p>
                        <div className="mt-6 flex flex-wrap justify-center gap-2">
                             <div className="px-3 py-1 bg-white/5 rounded-md border border-white/10 flex items-center gap-2">
                                <span className="w-1.5 h-1.5 rounded-full bg-red-500"></span>
                                <span className="text-[10px] font-mono text-gray-500 uppercase tracking-tighter">STATUS: ERROR</span>
                            </div>
                            <div className="px-3 py-1 bg-white/5 rounded-md border border-white/10 flex items-center gap-2">
                                <span className="text-[10px] font-mono text-gray-500 uppercase tracking-tighter">HEX: {errorDetail || '0xNETWORK'}</span>
                            </div>
                        </div>
                    </div>
                    <div className="flex flex-col sm:flex-row gap-4 pt-6">
                        <button 
                            onClick={() => window.location.reload()} 
                            className="px-10 py-4 bg-white text-black text-[11px] font-black uppercase rounded-full hover:bg-cyan-400 transition-all shadow-[0_10px_30px_rgba(255,255,255,0.1)] active:scale-95 flex items-center justify-center gap-2"
                        >
                            <RefreshCw className="w-3.5 h-3.5" /> 强制重连信道
                        </button>
                        <button 
                            onClick={onAutoSkip} 
                            className="px-10 py-4 bg-white/5 text-white text-[11px] font-black uppercase rounded-full border border-white/10 hover:bg-white/10 transition-all flex items-center justify-center gap-2 active:scale-95"
                        >
                            <Shuffle className="w-3.5 h-3.5" /> 尝试其他频率
                        </button>
                    </div>
                </div>
            </div>
        )}

        {[0, 1].map((index) => (
            <video
                key={index} ref={videoRefs[index]} playsInline muted={isMuted}
                className={`absolute inset-0 w-full h-full object-contain transition-opacity duration-1000 ${activePlayerIndex === index && errorState === 'none' ? 'opacity-100' : 'opacity-0'}`}
            />
        ))}

        {/* 录制状态指示器 */}
        {isRecording && errorState === 'none' && (
          <div className="absolute top-6 left-6 z-40 flex items-center gap-3 bg-black/60 backdrop-blur-xl px-4 py-2 rounded-full border border-red-500/30">
             <div className="w-2.5 h-2.5 bg-red-600 rounded-full animate-pulse shadow-[0_0_15px_rgba(220,38,38,1)]"></div>
             <span className="text-white text-[10px] font-black tracking-widest uppercase">REC</span>
             <span className="text-red-400 font-mono text-xs font-bold border-l border-white/10 pl-3">
                 {Math.floor(recordingDuration/60).toString().padStart(2,'0')}:{(recordingDuration%60).toString().padStart(2,'0')}
             </span>
          </div>
        )}

        {loading && errorState === 'none' && (
             <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/60 backdrop-blur-md z-20 space-y-4">
                <div className="relative w-16 h-16">
                    <div className="absolute inset-0 border-4 border-cyan-500/20 rounded-full"></div>
                    <div className="absolute inset-0 border-4 border-t-cyan-500 rounded-full animate-spin"></div>
                </div>
                <div className="text-[10px] text-cyan-500 font-mono font-black uppercase tracking-[0.3em] animate-pulse">
                    正在捕获全球信号...
                </div>
             </div>
        )}

        {/* 控制面板 */}
        <div className={`absolute inset-x-0 bottom-0 p-8 bg-gradient-to-t from-black via-black/60 to-transparent transition-all duration-700 ${errorState !== 'none' ? 'opacity-20 pointer-events-none translate-y-4' : 'opacity-0 group-hover:opacity-100'}`}>
            <div className="flex flex-col md:flex-row items-center justify-between gap-4">
                <div className="flex items-center gap-6">
                    <button onClick={() => {
                        const v = videoRefs[activePlayerIndex].current;
                        if (isPlaying) v?.pause(); else v?.play();
                        setIsPlaying(!isPlaying);
                    }} className="w-14 h-14 bg-white text-black rounded-full flex items-center justify-center transition-all hover:scale-110 active:scale-95 shadow-2xl">
                        {isPlaying ? <Square className="w-5 h-5 fill-current" /> : <Play className="w-5 h-5 fill-current ml-1" />}
                    </button>
                    <div className="min-w-0">
                        <div className="flex items-center gap-2 mb-1">
                            <span className="px-2 py-0.5 bg-cyan-500 text-[9px] font-black text-black rounded-sm uppercase tracking-tighter">LIVE</span>
                            <h4 className="text-white font-black text-lg tracking-tight truncate max-w-[150px] md:max-w-md uppercase italic">
                                {channel?.name || '等待选台中...'}
                            </h4>
                        </div>
                        <div className="flex items-center gap-2 text-gray-500 text-[10px] font-bold uppercase tracking-widest">
                            <Zap className="w-3 h-3 text-cyan-400 fill-current" /> 
                            {channel?.group || '全球通用信道'} • {country?.name || '未知地域'}
                        </div>
                    </div>
                </div>

                <div className="flex items-center gap-3">
                    {/* 录制按钮 */}
                    <button onClick={isRecording ? stopRecording : startRecording} className={`p-3.5 rounded-xl transition-all ${isRecording ? 'bg-red-600 text-white shadow-[0_0_15px_rgba(220,38,38,0.3)]' : 'bg-white/10 text-white hover:bg-white/20'}`}>
                        <Circle className={`w-5 h-5 ${isRecording ? 'fill-current animate-pulse' : ''}`} />
                    </button>

                    {/* 音量滑块组合 */}
                    <div className="flex items-center group/vol">
                      <button onClick={() => setIsMuted(!isMuted)} className="p-3.5 bg-white/10 hover:bg-white/20 rounded-xl text-white transition-colors" title={isMuted ? "取消静音" : "静音"}>
                          {isMuted || volume === 0 ? <VolumeX className="w-5 h-5 text-red-400" /> : <Volume2 className="w-5 h-5" />}
                      </button>
                      <div className="w-0 overflow-hidden group-hover/vol:w-28 group-hover/vol:ml-3 transition-all duration-500 flex items-center">
                          <input 
                              type="range" min="0" max="1" step="0.01" 
                              value={isMuted ? 0 : volume}
                              onChange={(e) => {
                                  const v = parseFloat(e.target.value);
                                  setVolume(v);
                                  if (v > 0) setIsMuted(false);
                              }}
                              className="w-24 h-1.5 accent-cyan-500 bg-white/20 rounded-full appearance-none cursor-pointer"
                          />
                      </div>
                    </div>

                    <button onClick={() => videoRefs[activePlayerIndex].current?.requestFullscreen()} className="p-3.5 bg-white/10 hover:bg-white/20 rounded-xl text-white transition-colors">
                        <Maximize className="w-5 h-5" />
                    </button>
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI } from "@google/genai";
import { AppTheme, PetType, ChatMessage, Channel } from '../types';
import { MessageCircle, X, Send, Bot, Cat, Dog, Rabbit, Sparkles, GripHorizontal } from 'lucide-react';

interface AiChatPetProps {
  theme: AppTheme;
  currentChannels: Channel[];
  onSelectChannel: (channel: Channel) => void;
}

export const AiChatPet: React.FC<AiChatPetProps> = ({ theme, currentChannels, onSelectChannel }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [petType, setPetType] = useState<PetType>(() => (localStorage.getItem('ai_pet_type') as PetType) || null);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [inputText, setInputText] = useState('');
  const [loading, setLoading] = useState(false);

  // 拖拽相关状态
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const dragStartPos = useRef({ x: 0, y: 0 });
  const initialPos = useRef({ x: 0, y: 0 });

  const scrollRef = useRef<HTMLDivElement>(null);
  const { styles } = theme;

  useEffect(() => { if (petType) localStorage.setItem('ai_pet_type', petType); }, [petType]);
  useEffect(() => { if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight; }, [messages, isOpen]);

  // 拖拽逻辑处理
  const handleMouseDown = (e: React.MouseEvent) => {
    // 只有点击 Header 才能拖拽
    setIsDragging(true);
    dragStartPos.current = { x: e.clientX, y: e.clientY };
    initialPos.current = { ...position };

    // 防止文本选中
    e.preventDefault();
  };

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!isDragging) return;

      const dx = e.clientX - dragStartPos.current.x;
      const dy = e.clientY - dragStartPos.current.y;

      setPosition({
        x: initialPos.current.x + dx,
        y: initialPos.current.y + dy
      });
    };

    const handleMouseUp = () => {
      setIsDragging(false);
    };

    if (isDragging) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
    }

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isDragging]);

  const handleSend = async () => {
    if (!inputText.trim() || !petType) return;
    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', text: inputText };
    setMessages(prev => [...prev, userMsg]);
    setInputText('');
    setLoading(true);

    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        let systemInstruction = `你是一个虚拟电视伙伴 (${petType})。用户正在看电视。
        当前可用频道列表: ${currentChannels.slice(0, 50).map(c => c.name).join(', ')}。
        如果用户要求推荐或寻找内容，请在双方括号中提供频道名称，例如 [[频道名称]]。
        请始终使用中文回复，保持幽默且符合你的动物设定。`;

        if (petType === 'cat') systemInstruction += " 你是一只傲娇的小猫，喜欢挖苦但心肠不坏。";
        else if (petType === 'dog') systemInstruction += " 你是一只热情忠诚的小狗，超级兴奋。";
        else if (petType === 'bunny') systemInstruction += " 你是一只轻声细语、害羞的兔子。";

        const chat = ai.chats.create({ 
          model: 'gemini-3-flash-preview', 
          config: { systemInstruction } 
        });
        const result = await chat.sendMessage({ message: userMsg.text });
        const responseText = result.text;

        const match = responseText?.match(/\[\[(.*?)\]\]/);
        if (match) {
            const recommendedName = match[1];
            const channel = currentChannels.find(c => c.name.toLowerCase().includes(recommendedName.toLowerCase()));
            if (channel) {
                setMessages(prev => [...prev, {
                    id: Date.now().toString(),
                    role: 'model',
                    text: responseText.replace(/\[\[.*?\]\]/g, channel.name) + " (已为你找到该频道并自动切换)"
                }]);
                onSelectChannel(channel);
                setLoading(false);
                return;
            }
        }

        setMessages(prev => [...prev, { id: Date.now().toString(), role: 'model', text: responseText || "我没听清，能再说一次吗？喵/汪/嘘？" }]);
    } catch (e) {
        setMessages(prev => [...prev, { id: Date.now().toString(), role: 'model', text: "哎呀，我的大脑断网了... 稍后再试试吧。" }]);
    } finally {
        setLoading(false);
    }
  };

  const getPetIcon = (type: PetType, className: string) => {
      switch (type) {
          case 'cat': return <Cat className={className} />;
          case 'dog': return <Dog className={className} />;
          case 'bunny': return <Rabbit className={className} />;
          case 'robot': return <Bot className={className} />;
          default: return <Bot className={className} />;
      }
  };

  if (!isOpen) {
      return (
          <button 
            onClick={() => setIsOpen(true)} 
            className={`fixed top-24 right-8 w-16 h-16 rounded-3xl shadow-[0_20px_40px_rgba(0,0,0,0.4)] flex items-center justify-center z-50 transition-all hover:scale-110 active:scale-95 ${styles.buttonPrimary} text-white border-4 border-white/20`}
          >
              <div className="relative">
                {petType ? getPetIcon(petType, "w-9 h-9") : <MessageCircle className="w-9 h-9" />}
                <div className="absolute -top-1 -right-1 w-4 h-4 bg-red-500 rounded-full border-2 border-white animate-pulse"></div>
              </div>
          </button>
      );
  }

  return (
    <div 
      className={`fixed top-24 right-8 w-80 md:w-[400px] h-[600px] ${styles.layoutShape} shadow-[0_30px_60px_rgba(0,0,0,0.5)] z-50 flex flex-col overflow-hidden ${styles.border} ${styles.bgSidebar} backdrop-blur-3xl transition-all animate-in slide-in-from-right duration-500`}
      style={{
        transform: `translate3d(${position.x}px, ${position.y}px, 0)`,
        transition: isDragging ? 'none' : 'transform 0.1s ease-out'
      }}
    >
        {/* 可拖拽 Header */}
        <div 
          onMouseDown={handleMouseDown}
          className={`p-6 flex items-center justify-between border-b ${styles.border} cursor-grab active:cursor-grabbing hover:bg-white/5 transition-colors shrink-0 select-none`}
        >
             <div className={`flex items-center gap-3 ${styles.textMain} font-black uppercase tracking-widest text-xs`}>
                 <GripHorizontal className="w-4 h-4 opacity-30" />
                 <Sparkles className="w-4 h-4 text-yellow-400" />
                 <span>AI 智播助手 (中文)</span>
             </div>
             <button 
                onClick={(e) => { e.stopPropagation(); setIsOpen(false); }} 
                className={`p-2 rounded-full hover:bg-white/10 ${styles.textDim}`}
             >
                <X className="w-5 h-5" />
             </button>
        </div>

        <div className={`flex-1 overflow-y-auto p-6 space-y-6 ${theme.type === 'web95' ? 'bg-white' : ''} ${theme.type === 'web95' ? 'scrollbar-web95' : 'scrollbar-thin'}`} ref={scrollRef}>
            {!petType ? (
                <div className="h-full flex flex-col items-center justify-center text-center space-y-8 p-4">
                    <h3 className={`${styles.textMain} font-black text-2xl tracking-tight`}>选择你的 AI 伙伴</h3>
                    <div className="grid grid-cols-2 gap-5 w-full">
                        {(['cat', 'dog', 'bunny', 'robot'] as const).map(type => (
                            <button key={type} onClick={() => { setPetType(type); setMessages([{ id: 'init', role: 'model', text: `你好呀！我是你的${type === 'cat' ? '傲娇小猫' : type === 'dog' ? '忠诚狗狗' : type === 'bunny' ? '害羞兔子' : '智能助手'}。告诉我你想看什么类型的频道？` }]); }} className={`flex flex-col items-center gap-3 p-6 ${styles.card} ${styles.layoutShape} transition-all hover:scale-105 group`}>
                                {getPetIcon(type, "w-12 h-12 transition-transform group-hover:rotate-12")}
                                <span className="text-[10px] font-black uppercase tracking-widest">{type === 'cat' ? '小猫' : type === 'dog' ? '小狗' : type === 'bunny' ? '兔子' : '助手'}</span>
                            </button>
                        ))}
                    </div>
                </div>
            ) : (
                <div className="space-y-6">
                    {messages.map(msg => (
                        <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                            <div className={`max-w-[85%] px-5 py-3 ${styles.layoutShape} text-sm font-medium leading-relaxed shadow-lg ${msg.role === 'user' ? `${styles.buttonPrimary} rounded-tr-none` : `${styles.card} rounded-tl-none`}`}>
                                {msg.text}
                            </div>
                        </div>
                    ))}
                    {loading && (
                        <div className="flex justify-start">
                             <div className={`${styles.card} px-6 py-4 ${styles.layoutShape} rounded-tl-none animate-pulse`}>
                                 <div className="flex gap-2">
                                     <div className={`w-2 h-2 ${styles.textDim} rounded-full animate-bounce`}></div>
                                     <div className={`w-2 h-2 ${styles.textDim} rounded-full animate-bounce delay-150`}></div>
                                     <div className={`w-2 h-2 ${styles.textDim} rounded-full animate-bounce delay-300`}></div>
                                 </div>
                             </div>
                        </div>
                    )}
                </div>
            )}
        </div>

        {petType && (
            <div className={`p-6 border-t ${styles.border} flex items-center gap-3 bg-black/20 shrink-0`}>
                <input 
                    type="text" 
                    value={inputText}
                    onChange={(e) => setInputText(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                    placeholder="例如：推荐一些好听的音乐频道"
                    className={`flex-1 ${styles.input} ${styles.layoutShape} px-5 py-3 text-sm focus:outline-none font-bold`}
                />
                <button onClick={handleSend} disabled={!inputText.trim() || loading} className={`p-3.5 ${styles.layoutShape} ${styles.buttonPrimary} disabled:opacity-30 shadow-xl transition-all active:scale-90`}><Send className="w-5 h-5" /></button>
            </div>
        )}
    </div>
  );
};

import React, { useEffect, useRef, useState, useCallback } from 'react';
import Hls from 'hls.js';
import { Play, RefreshCw, Square, Star, Volume2, VolumeX, Maximize, Clock, Zap, Circle, AlertTriangle, Shuffle, WifiOff, Globe, ShieldAlert, Camera } from 'lucide-react';
import { AppTheme, Channel, Country } from '../types';

interface VideoPlayerProps {
  channel: Channel | null;
  country: Country | null; 
  theme: AppTheme;
  isFavorite: boolean;
  onToggleFavorite: () => void;
  onAutoSkip?: () => void; // 自动跳台回调
}

export const VideoPlayer: React.FC<VideoPlayerProps> = ({ 
    channel, country, theme, isFavorite, onToggleFavorite, onAutoSkip
}) => {
  const [activePlayerIndex, setActivePlayerIndex] = useState(0);
  const videoRefs = [useRef<HTMLVideoElement>(null), useRef<HTMLVideoElement>(null)];
  const hlsRefs = useRef<(Hls | null)[]>([null, null]);

  const [loading, setLoading] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const [volume, setVolume] = useState(1);
  const [errorState, setErrorState] = useState<'none' | 'timeout' | 'fatal' | 'network'>('none');
  const [errorDetail, setErrorDetail] = useState<string>('');
  const retryCountRef = useRef(0);
  const MAX_RETRIES = 5; 

  const [isRecording, setIsRecording] = useState(false);
  const [recordingDuration, setRecordingDuration] = useState(0);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);
  const recordingTimerRef = useRef<number | null>(null);

  const loadTimeoutRef = useRef<number | null>(null);

  const resetState = () => {
    setErrorState('none');
    setErrorDetail('');
    setLoading(true);
    retryCountRef.current = 0;
    if (loadTimeoutRef.current) clearTimeout(loadTimeoutRef.current);
  };

  useEffect(() => {
    videoRefs.forEach(ref => {
      if (ref.current) {
        ref.current.volume = volume;
      }
    });
  }, [volume]);

  useEffect(() => {
    const url = channel?.url;
    if (!url) return;

    if (isRecording) stopRecording();
    resetState();

    const nextIndex = (activePlayerIndex + 1) % 2;
    const nextVideo = videoRefs[nextIndex].current;
    if (!nextVideo) return;

    if (hlsRefs.current[nextIndex]) {
        hlsRefs.current[nextIndex]?.destroy();
    }

    loadTimeoutRef.current = window.setTimeout(() => {
        if (loading || !isPlaying) {
            setErrorState('timeout');
            setLoading(false);
        }
    }, 20000);

    if (url.includes('.m3u8') && Hls.isSupported()) {
      const hls = new Hls({
        maxBufferLength: 30,
        manifestLoadingTimeOut: 15000,
        manifestLoadingMaxRetry: 10,
        manifestLoadingRetryDelay: 1000,
        manifestLoadingMaxRetryTimeout: 64000,
        levelLoadingTimeOut: 15000,
        levelLoadingMaxRetry: 5,
        fragLoadingTimeOut: 20000,
        fragLoadingMaxRetry: 5,
        enableWorker: true,
        xhrSetup: (xhr) => {
          xhr.withCredentials = false;
        }
      });
      hlsRefs.current[nextIndex] = hls;

      hls.loadSource(url);
      hls.attachMedia(nextVideo);

      hls.on(Hls.Events.MANIFEST_PARSED, () => {
        if (loadTimeoutRef.current) clearTimeout(loadTimeoutRef.current);
        nextVideo.play().catch(() => {
            setIsPlaying(false);
        });
        setLoading(false);
        setIsPlaying(true);
        setErrorState('none');
        setActivePlayerIndex(nextIndex);
        retryCountRef.current = 0;
      });

      hls.on(Hls.Events.ERROR, (event, data) => {
        if (data.fatal) {
            const detail = data.details || '';
            console.error(`HLS ERROR [${data.type}]: ${detail}`, data);

            if (retryCountRef.current < MAX_RETRIES) {
                retryCountRef.current++;
                const backoff = Math.pow(2, retryCountRef.current) * 500;

                setTimeout(() => {
                  if (!hlsRefs.current[nextIndex]) return;
                  switch (data.type) {
                      case Hls.ErrorTypes.NETWORK_ERROR:
                          hls.startLoad();
                          break;
                      case Hls.ErrorTypes.MEDIA_ERROR:
                          hls.recoverMediaError();
                          break;
                      default:
                          setErrorState('fatal');
                          setLoading(false);
                          break;
                  }
                }, backoff);
            } else {
                setErrorState(data.type === Hls.ErrorTypes.NETWORK_ERROR ? 'network' : 'fatal');
                setErrorDetail(detail);
                setLoading(false);
                if (loadTimeoutRef.current) clearTimeout(loadTimeoutRef.current);
                hls.destroy();
            }
        }
      });
    } else {
      nextVideo.src = url;
      nextVideo.oncanplay = () => {
        if (loadTimeoutRef.current) clearTimeout(loadTimeoutRef.current);
        nextVideo.play().catch(() => { setIsPlaying(false); });
        setLoading(false);
        setIsPlaying(true);
        setErrorState('none');
        setActivePlayerIndex(nextIndex);
      };
      nextVideo.onerror = () => {
        setErrorState('network');
        setErrorDetail('Native video source failure');
        setLoading(false);
      };
    }

    return () => {
        if (loadTimeoutRef.current) clearTimeout(loadTimeoutRef.current);
    };
  }, [channel?.url]);

  // 截图功能
  const takeScreenshot = () => {
    const video = videoRefs[activePlayerIndex].current;
    if (!video || errorState !== 'none' || loading) return;

    try {
      const canvas = document.createElement('canvas');
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      // 绘制当前帧
      ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

      // 导出并下载
      const dataUrl = canvas.toDataURL('image/png');
      const link = document.createElement('a');
      link.href = dataUrl;
      link.download = `Live_Snap_${channel?.name || 'Unknown'}_${new Date().getTime()}.png`;
      link.click();
    } catch (err) {
      console.error('截图失败:', err);
    }
  };

  const startRecording = () => {
    const video = videoRefs[activePlayerIndex].current;
    if (!video || errorState !== 'none') return;
    try {
      const stream = (video as any).captureStream ? (video as any).captureStream() : (video as any).mozCaptureStream ? (video as any).mozCaptureStream() : null;
      if (!stream) return;
      const recorder = new MediaRecorder(stream, { mimeType: 'video/webm;codecs=vp9,opus' });
      mediaRecorderRef.current = recorder;
      chunksRef.current = [];
      recorder.ondataavailable = (e) => { if (e.data.size > 0) chunksRef.current.push(e.data); };
      recorder.onstop = () => {
        const blob = new Blob(chunksRef.current, { type: 'video/webm' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `Live_Record_${channel?.name}_${new Date().getTime()}.webm`;
        a.click();
      };
      recorder.start();
      setIsRecording(true);
      setRecordingDuration(0);
      recordingTimerRef.current = window.setInterval(() => setRecordingDuration(p => p + 1), 1000);
    } catch (err) {}
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      if (recordingTimerRef.current) clearInterval(recordingTimerRef.current);
    }
  };

  const { styles } = theme;

  const getErrorDisplay = () => {
      if (errorDetail === 'manifestLoadError') {
          return {
              icon: <ShieldAlert className="w-12 h-12 text-rose-500" />,
              title: 'CORS 或 资源下线',
              desc: '直播服务器拒绝了连接请求 (manifestLoadError)。这通常是因为：1. 源地址已关闭；2. 跨域限制 (CORS)；3. 您当前所在地区的网络提供商拦截了该流地址。'
          };
      }
      if (errorState === 'network') {
          return {
              icon: <WifiOff className="w-12 h-12 text-amber-500" />,
              title: '主干节点响应失败',
              desc: '无法建立与目标服务器的有效握手。请检查本地网络连接，或尝试更换至其他节点频道。'
          };
      }
      if (errorState === 'timeout') {
          return {
              icon: <Clock className="w-12 h-12 text-cyan-500 animate-pulse" />,
              title: '信号握手超时',
              desc: '服务器响应时间过长，流媒体清单无法按时下载。该信道目前可能因并发过高而发生拥堵。'
          };
      }
      return {
          icon: <AlertTriangle className="w-12 h-12 text-red-500" />,
          title: '频率信号丢失',
          desc: '该频率当前无法接收到有效载波。建议点击「随机跳台」寻找其他可用频道。'
      };
  };

  const display = getErrorDisplay();

  return (
    <div className="relative w-full group select-none">
      <div className="absolute inset-0 -m-8 bg-cyan-500/5 blur-[100px] opacity-0 group-hover:opacity-100 transition-opacity duration-1000 pointer-events-none"></div>

      <div className={`relative w-full aspect-video bg-[#0a0a0a] rounded-3xl overflow-hidden border ${styles.border} shadow-[0_30px_100px_rgba(0,0,0,0.8)]`}>

        {errorState !== 'none' && (
            <div className="absolute inset-0 z-40 flex flex-col items-center justify-center text-center p-10 bg-black/90 backdrop-blur-2xl">
                <div className="absolute inset-0 opacity-10 pointer-events-none overflow-hidden">
                    <div className="w-full h-full bg-[url('https://media.giphy.com/media/oEI9uWUeez9BK/giphy.gif')] bg-cover opacity-20 grayscale scale-150"></div>
                </div>
                <div className="relative z-10 flex flex-col items-center space-y-6 animate-in fade-in zoom-in slide-in-from-bottom-4 duration-700">
                    <div className="w-24 h-24 rounded-full bg-white/5 flex items-center justify-center border border-white/10 shadow-[0_0_60px_rgba(244,63,94,0.1)] group/icon relative">
                        {display.icon}
                        <div className="absolute -inset-4 rounded-full border border-white/5 animate-pulse opacity-20"></div>
                    </div>
                    <div>
                        <h3 className="text-white font-black text-3xl uppercase italic tracking-tighter">
                            {display.title}
                        </h3>
                        <p className="text-gray-400 text-xs mt-4 max-w-sm mx-auto leading-relaxed font-bold opacity-80">
                            {display.desc}
                        </p>
                    </div>
                    <div className="flex flex-col sm:flex-row gap-4 pt-6">
                        <button 
                            onClick={() => window.location.reload()} 
                            className="px-10 py-4 bg-white text-black text-[11px] font-black uppercase rounded-full hover:bg-cyan-400 transition-all shadow-2xl active:scale-95 flex items-center justify-center gap-2"
                        >
                            <RefreshCw className="w-3.5 h-3.5" /> 强制重连信道
                        </button>
                        <button 
                            onClick={onAutoSkip} 
                            className="px-10 py-4 bg-white/5 text-white text-[11px] font-black uppercase rounded-full border border-white/10 hover:bg-white/10 transition-all flex items-center justify-center gap-2 active:scale-95"
                        >
                            <Shuffle className="w-3.5 h-3.5" /> 尝试其他频率
                        </button>
                    </div>
                </div>
            </div>
        )}

        {[0, 1].map((index) => (
            <video
                key={index} ref={videoRefs[index]} playsInline muted={isMuted}
                className={`absolute inset-0 w-full h-full object-contain transition-opacity duration-1000 ${activePlayerIndex === index && errorState === 'none' ? 'opacity-100' : 'opacity-0'}`}
            />
        ))}

        {isRecording && errorState === 'none' && (
          <div className="absolute top-6 left-6 z-40 flex items-center gap-3 bg-black/60 backdrop-blur-xl px-4 py-2 rounded-full border border-red-500/30">
             <div className="w-2.5 h-2.5 bg-red-600 rounded-full animate-pulse shadow-[0_0_15px_rgba(220,38,38,1)]"></div>
             <span className="text-white text-[10px] font-black tracking-widest uppercase">REC</span>
             <span className="text-red-400 font-mono text-xs font-bold border-l border-white/10 pl-3">
                 {Math.floor(recordingDuration/60).toString().padStart(2,'0')}:{(recordingDuration%60).toString().padStart(2,'0')}
             </span>
          </div>
        )}

        {loading && errorState === 'none' && (
             <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/60 backdrop-blur-md z-20 space-y-4">
                <div className="relative w-16 h-16">
                    <div className="absolute inset-0 border-4 border-cyan-500/20 rounded-full"></div>
                    <div className="absolute inset-0 border-4 border-t-cyan-500 rounded-full animate-spin"></div>
                </div>
                <div className="text-[10px] text-cyan-500 font-mono font-black uppercase tracking-[0.3em] animate-pulse">
                    正在捕获全球信号...
                </div>
             </div>
        )}

        <div className={`absolute inset-x-0 bottom-0 p-8 bg-gradient-to-t from-black via-black/60 to-transparent transition-all duration-700 ${errorState !== 'none' ? 'opacity-20 pointer-events-none translate-y-4' : 'opacity-0 group-hover:opacity-100'}`}>
            <div className="flex flex-col md:flex-row items-center justify-between gap-4">
                <div className="flex items-center gap-6">
                    <button onClick={() => {
                        const v = videoRefs[activePlayerIndex].current;
                        if (isPlaying) v?.pause(); else v?.play();
                        setIsPlaying(!isPlaying);
                    }} className="w-14 h-14 bg-white text-black rounded-full flex items-center justify-center transition-all hover:scale-110 active:scale-95 shadow-2xl">
                        {isPlaying ? <Square className="w-5 h-5 fill-current" /> : <Play className="w-5 h-5 fill-current ml-1" />}
                    </button>
                    <div className="min-w-0">
                        <div className="flex items-center gap-2 mb-1">
                            <span className="px-2 py-0.5 bg-cyan-500 text-[9px] font-black text-black rounded-sm uppercase tracking-tighter">LIVE</span>
                            <h4 className="text-white font-black text-lg tracking-tight truncate max-w-[150px] md:max-w-md uppercase italic">
                                {channel?.name || '等待选台中...'}
                            </h4>
                        </div>
                        <div className="flex items-center gap-2 text-gray-500 text-[10px] font-bold uppercase tracking-widest">
                            <Zap className="w-3 h-3 text-cyan-400 fill-current" /> 
                            {channel?.group || '全球通用信道'} • {country?.name || '未知地域'}
                        </div>
                    </div>
                </div>

                <div className="flex items-center gap-3">
                    {/* 截图按钮 */}
                    <button 
                        onClick={takeScreenshot} 
                        className={`p-3.5 bg-white/10 text-white hover:bg-white/20 rounded-xl transition-all active:scale-90`}
                        title="拍摄快照"
                    >
                        <Camera className="w-5 h-5" />
                    </button>

                    {/* 录制按钮 */}
                    <button 
                        onClick={isRecording ? stopRecording : startRecording} 
                        className={`p-3.5 rounded-xl transition-all ${isRecording ? 'bg-red-600 text-white shadow-[0_0_15px_rgba(220,38,38,0.3)]' : 'bg-white/10 text-white hover:bg-white/20'}`}
                        title={isRecording ? "停止录制" : "开始录制"}
                    >
                        <Circle className={`w-5 h-5 ${isRecording ? 'fill-current animate-pulse' : ''}`} />
                    </button>

                    <div className="flex items-center group/vol">
                      <button onClick={() => setIsMuted(!isMuted)} className="p-3.5 bg-white/10 hover:bg-white/20 rounded-xl text-white transition-colors" title={isMuted ? "取消静音" : "静音"}>
                          {isMuted || volume === 0 ? <VolumeX className="w-5 h-5 text-red-400" /> : <Volume2 className="w-5 h-5" />}
                      </button>
                      <div className="w-0 overflow-hidden group-hover/vol:w-28 group-hover/vol:ml-3 transition-all duration-500 flex items-center">
                          <input 
                              type="range" min="0" max="1" step="0.01" 
                              value={isMuted ? 0 : volume}
                              onChange={(e) => {
                                  const v = parseFloat(e.target.value);
                                  setVolume(v);
                                  if (v > 0) setIsMuted(false);
                              }}
                              className="w-24 h-1.5 accent-cyan-500 bg-white/20 rounded-full appearance-none cursor-pointer"
                          />
                      </div>
                    </div>

                    <button onClick={() => videoRefs[activePlayerIndex].current?.requestFullscreen()} className="p-3.5 bg-white/10 hover:bg-white/20 rounded-xl text-white transition-colors">
                        <Maximize className="w-5 h-5" />
                    </button>
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

import { Country, Channel } from '../types';

const API_BASE = 'https://iptv-org.github.io/api';
const PLAYLIST_BASE = 'https://iptv-org.github.io/iptv/countries';
const RADIO_API_BASE = 'https://de1.api.radio-browser.info/json/stations/bycountrycodeexact';

// 排除受限地区
const EXCLUDED_REGIONS = ['CN', 'HK', 'TW'];

// 全球顶级信道兜底库 (始终可用)
