        favorites={favorites} onSelectFavorite={handleChannelSelect} history={history}
        onImportM3U={() => {}} settings={{enableSound: true}} onToggleSound={() => {}} reminders={[]}
        onDeleteReminder={() => {}} onPlayReminder={() => {}}
