              <div className={`${styles.card} max-w-xl p-8 ${styles.layoutShape} relative border ${styles.border}`}>
                  <button onClick={closeOnboarding} className="absolute top-4 right-4 p-2 opacity-40 hover:opacity-100"><X className="w-5 h-5" /></button>
                  <div className="flex flex-col items-center text-center space-y-6">
                      <div className="w-16 h-16 rounded-full bg-cyan-500/10 flex items-center justify-center"><HelpCircle className="w-8 h-8 text-cyan-500" /></div>
                      <div>
                          <h2 className={`text-2xl font-black uppercase italic ${styles.textMain}`}>欢迎来到全球智播</h2>
                          <p className={`mt-3 text-[11px] ${styles.textDim} font-bold leading-relaxed uppercase tracking-widest`}>这是你的私人全球信号基站，连接全球实时脉搏。</p>
                      </div>
                      <button onClick={closeOnboarding} className={`w-full py-4 ${styles.buttonPrimary} ${styles.layoutShape} font-black uppercase tracking-widest text-[11px] shadow-2xl`}>开始探索</button>
                  </div>
              </div>
          </div>
      )}

      <Sidebar 
        countries={countries} selectedCountry={selectedCountry} onSelectCountry={setSelectedCountry}
        isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} mode={mode} onModeChange={setMode}
        themes={THEMES} currentTheme={currentTheme} onThemeChange={setCurrentTheme}
        favorites={favorites} onSelectFavorite={handleChannelSelect} history={history}
        onImportM3U={() => {}} settings={{enableSound: true}} onToggleSound={() => {}} 
        reminders={reminders} onDeleteReminder={(id) => {
            const next = reminders.filter(r => r.id !== id);
            setReminders(next); localStorage.setItem('global_reminders', JSON.stringify(next));
        }} onPlayReminder={handleChannelSelect}
      />

      <main className="flex-1 flex flex-col h-full min-w-0 z-10 relative">
        <header className={`shrink-0 px-6 py-3 flex items-center justify-between border-b ${styles.border} ${styles.bgSidebar} backdrop-blur-3xl z-20`}>
            <div className="flex items-center gap-4">
                <button onClick={() => setSidebarOpen(true)} className={`md:hidden p-2 rounded-xl ${styles.textMain}`}><Menu className="w-6 h-6" /></button>
                <div className="flex items-center gap-2">
                    <span className="text-2xl">{selectedCountry?.flag}</span>
                    <h1 className={`text-lg font-black uppercase italic tracking-tighter ${styles.textMain}`}>{selectedCountry?.name}</h1>
                </div>
            </div>
            <div className="flex items-center gap-4">
                <button onClick={() => setShowSchedule(true)} className={`p-2 rounded-full ${styles.textDim} hover:${styles.textMain}`}><AlarmClock className="w-5 h-5" /></button>
                <div className={`hidden sm:flex items-center gap-2 ${styles.card} px-3 py-1.5 ${styles.layoutShape} text-[10px]`}>
                    <div className="w-1.5 h-1.5 rounded-full animate-pulse bg-cyan-500"></div>
                    <span className={`font-mono ${styles.textMain}`}>{localTime}</span>
                </div>
                <button onClick={() => loadContent(true)} className={`p-2 rounded-full ${styles.textMain} ${loadingChannels ? 'animate-spin' : ''}`}><RefreshCw className="w-4 h-4" /></button>
            </div>
        </header>

        <div className={`flex-1 overflow-y-auto ${currentTheme.type === 'web95' ? 'scrollbar-web95' : 'scrollbar-thin'}`}>
            <div className="px-4 md:px-6 py-6 max-w-[1800px] mx-auto">
                <div className="flex flex-col lg:flex-row gap-6">
                    <div className="flex-1 min-w-0 space-y-6">
                        <section className="space-y-4">
                            <div className="flex items-center justify-between px-4 py-2 bg-black/20 rounded-xl border border-white/5 animate-pulse">
