                            </div>
                            <VideoPlayer 
                              channel={currentChannel} country={selectedCountry} theme={currentTheme}
                              isFavorite={!!currentChannel && favorites.some(f => f.id === currentChannel.id)}
                              onToggleFavorite={() => currentChannel && toggleFavorite(currentChannel)} onAutoSkip={() => {}}
                            />
                            <FavoritesBar favorites={favorites} currentChannel={currentChannel} onSelectChannel={handleChannelSelect} theme={currentTheme} mode={mode} />
                        </section>

                        <section className="pt-4">
                            <div className="flex flex-col mb-6 space-y-4">
                                <div className="flex items-center gap-3">
                                    <div className="w-1 h-5 bg-cyan-500 rounded-full"></div>
                                    <h2 className={`text-lg font-black uppercase italic tracking-tight ${styles.textMain}`}>探索内容库 ({channels.length})</h2>
                                </div>
                                <div className="flex flex-wrap gap-2">
                                    {HOT_TAGS.map(tag => (
                                        <button key={tag} onClick={() => setChannelFilter(tag)} className={`px-3 py-1.5 ${styles.layoutShape} text-[9px] font-black border ${channelFilter === tag ? styles.buttonActive : `${styles.button} opacity-40 hover:opacity-100`}`}># {tag}</button>
                                    ))}
                                    {channelFilter && <button onClick={() => setChannelFilter('')} className="px-3 py-1.5 rounded-lg text-[9px] font-black bg-rose-500/20 text-rose-500">清除</button>}
                                </div>
                            </div>
                            <ChannelGrid 
                                channels={channels} currentChannel={currentChannel} onSelectChannel={handleChannelSelect} 
                                loading={loadingChannels} mode={mode} theme={currentTheme} favorites={favorites} 
                                onToggleFavorite={toggleFavorite} externalFilter={channelFilter} onExternalFilterChange={setChannelFilter}
                            />
                        </section>
                    </div>

                    <div className="lg:w-[320px] shrink-0 space-y-4">
                        <div className="lg:sticky lg:top-4 space-y-4">
                            <div className={`${styles.card} p-5 ${styles.layoutShape}`}>
                                <h3 className="text-[9px] font-black uppercase tracking-[0.2em] mb-4 opacity-40 flex items-center gap-2"><History className="w-3 h-3" /> 播放足迹</h3>
                                <div className="space-y-2">
                                    {history.map(h => (
                                        <div key={h.id} onClick={() => handleChannelSelect(h)} className="flex items-center gap-3 p-2 hover:bg-white/5 cursor-pointer rounded-xl group transition-all">
                                            <div className="w-8 h-8 rounded-lg bg-black/30 flex items-center justify-center shrink-0 overflow-hidden">{h.logo ? <img src={h.logo} className="w-full h-full object-contain" /> : <History className="w-3.5 h-3.5 opacity-20" />}</div>
                                            <span className={`text-[10px] font-bold uppercase truncate ${styles.textMain}`}>{h.name}</span>
                                        </div>
                                    ))}
                                </div>
                            </div>
                            <button onClick={() => { if(channels.length > 0) handleChannelSelect(channels[Math.floor(Math.random()*channels.length)]) }} className={`w-full py-4 ${styles.buttonPrimary} ${styles.layoutShape} font-black uppercase text-[10px] flex items-center justify-center gap-2 shadow-xl`}><Shuffle className="w-3.5 h-3.5" /> 随机漫游</button>
                            <AiChatPet theme={currentTheme} currentChannels={channels} onSelectChannel={handleChannelSelect} />
                        </div>
                    </div>
                </div>
            </div>
        </div>
      </main>

      <ScheduleList 
        reminders={reminders} isOpen={showSchedule} onClose={() => setShowSchedule(false)} 
        onDelete={(id) => { const next = reminders.filter(r => r.id !== id); setReminders(next); localStorage.setItem('global_reminders', JSON.stringify(next)); }}
        theme={currentTheme} onPlayChannel={(id) => { const ch = channels.find(c => c.id === id); if(ch) handleChannelSelect(ch); }}
        allChannels={channels}
      />
      <AlarmModal reminder={activeAlarm} onClose={() => setActiveAlarm(null)} onWatch={(id) => { const ch = channels.find(c => c.id === id); if(ch) handleChannelSelect(ch); setActiveAlarm(null); }} theme={currentTheme} />
    </div>
  );
};

