                <div className={`hidden sm:flex items-center gap-2 ${styles.card} px-3 py-1.5 ${styles.layoutShape} text-[10px]`}>
                    <div className="w-1.5 h-1.5 rounded-full animate-pulse bg-cyan-500"></div>
                    <span className={`font-mono ${styles.textMain}`}>{localTime}</span>
                </div>
                <button onClick={() => loadContent(true)} className={`p-2 rounded-full ${styles.textMain} ${loadingChannels ? 'animate-spin' : ''}`}><RefreshCw className="w-4 h-4" /></button>
            </div>
        </header>

        <div className={`flex-1 overflow-y-auto ${currentTheme.type === 'web95' ? 'scrollbar-web95' : 'scrollbar-thin'}`}>
            <div className="px-4 md:px-6 py-6 max-w-[1800px] mx-auto">
                <div className="flex flex-col lg:flex-row gap-6">
                    <div className="flex-1 min-w-0 space-y-6">
                        <section className="space-y-4">
                            <div className="flex items-center justify-between px-4 py-2 bg-black/20 rounded-xl border border-white/5 animate-pulse">
                                <div className="flex items-center gap-2 text-[9px] font-black uppercase text-cyan-500/80 italic tracking-[0.2em]">
                                    <MapPin className="w-3 h-3" />
                                    <span>
                                        {discoveryTag ? `正在扫描全球 "${discoveryTag}" 信号节点...` : `正在连接至: ${selectedCountry?.name} 基站...`}
                                    </span>
                                </div>
                                {discoveryTag && (
                                    <button onClick={() => setDiscoveryTag(null)} className="text-[9px] font-black uppercase text-rose-500 bg-rose-500/10 px-2 py-0.5 rounded">返回地区频道</button>
                                )}
                            </div>
                            <VideoPlayer 
                              channel={currentChannel} country={discoveryTag ? GLOBAL_EXPLORE_COUNTRY : selectedCountry} theme={currentTheme}
                              isFavorite={!!currentChannel && favorites.some(f => f.id === currentChannel.id)}
                              onToggleFavorite={() => currentChannel && toggleFavorite(currentChannel)} onAutoSkip={() => {}}
                            />
                            <FavoritesBar favorites={favorites} currentChannel={currentChannel} onSelectChannel={handleChannelSelect} theme={currentTheme} mode={mode} />
                        </section>

                        <section className="pt-4">
                            <div className="flex flex-col mb-6 space-y-4">
                                <div className="flex items-center gap-3">
                                    <div className="w-1 h-5 bg-cyan-500 rounded-full"></div>
                                    <h2 className={`text-lg font-black uppercase italic tracking-tight ${styles.textMain}`}>
                                        {discoveryTag ? `全球${discoveryTag}内容库 (${channels.length})` : `探索内容库 (${channels.length})`}
                                    </h2>
                                </div>
                                <div className="flex flex-wrap gap-2">
                                    {HOT_TAGS.map(tag => (
                                        <button 
                                            key={tag} 
                                            onClick={() => handleTagClick(tag)} 
                                            className={`px-3 py-1.5 ${styles.layoutShape} text-[9px] font-black border transition-all ${discoveryTag === tag ? styles.buttonActive : `${styles.button} opacity-40 hover:opacity-100`}`}
                                        >
                                            # {tag}
                                        </button>
                                    ))}
                                    {(discoveryTag || channelFilter) && (
                                        <button onClick={() => { setDiscoveryTag(null); setChannelFilter(''); }} className="px-3 py-1.5 rounded-lg text-[9px] font-black bg-rose-500/20 text-rose-500">清除所有筛选</button>
                                    )}
                                </div>
                            </div>
                            <ChannelGrid 
                                channels={channels} currentChannel={currentChannel} onSelectChannel={handleChannelSelect} 
                                loading={loadingChannels} mode={mode} theme={currentTheme} favorites={favorites} 
                                onToggleFavorite={toggleFavorite} externalFilter={channelFilter} onExternalFilterChange={setChannelFilter}
                            />
                        </section>
                    </div>

                    <div className="lg:w-[320px] shrink-0 space-y-4">
                        <div className="lg:sticky lg:top-4 space-y-4">
                            <div className={`${styles.card} p-5 ${styles.layoutShape}`}>
                                <h3 className="text-[9px] font-black uppercase tracking-[0.2em] mb-4 opacity-40 flex items-center gap-2"><History className="w-3 h-3" /> 播放足迹</h3>
                                <div className="space-y-2">
                                    {history.map(h => (
                                        <div key={h.id} onClick={() => handleChannelSelect(h)} className="flex items-center gap-3 p-2 hover:bg-white/5 cursor-pointer rounded-xl group transition-all">
                                            <div className="w-8 h-8 rounded-lg bg-black/30 flex items-center justify-center shrink-0 overflow-hidden">{h.logo ? <img src={h.logo} className="w-full h-full object-contain" /> : <History className="w-3.5 h-3.5 opacity-20" />}</div>
                                            <span className={`text-[10px] font-bold uppercase truncate ${styles.textMain}`}>{h.name}</span>
