  const { styles } = currentTheme;

  return (
    <div className={`flex h-screen w-full ${styles.bgMain} ${styles.font} overflow-hidden relative`}>
      <div className="bg-noise"></div>

      {/* Dynamic Mesh Gradient Overlay */}
      <div className="fixed inset-0 pointer-events-none opacity-20">
          <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-cyan-500 blur-[150px] rounded-full animate-pulse-glow"></div>
          <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-purple-500 blur-[150px] rounded-full animate-pulse-glow" style={{animationDelay: '-2s'}}></div>
      </div>

      <Sidebar 
        countries={countries} selectedCountry={discoveryTag ? GLOBAL_EXPLORE_COUNTRY : selectedCountry} 
        onSelectCountry={(c) => { setDiscoveryTag(null); setSelectedCountry(c); }}
        isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} mode={mode} onModeChange={setMode}
        themes={THEMES} currentTheme={currentTheme} onThemeChange={handleThemeChange}
        favorites={favorites} onSelectFavorite={handleChannelSelect} history={history}
        onImportM3U={() => {}} settings={{enableSound: true}} onToggleSound={() => {}} 
        reminders={reminders} onDeleteReminder={(id) => {
            const next = reminders.filter(r => r.id !== id);
            setReminders(next); localStorage.setItem('global_reminders', JSON.stringify(next));
        }} onPlayReminder={handleChannelSelect}
      />

      <main className="flex-1 flex flex-col h-full min-w-0 z-10 relative">
        <header className={`shrink-0 px-8 py-4 flex items-center justify-between border-b ${styles.border} ${styles.bgSidebar} backdrop-blur-[60px] z-30 shadow-lg`}>
            <div className="flex items-center gap-6">
                <button onClick={() => setSidebarOpen(true)} className={`md:hidden p-3 rounded-full ${styles.card} ${styles.textMain} active:scale-90 transition-transform`}><Menu className="w-6 h-6" /></button>
                <div className="flex items-center gap-4">
                    <span className="text-3xl drop-shadow-2xl filter saturate-150">{discoveryTag ? '🛰️' : selectedCountry?.flag}</span>
                    <div className="flex flex-col">
                        <h1 className={`text-xl font-black uppercase italic tracking-tighter leading-none ${styles.textMain}`}>
                            {discoveryTag ? `全球探索: ${discoveryTag}` : selectedCountry?.name}
                        </h1>
                        <span className={`text-[9px] font-black tracking-widest uppercase opacity-40 mt-1 ${styles.textDim}`}>
                            {channels.length} Nodes Connected
                        </span>
                    </div>
                </div>
            </div>

            <div className="flex items-center gap-6">
                <div className={`hidden lg:flex flex-col items-end gap-0.5`}>
                    <span className={`text-[8px] font-black uppercase tracking-[0.2em] ${styles.textDim}`}>Local Node Time</span>
                    <span className={`text-sm font-mono font-bold tracking-widest ${styles.textMain}`}>{localTime}</span>
                </div>

                <div className="flex items-center gap-2">
                    <button onClick={() => setShowSchedule(true)} className={`p-3 rounded-xl ${styles.button} hover:scale-105 active:scale-95 transition-all relative`}>
                        <AlarmClock className="w-5 h-5" />
                        {reminders.length > 0 && <span className="absolute top-2 right-2 w-2 h-2 bg-rose-500 rounded-full border border-black animate-ping"></span>}
                    </button>
                    <button onClick={() => loadContent(true)} className={`p-3 rounded-xl ${styles.button} hover:rotate-180 transition-all duration-700 ${loadingChannels ? 'animate-spin' : ''}`}><RefreshCw className="w-5 h-5" /></button>
                </div>
            </div>
        </header>

        <div className={`flex-1 overflow-y-auto ${currentTheme.type === 'web95' ? 'scrollbar-web95' : 'scrollbar-thin'}`}>
            <div className="px-6 py-8 max-w-[1920px] mx-auto">
                <div className="flex flex-col lg:flex-row gap-8">
                    <div className="flex-1 min-w-0 space-y-8">
                        <section className="space-y-6">
                            <div className={`flex items-center justify-between px-6 py-3 ${styles.card} ${styles.layoutShape} border ${styles.border} group`}>
                                <div className="flex items-center gap-3">
                                    <div className="relative">
                                        <MapPin className="w-4 h-4 text-cyan-400" />
                                        <div className="absolute inset-0 bg-cyan-400/40 blur-md animate-pulse"></div>
                                    </div>
                                    <span className={`text-[10px] font-black uppercase tracking-[0.1em] ${styles.textMain}`}>
                                        {discoveryTag ? `Scanning Global Metadata for "${discoveryTag}"` : `Active Link: ${selectedCountry?.name} Ground Station`}
                                    </span>
                                </div>
                                {discoveryTag && (
                                    <button onClick={() => setDiscoveryTag(null)} className="text-[10px] font-black uppercase text-rose-500 hover:text-white bg-rose-500/10 hover:bg-rose-500 px-3 py-1 rounded-full transition-all">Exit Search</button>
                                )}
                            </div>

                            <VideoPlayer 
                              channel={currentChannel} country={discoveryTag ? GLOBAL_EXPLORE_COUNTRY : selectedCountry} theme={currentTheme}
                              isFavorite={!!currentChannel && favorites.some(f => f.id === currentChannel.id)}
                              onToggleFavorite={() => currentChannel && toggleFavorite(currentChannel)} 
                              onAutoSkip={() => {
                                  if (channels.length > 1) {
                                      const next = channels[Math.floor(Math.random()*channels.length)];
                                      handleChannelSelect(next);
                                  }
                              }}
                            />

                            <FavoritesBar favorites={favorites} currentChannel={currentChannel} onSelectChannel={handleChannelSelect} theme={currentTheme} mode={mode} />
                        </section>

                        <section className="pt-4 space-y-8">
                            <div className="flex flex-col space-y-6">
                                <div className="flex items-center justify-between">
                                    <div className="flex items-center gap-4">
                                        <div className={`w-1.5 h-8 bg-gradient-to-b from-cyan-400 to-blue-600 rounded-full shadow-[0_0_15px_rgba(34,211,238,0.5)]`}></div>
                                        <h2 className={`text-2xl font-black uppercase italic tracking-tighter ${styles.textMain}`}>
                                            Discovery Library
                                        </h2>
                                    </div>
                                    <div className={`hidden sm:flex items-center gap-2 px-3 py-1 bg-white/5 rounded-full border border-white/5 text-[9px] font-black uppercase text-white/30`}>
                                        <Sparkles className="w-3 h-3" /> Filter by Intent
                                    </div>
                                </div>

                                <div className="flex flex-wrap gap-2.5">
                                    {HOT_TAGS.map(tag => (
                                        <button 
                                            key={tag} 
                                            onClick={() => handleTagClick(tag)} 
                                            className={`px-4 py-2 ${styles.layoutShape} text-[10px] font-black border transition-all duration-300 transform active:scale-90 ${discoveryTag === tag ? styles.buttonActive : `${styles.button} opacity-40 hover:opacity-100 hover:scale-105`}`}
                                        >
                                            # {tag}
                                        </button>
                                    ))}
                                    {(discoveryTag || channelFilter) && (
                                        <button onClick={() => { setDiscoveryTag(null); setChannelFilter(''); }} className="px-5 py-2 rounded-full text-[10px] font-black bg-rose-500/20 text-rose-500 hover:bg-rose-500 hover:text-white transition-all">RESET FILTERS</button>
                                    )}
                                </div>
                            </div>

                            <ChannelGrid 
                                channels={channels} currentChannel={currentChannel} onSelectChannel={handleChannelSelect} 
                                loading={loadingChannels} mode={mode} theme={currentTheme} favorites={favorites} 
                                onToggleFavorite={toggleFavorite} externalFilter={channelFilter} onExternalFilterChange={setChannelFilter}
                            />
                        </section>
                    </div>

                    <div className="lg:w-[360px] shrink-0 space-y-6">
                        <div className="lg:sticky lg:top-8 space-y-6">
                            <div className={`${styles.card} p-6 ${styles.layoutShape} border ${styles.border} group overflow-hidden relative`}>
                                <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-cyan-500/20 to-transparent"></div>
                                <h3 className="text-[10px] font-black uppercase tracking-[0.3em] mb-6 opacity-40 flex items-center gap-3"><History className="w-4 h-4" /> Temporal Logs</h3>
                                <div className="space-y-3">
                                    {history.length > 0 ? history.map(h => (
                                        <div key={h.id} onClick={() => handleChannelSelect(h)} className={`flex items-center gap-4 p-3 rounded-2xl hover:bg-white/5 cursor-pointer group/item transition-all border border-transparent hover:border-white/5`}>
                                            <div className="w-10 h-10 rounded-xl bg-black/40 flex items-center justify-center shrink-0 overflow-hidden shadow-inner group-hover/item:scale-110 transition-transform">
                                                {h.logo ? <img src={h.logo} className="w-full h-full object-contain p-1.5" /> : <History className="w-4 h-4 opacity-10" />}
                                            </div>
                                            <div className="flex flex-col min-w-0">
                                                <span className={`text-[11px] font-black uppercase truncate ${styles.textMain}`}>{h.name}</span>
                                                <span className={`text-[8px] font-bold opacity-30 uppercase tracking-tighter`}>{h.group || 'Public Wave'}</span>
                                            </div>
                                        </div>
                                    )) : (
                                        <div className="py-8 text-center text-[9px] font-black opacity-10 uppercase italic">History empty</div>
                                    )}
                                </div>
                            </div>

                            <button onClick={() => { if(channels.length > 0) handleChannelSelect(channels[Math.floor(Math.random()*channels.length)]) }} className={`w-full py-5 ${styles.buttonPrimary} ${styles.layoutShape} font-black uppercase text-[11px] flex items-center justify-center gap-3 shadow-[0_20px_40px_rgba(0,0,0,0.3)] hover:translate-y-[-2px] active:translate-y-[2px] transition-all`}><Shuffle className="w-4 h-4" /> Neural Randomize</button>

                            <AiChatPet theme={currentTheme} currentChannels={channels} onSelectChannel={handleChannelSelect} />
                        </div>
                    </div>
                </div>
            </div>
        </div>
      </main>

      <ScheduleList 
        reminders={reminders} isOpen={showSchedule} onClose={() => setShowSchedule(false)} 
        onDelete={(id) => { const next = reminders.filter(r => r.id !== id); setReminders(next); localStorage.setItem('global_reminders', JSON.stringify(next)); }}
        theme={currentTheme} onPlayChannel={(id) => { const ch = channels.find(c => c.id === id); if(ch) handleChannelSelect(ch); }}
        allChannels={channels}
      />
      <AlarmModal reminder={activeAlarm} onClose={() => setActiveAlarm(null)} onWatch={(id) => { const ch = channels.find(c => c.id === id); if(ch) handleChannelSelect(ch); setActiveAlarm(null); }} theme={currentTheme} />
    </div>
  );
};

export default App;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import Hls from 'hls.js';
import { Play, RefreshCw, Square, Star, Volume2, VolumeX, Maximize, Clock, Zap, Circle, AlertTriangle, Shuffle, WifiOff, Globe, ShieldAlert, Camera, Terminal } from 'lucide-react';
import { AppTheme, Channel, Country } from '../types';

interface VideoPlayerProps {
  channel: Channel | null;
  country: Country | null; 
  theme: AppTheme;
  isFavorite: boolean;
  onToggleFavorite: () => void;
  onAutoSkip?: () => void;
}

export const VideoPlayer: React.FC<VideoPlayerProps> = ({ 
    channel, country, theme, isFavorite, onToggleFavorite, onAutoSkip
}) => {
  const [activePlayerIndex, setActivePlayerIndex] = useState(0);
  const videoRefs = [useRef<HTMLVideoElement>(null), useRef<HTMLVideoElement>(null)];
  const hlsRefs = useRef<(Hls | null)[]>([null, null]);

  const [loading, setLoading] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const [volume, setVolume] = useState(1);
  const [errorState, setErrorState] = useState<'none' | 'timeout' | 'fatal' | 'network'>('none');
  const [errorDetail, setErrorDetail] = useState<string>('');
  const retryCountRef = useRef(0);
  const MAX_RETRIES = 5; 

  const [isRecording, setIsRecording] = useState(false);
  const [recordingDuration, setRecordingDuration] = useState(0);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);
  const recordingTimerRef = useRef<number | null>(null);
  const loadTimeoutRef = useRef<number | null>(null);

  const killAllPlayers = useCallback(() => {
    videoRefs.forEach(ref => {
      if (ref.current) {
        ref.current.pause();
        ref.current.removeAttribute('src');
        ref.current.load();
      }
    });
    hlsRefs.current.forEach((hls, idx) => {
      if (hls) {
        hls.destroy();
        hlsRefs.current[idx] = null;
      }
    });
  }, []);

  const resetState = () => {
    setErrorState('none');
    setErrorDetail('');
    setLoading(true);
    retryCountRef.current = 0;
    if (loadTimeoutRef.current) clearTimeout(loadTimeoutRef.current);
  };

  useEffect(() => {
    videoRefs.forEach(ref => {
      if (ref.current) ref.current.volume = volume;
    });
  }, [volume]);

  useEffect(() => {
    const url = channel?.url;
    if (!url) return;
    if (isRecording) stopRecording();
    killAllPlayers();
    resetState();

    const nextIndex = (activePlayerIndex + 1) % 2;
    const nextVideo = videoRefs[nextIndex].current;
    if (!nextVideo) return;

    loadTimeoutRef.current = window.setTimeout(() => {
        if (loading || !isPlaying) {
            setErrorState('timeout');
            setLoading(false);
        }
    }, 20000);

    if (url.includes('.m3u8') && Hls.isSupported()) {
      const hls = new Hls({
        maxBufferLength: 30,
        enableWorker: true,
        xhrSetup: (xhr) => { xhr.withCredentials = false; }
      });
      hlsRefs.current[nextIndex] = hls;
      hls.loadSource(url);
      hls.attachMedia(nextVideo);
      hls.on(Hls.Events.MANIFEST_PARSED, () => {
        if (loadTimeoutRef.current) clearTimeout(loadTimeoutRef.current);
        videoRefs.forEach((ref, idx) => { if (idx !== nextIndex && ref.current) ref.current.pause(); });
        nextVideo.play().catch(() => { setIsPlaying(false); });
        setLoading(false);
        setIsPlaying(true);
        setErrorState('none');
        setActivePlayerIndex(nextIndex);
        retryCountRef.current = 0;
      });
      hls.on(Hls.Events.ERROR, (event, data) => {
        if (data.fatal) {
            if (retryCountRef.current < MAX_RETRIES) {
                retryCountRef.current++;
                setTimeout(() => {
                  if (!hlsRefs.current[nextIndex]) return;
                  if (data.type === Hls.ErrorTypes.NETWORK_ERROR) hls.startLoad();
                  else hls.recoverMediaError();
                }, Math.pow(2, retryCountRef.current) * 500);
            } else {
                setErrorState(data.type === Hls.ErrorTypes.NETWORK_ERROR ? 'network' : 'fatal');
                setErrorDetail(data.details || '');
                setLoading(false);
                if (loadTimeoutRef.current) clearTimeout(loadTimeoutRef.current);
            }
        }
      });
    } else {
      nextVideo.src = url;
      nextVideo.oncanplay = () => {
        if (loadTimeoutRef.current) clearTimeout(loadTimeoutRef.current);
        nextVideo.play().catch(() => { setIsPlaying(false); });
        setLoading(false);
        setIsPlaying(true);
        setErrorState('none');
        setActivePlayerIndex(nextIndex);
      };
      nextVideo.onerror = () => { setErrorState('network'); setLoading(false); };
    }
    return () => { if (loadTimeoutRef.current) clearTimeout(loadTimeoutRef.current); };
  }, [channel?.url]);

  useEffect(() => { return () => killAllPlayers(); }, [killAllPlayers]);

  const takeScreenshot = () => {
    const video = videoRefs[activePlayerIndex].current;
    if (!video || errorState !== 'none' || loading) return;
    const canvas = document.createElement('canvas');
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
    const link = document.createElement('a');
    link.href = canvas.toDataURL('image/png');
    link.download = `Live_Snap_${channel?.name}_${Date.now()}.png`;
    link.click();
  };

  const startRecording = () => {
    const video = videoRefs[activePlayerIndex].current;
    if (!video) return;
    const stream = (video as any).captureStream ? (video as any).captureStream() : null;
    if (!stream) return;
    const recorder = new MediaRecorder(stream, { mimeType: 'video/webm' });
    mediaRecorderRef.current = recorder;
    chunksRef.current = [];
    recorder.ondataavailable = (e) => chunksRef.current.push(e.data);
    recorder.onstop = () => {
        const url = URL.createObjectURL(new Blob(chunksRef.current, { type: 'video/webm' }));
        const a = document.createElement('a'); a.href = url; a.download = `Record_${channel?.name}.webm`; a.click();
    };
    recorder.start();
    setIsRecording(true);
    setRecordingDuration(0);
    recordingTimerRef.current = window.setInterval(() => setRecordingDuration(p => p + 1), 1000);
  };

  const stopRecording = () => {
    mediaRecorderRef.current?.stop();
    setIsRecording(false);
    if (recordingTimerRef.current) clearInterval(recordingTimerRef.current);
  };

  const { styles } = theme;
  const getErrorDisplay = () => {
      if (errorState === 'network') return { icon: <WifiOff className="w-12 h-12 text-amber-500" />, title: 'Uplink Failed', desc: 'Could not establish connection to the host server.' };
      if (errorState === 'timeout') return { icon: <Clock className="w-12 h-12 text-cyan-500 animate-pulse" />, title: 'Signal Timeout', desc: 'Station is taking too long to respond. Network congestion.' };
      return { icon: <AlertTriangle className="w-12 h-12 text-rose-500" />, title: 'Frequency Lost', desc: 'The carrier wave for this node has been disconnected.' };
  };

  const display = getErrorDisplay();

  return (
    <div className="relative w-full group">
      <div className={`relative w-full aspect-video bg-black ${styles.layoutShape} overflow-hidden border ${styles.border} shadow-[0_40px_120px_rgba(0,0,0,0.9)]`}>

        {/* Ambient Glow behind video */}
        <div className="absolute inset-0 bg-gradient-to-tr from-cyan-500/10 via-transparent to-purple-500/10 opacity-50"></div>

        {errorState !== 'none' && (
            <div className="absolute inset-0 z-40 flex flex-col items-center justify-center text-center p-12 bg-black/95 backdrop-blur-[40px]">
                <div className="relative z-10 flex flex-col items-center space-y-8 animate-in fade-in zoom-in slide-in-from-bottom-8 duration-1000">
                    <div className="w-28 h-28 rounded-full bg-white/5 flex items-center justify-center border border-white/10 shadow-[0_0_80px_rgba(255,255,255,0.05)] relative group">
                        {display.icon}
                        <div className="absolute -inset-6 rounded-full border border-white/5 animate-ping opacity-10"></div>
                    </div>
                    <div>
                        <h3 className="text-white font-black text-4xl uppercase italic tracking-tighter mb-4">{display.title}</h3>
                        <p className="text-white/40 text-[11px] max-w-xs mx-auto leading-relaxed font-bold uppercase tracking-widest">{display.desc}</p>
                    </div>
                    <div className="flex flex-col sm:flex-row gap-4 pt-4">
                        <button onClick={() => window.location.reload()} className="px-12 py-4 bg-white text-black text-[11px] font-black uppercase rounded-full hover:bg-cyan-400 transition-all active:scale-90 flex items-center gap-3">
                            <RefreshCw className="w-4 h-4" /> Force Relink
                        </button>
                        <button onClick={onAutoSkip} className="px-12 py-4 bg-white/5 text-white text-[11px] font-black uppercase rounded-full border border-white/10 hover:bg-white/10 transition-all active:scale-90 flex items-center gap-3">
                            <Shuffle className="w-4 h-4" /> Jump Node
                        </button>
                    </div>
                </div>
            </div>
        )}

        {[0, 1].map((index) => (
            <video
                key={index} ref={videoRefs[index]} playsInline muted={isMuted}
                className={`absolute inset-0 w-full h-full object-contain transition-opacity duration-1000 ${activePlayerIndex === index && errorState === 'none' ? 'opacity-100' : 'opacity-0'}`}
            />
        ))}

        {/* Scanline Effect overlay */}
        <div className="absolute inset-0 pointer-events-none opacity-[0.03] bg-[linear-gradient(rgba(18,16,16,0)_50%,rgba(0,0,0,0.25)_50%),linear-gradient(90deg,rgba(255,0,0,0.06),rgba(0,255,0,0.02),rgba(0,0,255,0.06))] bg-[length:100%_4px,3px_100%]"></div>

        {isRecording && (
          <div className="absolute top-8 left-8 z-40 flex items-center gap-4 bg-black/60 backdrop-blur-2xl px-5 py-2.5 rounded-full border border-red-500/40 shadow-2xl">
             <div className="w-3 h-3 bg-red-600 rounded-full animate-pulse shadow-[0_0_15px_#dc2626]"></div>
             <span className="text-white text-[11px] font-black tracking-widest uppercase italic">Recording</span>
             <span className="text-red-400 font-mono text-xs font-black border-l border-white/10 pl-4">
                 {Math.floor(recordingDuration/60).toString().padStart(2,'0')}:{(recordingDuration%60).toString().padStart(2,'0')}
             </span>
          </div>
        )}

        {loading && errorState === 'none' && (
             <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/80 backdrop-blur-xl z-20 space-y-6">
                <div className="relative w-20 h-20">
                    <div className="absolute inset-0 border-[6px] border-cyan-500/10 rounded-full"></div>
                    <div className="absolute inset-0 border-[6px] border-t-cyan-500 rounded-full animate-spin"></div>
                    <Terminal className="absolute inset-0 m-auto w-6 h-6 text-cyan-500 animate-pulse" />
                </div>
                <div className="text-[11px] text-cyan-500 font-mono font-black uppercase tracking-[0.5em] animate-pulse">Syncing Stream...</div>
             </div>
        )}

        {/* Console UI */}
        <div className={`absolute inset-x-8 bottom-8 p-6 bg-black/60 backdrop-blur-[50px] rounded-[32px] border border-white/10 transition-all duration-700 shadow-2xl ${errorState !== 'none' ? 'opacity-0 translate-y-8' : 'opacity-0 translate-y-4 group-hover:opacity-100 group-hover:translate-y-0'}`}>
            <div className="flex flex-col md:flex-row items-center justify-between gap-6">
                <div className="flex items-center gap-6 min-w-0">
                    <button onClick={() => {
                        const v = videoRefs[activePlayerIndex].current;
                        if (isPlaying) v?.pause(); else v?.play();
                        setIsPlaying(!isPlaying);
                    }} className="w-16 h-16 bg-white text-black rounded-full flex items-center justify-center transition-all hover:scale-110 hover:bg-cyan-400 active:scale-95 shadow-[0_15px_40px_rgba(255,255,255,0.2)]">
                        {isPlaying ? <Square className="w-6 h-6 fill-current" /> : <Play className="w-6 h-6 fill-current ml-1" />}
                    </button>
                    <div className="min-w-0">
                        <div className="flex items-center gap-3 mb-1">
                            <span className="px-2 py-0.5 bg-gradient-to-r from-red-600 to-rose-500 text-[9px] font-black text-white rounded shadow-lg uppercase tracking-widest animate-pulse">Live</span>
                            <h4 className="text-white font-black text-xl tracking-tighter truncate max-w-md uppercase italic leading-none">
                                {channel?.name || 'Searching...'}
                            </h4>
                        </div>
                        <div className="flex items-center gap-3 text-white/30 text-[10px] font-black uppercase tracking-widest mt-2">
                            <div className="flex items-center gap-1.5"><Zap className="w-3.5 h-3.5 text-cyan-400" /> {channel?.group || 'Public'}</div>
                            <div className="w-1 h-1 rounded-full bg-white/20"></div>
                            <div className="flex items-center gap-1.5"><Globe className="w-3.5 h-3.5" /> {country?.name || 'Global'}</div>
                        </div>
                    </div>
                </div>

                <div className="flex items-center gap-2">
                    <button 
                        onClick={onToggleFavorite} 
                        className={`p-4 rounded-[20px] transition-all active:scale-90 shadow-xl ${isFavorite ? 'bg-amber-400 text-black shadow-amber-500/30' : 'bg-white/5 text-white hover:bg-white/10 border border-white/5'}`}
                        title="Favorite"
                    >
                        <Star className={`w-5 h-5 ${isFavorite ? 'fill-current' : ''}`} />
                    </button>

                    <button onClick={takeScreenshot} className="p-4 bg-white/5 text-white hover:bg-white/10 border border-white/5 rounded-[20px] transition-all active:scale-90 shadow-xl">
                        <Camera className="w-5 h-5" />
                    </button>

                    <button onClick={isRecording ? stopRecording : startRecording} className={`p-4 rounded-[20px] transition-all shadow-xl ${isRecording ? 'bg-red-600 text-white animate-pulse' : 'bg-white/5 text-white hover:bg-white/10 border border-white/5'}`}>
                        <Circle className={`w-5 h-5 ${isRecording ? 'fill-current' : ''}`} />
                    </button>

                    <div className="h-10 w-[1px] bg-white/10 mx-2"></div>

                    <div className="flex items-center group/vol">
                      <button onClick={() => setIsMuted(!isMuted)} className="p-4 bg-white/5 border border-white/5 hover:bg-white/10 rounded-[20px] text-white transition-all shadow-xl">
                          {isMuted || volume === 0 ? <VolumeX className="w-5 h-5 text-rose-500" /> : <Volume2 className="w-5 h-5" />}
                      </button>
                      <div className="w-0 overflow-hidden group-hover/vol:w-32 group-hover/vol:ml-4 transition-all duration-500 flex items-center">
                          <input type="range" min="0" max="1" step="0.01" value={isMuted ? 0 : volume} onChange={(e) => { const v = parseFloat(e.target.value); setVolume(v); if (v > 0) setIsMuted(false); }} className="w-28 h-1.5 accent-cyan-500 bg-white/10 rounded-full appearance-none cursor-pointer" />
                      </div>
                    </div>

                    <button onClick={() => videoRefs[activePlayerIndex].current?.requestFullscreen()} className="p-4 bg-white/5 border border-white/5 hover:bg-white/10 rounded-[20px] text-white transition-all shadow-xl">
                        <Maximize className="w-5 h-5" />
                    </button>
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Channel, AppTheme } from '../types';
import { Tv, Search, Radio, Star, Play, Activity, Globe2, X, Command } from 'lucide-react';

interface ChannelGridProps {
  channels: Channel[];
  currentChannel: Channel | null;
  onSelectChannel: (channel: Channel) => void;
  loading: boolean;
  mode: 'tv' | 'radio';
  theme: AppTheme;
  favorites: Channel[];
  onToggleFavorite: (channel: Channel) => void;
  externalFilter?: string;
  onExternalFilterChange?: (filter: string) => void;
}

export const ChannelGrid: React.FC<ChannelGridProps> = ({ 
    channels, currentChannel, onSelectChannel, loading, mode, theme, favorites, onToggleFavorite,
    externalFilter = '', onExternalFilterChange
}) => {
  const [internalFilter, setInternalFilter] = useState('');
  const { styles } = theme;

  useEffect(() => { if (externalFilter) setInternalFilter(''); }, [externalFilter]);

  const filteredChannels = useMemo(() => {
    const activeFilter = (externalFilter || internalFilter).toLowerCase();
    if (!activeFilter) return channels;
    return channels.filter(c => c.name.toLowerCase().includes(activeFilter) || (c.group && c.group.toLowerCase().includes(activeFilter)));
  }, [channels, externalFilter, internalFilter]);

  if (loading) {
    return (
      <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 gap-4">
        {Array.from({ length: 18 }).map((_, i) => (
            <div key={i} className={`h-32 bg-white/5 ${styles.layoutShape} animate-pulse relative overflow-hidden`}>
                <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/[0.05] to-transparent animate-shimmer"></div>
            </div>
        ))}
      </div>
    );
  }

  return (
    <div className="space-y-8">
      <div className={`flex items-center gap-4 p-4 ${styles.input} ${styles.layoutShape} border ${styles.border} shadow-2xl group transition-all`}>
        <Search className={`w-5 h-5 ${styles.textDim} group-focus-within:text-cyan-400 transition-colors`} />
        <input 
            type="text"
            placeholder={externalFilter ? `Search global tag: ${externalFilter}` : "Find channels, topics or genres..."}
            className="bg-transparent border-none focus:outline-none text-[13px] font-bold w-full placeholder:opacity-30 uppercase tracking-widest"
            value={internalFilter}
            onChange={(e) => {
                setInternalFilter(e.target.value);
                if (onExternalFilterChange) onExternalFilterChange('');
            }}
        />
        <div className="hidden md:flex items-center gap-1 opacity-20 group-focus-within:opacity-0 transition-opacity">
            <Command className="w-3 h-3" /> <span className="text-[9px] font-black">S</span>
        </div>
        {(internalFilter || externalFilter) && (
            <button onClick={() => { setInternalFilter(''); if (onExternalFilterChange) onExternalFilterChange(''); }} className="p-2 hover:bg-rose-500/20 text-rose-500 rounded-full transition-colors">
                <X className="w-4 h-4" />
            </button>
        )}
      </div>

      <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 gap-4">
          {filteredChannels.length > 0 ? filteredChannels.map(channel => {
              const isActive = currentChannel?.id === channel.id;
              const isFav = favorites.some(f => f.id === channel.id);

              return (
                  <div
                      key={channel.id}
                      onClick={() => onSelectChannel(channel)}
                      className={`
                        group relative p-5 flex flex-col items-center justify-center text-center transition-all duration-500 cursor-pointer
                        border ${styles.layoutShape} min-w-0 active:scale-95
                        ${isActive 
                            ? `${styles.buttonActive} shadow-[0_20px_40px_rgba(0,0,0,0.4)] scale-105 z-10 border-transparent` 
                            : `${styles.card} ${styles.cardHover} hover:scale-105`}
                      `}
                  >
                      {/* Favorite Marker */}
                      {isFav && !isActive && (
                          <div className="absolute top-2 right-2 text-amber-500 opacity-60">
                              <Star className="w-3 h-3 fill-current" />
                          </div>
                      )}

                      <div className={`w-14 h-14 mb-4 rounded-2xl flex items-center justify-center overflow-hidden transition-all duration-500 group-hover:rotate-3 shadow-inner ${isActive ? 'bg-white/20' : 'bg-black/40 border border-white/5'}`}>
                          {channel.logo ? (
                              <img src={channel.logo} className="w-full h-full object-contain p-2 group-hover:scale-110 transition-transform" loading="lazy" />
                          ) : (
                              mode === 'tv' ? <Tv className={`w-6 h-6 ${isActive ? 'text-black' : 'opacity-20'}`} /> : <Radio className={`w-6 h-6 ${isActive ? 'text-black' : 'opacity-20'}`} />
                          )}
                      </div>

                      <div className="flex flex-col gap-1 w-full">
                          <span className={`text-[11px] font-black tracking-tighter line-clamp-2 uppercase italic leading-tight ${isActive ? 'text-black' : styles.textMain}`}>
                              {channel.name}
                          </span>
                          <span className={`text-[8px] font-black uppercase tracking-widest opacity-30 group-hover:opacity-60 transition-opacity ${isActive ? 'text-black/60' : styles.textDim}`}>
                              {channel.group || 'NODE'}
                          </span>
                      </div>

                      {isActive && (
                          <div className="absolute bottom-[-2px] left-1/2 -translate-x-1/2 w-1/2 h-1 bg-white rounded-full shadow-[0_0_10px_#fff]"></div>
                      )}
                  </div>
              );
          }) : (
              <div className="col-span-full py-24 text-center">
                  <Globe2 className="w-16 h-16 mx-auto mb-6 opacity-5 animate-pulse" />
                  <div className="opacity-20 font-black uppercase italic tracking-[0.4em] text-xs">
                      No matching frequencies found
                  </div>
              </div>
          )}
      </div>
    </div>
  );
};

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Country, AppTheme, Channel, AppSettings, Reminder } from '../types';
import { Search, Globe, X, Tv, Radio, Palette, Star, Upload, Volume2, VolumeX, Settings, ChevronDown, ChevronUp, CalendarClock, Trash2, Play, Music, Plus, History, Layers } from 'lucide-react';

interface SidebarProps {
  countries: Country[];
  selectedCountry: Country | null;
  onSelectCountry: (country: Country) => void;
  isOpen: boolean;
  onClose: () => void;
  mode: 'tv' | 'radio';
  onModeChange: (mode: 'tv' | 'radio') => void;
  themes: AppTheme[];
  currentTheme: AppTheme;
  onThemeChange: (theme: AppTheme) => void;
  favorites: Channel[];
  onSelectFavorite: (channel: Channel) => void;
  onImportM3U: (content: string) => void;
  settings: AppSettings;
  onToggleSound: () => void;
  reminders: Reminder[];
  onDeleteReminder: (id: string) => void;
  onPlayReminder: (channelId: string) => void;
  history: Channel[];
}

export const Sidebar: React.FC<SidebarProps> = ({ 
    countries, selectedCountry, onSelectCountry, isOpen, onClose, mode, onModeChange, themes,
    currentTheme, onThemeChange, favorites, onSelectFavorite, onImportM3U, settings,
    onToggleSound, reminders, onDeleteReminder, onPlayReminder, history
}) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [showThemes, setShowThemes] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [activeTab, setActiveTab] = useState<'favorites' | 'history' | 'schedule' | null>('favorites');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const filteredCountries = useMemo(() => {
    if (!searchQuery) return countries;
    const lowerQ = searchQuery.toLowerCase();
    return countries.filter(c => c.name.toLowerCase().includes(lowerQ) || c.code.toLowerCase().includes(lowerQ));
  }, [countries, searchQuery]);

  const modeFavorites = useMemo(() => favorites.filter(c => (c.type || 'tv') === mode), [favorites, mode]);
  const { styles } = currentTheme;

  return (
    <>
        {isOpen && <div className="fixed inset-0 bg-black/60 z-40 md:hidden backdrop-blur-xl transition-all" onClick={onClose} />}

        <aside className={`
            fixed md:relative z-50 h-full ${styles.bgSidebar} w-85 flex flex-col min-w-0
            transition-all duration-700 cubic-bezier(0.4, 0, 0.2, 1)
            ${isOpen ? 'translate-x-0' : '-translate-x-full md:translate-x-0'}
            ${styles.shadow} shadow-2xl
        `}>

        <div className={`p-8 pb-6 border-b ${styles.border} flex items-center justify-between shrink-0`}>
            <div className={`flex items-center gap-4 ${styles.textMain}`}>
                <div className={`p-3 bg-white text-black rounded-2xl shadow-[0_10px_20px_rgba(255,255,255,0.1)] shrink-0`}>
                    <Globe className="w-5 h-5" />
                </div>
                <div className="flex flex-col">
                    <h1 className="text-2xl font-black tracking-tighter uppercase italic leading-none">Global</h1>
                    <span className="text-[9px] font-black tracking-[0.4em] uppercase opacity-40 mt-1">Streaming Node</span>
                </div>
            </div>
            <button onClick={onClose} className={`md:hidden ${styles.textDim} p-2 hover:bg-white/5 rounded-full transition-colors`}>
                <X className="w-6 h-6" />
            </button>
        </div>

        <div className="p-6 space-y-6 shrink-0">
            {/* Mode Switcher Pill */}
            <div className={`flex p-1.5 ${styles.layoutShape} bg-black/40 border ${styles.border} shadow-inner`}>
                <button 
                    onClick={() => onModeChange('tv')}
                    className={`flex-1 flex items-center justify-center gap-2 py-3 ${styles.layoutShape} text-[10px] font-black transition-all duration-500 uppercase tracking-widest ${mode === 'tv' ? `${styles.buttonActive} shadow-lg` : `${styles.textDim} hover:bg-white/5`}`}
                >
                    <Tv className="w-4 h-4" /> Vision
                </button>
                <button 
                    onClick={() => onModeChange('radio')}
                    className={`flex-1 flex items-center justify-center gap-2 py-3 ${styles.layoutShape} text-[10px] font-black transition-all duration-500 uppercase tracking-widest ${mode === 'radio' ? `${styles.buttonActive} shadow-lg` : `${styles.textDim} hover:bg-white/5`}`}
                >
                    <Radio className="w-4 h-4" /> Waves
                </button>
            </div>

            <div className="flex gap-2">
                {(['favorites', 'history', 'schedule'] as const).map((tab) => (
                    <button 
                        key={tab}
                        onClick={() => setActiveTab(activeTab === tab ? null : tab)}
                        className={`flex-1 flex flex-col items-center justify-center py-3 ${styles.layoutShape} transition-all border ${activeTab === tab ? styles.buttonActive : `${styles.card} border-transparent opacity-60 hover:opacity-100`}`}
                    >
                        {tab === 'favorites' && <Star className={`w-4 h-4 mb-1.5 ${activeTab === tab ? 'fill-current' : ''}`} />}
                        {tab === 'history' && <History className="w-4 h-4 mb-1.5" />}
                        {tab === 'schedule' && <CalendarClock className="w-4 h-4 mb-1.5" />}
                        <span className="text-[8px] font-black uppercase tracking-widest">{tab === 'favorites' ? 'Saved' : tab === 'history' ? 'Logs' : 'Alert'}</span>
                    </button>
                ))}
            </div>

            {activeTab && (
                <div className={`p-2 ${styles.card} ${styles.layoutShape} border ${styles.border} space-y-1.5 max-h-64 overflow-y-auto ${currentTheme.type === 'web95' ? 'scrollbar-web95' : 'scrollbar-thin'} animate-in slide-in-from-top-4 duration-500 shadow-xl`}>
                    {activeTab === 'favorites' && (
                        modeFavorites.length > 0 ? modeFavorites.map(ch => (
                            <button key={ch.id} onClick={() => { onSelectFavorite(ch); if (window.innerWidth < 768) onClose(); }} className={`w-full flex items-center gap-4 p-3 ${styles.layoutShape} hover:bg-white/5 text-left group transition-all`}>
                                <div className="w-9 h-9 rounded-xl bg-black/40 shrink-0 flex items-center justify-center overflow-hidden shadow-inner group-hover:scale-110 transition-transform">
                                    {ch.logo ? <img src={ch.logo} className="w-full h-full object-contain p-1.5" /> : <Star className="w-4 h-4 opacity-20" />}
                                </div>
                                <div className="flex flex-col min-w-0">
                                    <span className={`text-[11px] font-black truncate uppercase tracking-tight ${styles.textMain}`}>{ch.name}</span>
                                    <span className={`text-[8px] font-bold opacity-30 uppercase tracking-tighter`}>{ch.group || 'General'}</span>
                                </div>
                            </button>
                        )) : <div className="py-10 text-center text-[9px] font-black opacity-20 uppercase italic">Collection Empty</div>
                    )}
                </div>
            )}
        </div>

        <div className={`flex-1 overflow-y-auto px-6 space-y-2 ${currentTheme.type === 'web95' ? 'scrollbar-web95' : 'scrollbar-thin'}`}>
            <div className={`sticky top-0 z-20 pt-2 pb-4 ${styles.bgSidebar}`}>
                <div className={`relative ${styles.input} ${styles.layoutShape} border ${styles.border} flex items-center px-5 py-3.5 transition-all focus-within:ring-2 focus-within:ring-white/10 group shadow-inner`}>
                    <Search className={`w-4 h-4 ${styles.textDim} group-focus-within:text-white transition-colors`} />
                    <input 
                        type="text" 
                        placeholder="Search regions..." 
                        className="bg-transparent border-none focus:outline-none text-[11px] w-full ml-4 font-black uppercase tracking-widest placeholder:opacity-30"
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                    />
                </div>
            </div>

            <div className="space-y-1.5 pb-8">
                {filteredCountries.map(country => (
                    <button
                        key={country.code}
                        onClick={() => { onSelectCountry(country); if (window.innerWidth < 768) onClose(); }}
                        className={`
                            w-full flex items-center gap-5 p-4 ${styles.layoutShape} transition-all group relative active:scale-95
                            ${selectedCountry?.code === country.code 
                                ? `${styles.buttonActive} shadow-xl scale-[1.02] border-none` 
                                : `${styles.textDim} hover:bg-white/5`
                            }
                        `}
                    >
                        <span className="text-3xl shrink-0 group-hover:rotate-6 transition-transform filter drop-shadow-md">{country.flag}</span>
                        <div className="flex flex-col min-w-0">
                            <span className={`text-xs font-black truncate uppercase tracking-tight ${selectedCountry?.code === country.code ? 'text-black' : styles.textMain}`}>{country.name}</span>
                            <span className={`text-[8px] font-black uppercase tracking-[0.2em] opacity-30 ${selectedCountry?.code === country.code ? 'text-black' : ''}`}>{country.code} Network</span>
                        </div>
                        {selectedCountry?.code === country.code && (
                            <div className="ml-auto w-1.5 h-1.5 rounded-full bg-black shadow-lg animate-pulse"></div>
                        )}
                    </button>
                ))}
            </div>
        </div>

        <div className={`p-6 border-t ${styles.border} bg-black/10 space-y-4`}>
            <button onClick={() => fileInputRef.current?.click()} className={`w-full flex items-center justify-center gap-3 py-4 ${styles.layoutShape} ${styles.border} ${styles.button} text-[10px] font-black uppercase tracking-widest transition-all hover:scale-[1.02] active:scale-95`}>
                <Upload className="w-4 h-4" /> Global Link Protocol
            </button>
            <input type="file" accept=".m3u,.m3u8" ref={fileInputRef} className="hidden" onChange={(e) => {
                const f = e.target.files?.[0];
                if (f) {
                    const r = new FileReader();
                    r.onload = (ev) => { if (ev.target?.result) onImportM3U(ev.target.result as string); };
                    r.readAsText(f);
                }
            }} />

            <div className="flex gap-3">
                <button onClick={() => { setShowSettings(!showSettings); setShowThemes(false); }} className={`flex-1 flex items-center justify-center gap-2 py-3.5 text-[10px] font-black uppercase ${styles.button} ${styles.border} ${styles.layoutShape} transition-all ${showSettings ? styles.buttonActive : 'opacity-60'}`}>
                    <Settings className="w-4 h-4" /> Setup
                </button>
                <button onClick={() => { setShowThemes(!showThemes); setShowSettings(false); }} className={`flex-1 flex items-center justify-center gap-2 py-3.5 text-[10px] font-black uppercase ${styles.button} ${styles.border} ${styles.layoutShape} transition-all ${showThemes ? styles.buttonActive : 'opacity-60'}`}>
                    <Palette className="w-4 h-4" /> Visuals
                </button>
            </div>

            {showThemes && (
                 <div className={`p-2.5 ${styles.card} ${styles.layoutShape} border ${styles.border} space-y-1 max-h-56 overflow-y-auto scrollbar-none animate-in slide-in-from-bottom-4 duration-500 shadow-2xl`}>
                    <div className="text-[8px] font-black uppercase tracking-widest opacity-20 mb-2 px-3">Available UI Protocols</div>
                    {themes.map(t => (
                        <button key={t.id} onClick={() => { onThemeChange(t); setShowThemes(false); }} className={`w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest ${styles.layoutShape} transition-all ${currentTheme.id === t.id ? styles.buttonActive : 'hover:bg-white/5 opacity-60 hover:opacity-100'}`}>
                            {t.name}
                        </button>
                    ))}
                 </div>
            )}
        </div>
      </aside>
    </>
  );
};

