const FAVORITES_COUNTRY: Country = { name: '收藏信道', code: 'FAVORITES', languages: [], flag: '⭐' };
const GLOBAL_EXPLORE_COUNTRY: Country = { name: '星空漫游', code: 'GLOBAL_EXPLORE', languages: ['en'], flag: '🛸' };
const HOT_TAGS = ['新闻', '体育', '电影', '音乐', '中文', '少儿', '探索', '动作', '风景', '喜剧', '经典', '时尚'];

const App: React.FC = () => {
  const [isAppReady, setIsAppReady] = useState(false);
  const [countries, setCountries] = useState<Country[]>([]);
  const [selectedCountry, setSelectedCountry] = useState<Country | null>(null);
  const [channels, setChannels] = useState<Channel[]>([]);
  const [currentChannel, setCurrentChannel] = useState<Channel | null>(null);
  const [history, setHistory] = useState<Channel[]>([]);
  const [localTime, setLocalTime] = useState('--:--:--');
  const [loadingChannels, setLoadingChannels] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [mode, setMode] = useState<'tv' | 'radio'>('tv');
  const [favorites, setFavorites] = useState<Channel[]>([]);
  const [currentTheme, setCurrentTheme] = useState<AppTheme>(THEMES[0]);
  const [channelFilter, setChannelFilter] = useState('');
  const [discoveryTag, setDiscoveryTag] = useState<string | null>(null);
  const [reminders, setReminders] = useState<Reminder[]>([]);
  const [showSchedule, setShowSchedule] = useState(false);
  const [activeAlarm, setActiveAlarm] = useState<Reminder | null>(null);

  useEffect(() => {
    try {
        const savedFavs = localStorage.getItem('global_favorites');
        if (savedFavs) setFavorites(JSON.parse(savedFavs));
        const savedReminders = localStorage.getItem('global_reminders');
        if (savedReminders) setReminders(JSON.parse(savedReminders));
        const savedThemeId = localStorage.getItem('app_theme_id');
        if (savedThemeId) {
            const t = THEMES.find(th => th.id === savedThemeId);
            if (t) setCurrentTheme(t);
        }
    } catch (e) { console.error("Storage failed", e); }
  }, []);

  useEffect(() => {
    const timer = setInterval(() => {
      try {
        const tz = (selectedCountry && selectedCountry.code !== 'GLOBAL') ? getTimezone(selectedCountry.code) : 'UTC';
        setLocalTime(new Intl.DateTimeFormat('zh-CN', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false, timeZone: tz }).format(new Date()));
        const nowStr = new Date().toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit', hour12: false });
        const trigger = reminders.find(r => r.timeStr === nowStr);
        if (trigger && !activeAlarm) setActiveAlarm(trigger);
      } catch (e) { setLocalTime('SEARCHING...'); }
    }, 1000);
    return () => clearInterval(timer);
  }, [selectedCountry, reminders, activeAlarm]);

  useEffect(() => {
    const init = async () => {
      const data = await fetchCountries();
      setCountries([FAVORITES_COUNTRY, ...data]);
      const initialCountry = data.find(c => c.code === 'GLOBAL') || data[0];
      setSelectedCountry(initialCountry);
      setIsAppReady(true);
    };
    init();
  }, []);

  const loadContent = async (refresh = false) => {
    if (!selectedCountry) return;
    setLoadingChannels(true);
    try {
      let data: Channel[] = [];
      if (discoveryTag) {
        data = await fetchGlobalChannelsByCategory(discoveryTag);
      } else {
        data = mode === 'tv' ? await fetchChannelsByCountry(selectedCountry.code, refresh) : await fetchRadioStations(selectedCountry.code, refresh);
      }
      setChannels(data);
      if (data.length > 0 && (!currentChannel || refresh)) {
          const firstAvailable = data.find(c => c.url) || data[0];
          if (!currentChannel) setCurrentChannel(firstAvailable);
      }
    } catch (err) { setChannels([]); }
    finally { setLoadingChannels(false); }
  };

  useEffect(() => { if (isAppReady) loadContent(); }, [selectedCountry, mode, isAppReady, discoveryTag]);

  const handleChannelSelect = (channel: Channel) => {
    setCurrentChannel(channel);
    setHistory(prev => [channel, ...prev.filter(c => c.id !== channel.id)].slice(0, 10));
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleTagClick = (tag: string) => {
      setDiscoveryTag(discoveryTag === tag ? null : tag);
      setChannelFilter(''); 
  };

  const toggleFavorite = (channel: Channel) => {
    const newFavs = favorites.some(f => f.id === channel.id) ? favorites.filter(f => f.id !== channel.id) : [...favorites, channel];
    setFavorites(newFavs);
    localStorage.setItem('global_favorites', JSON.stringify(newFavs));
  };

  const handleThemeChange = (theme: AppTheme) => {
    setCurrentTheme(theme);
    localStorage.setItem('app_theme_id', theme.id);
  };

  if (!isAppReady) return (
    <div className="h-screen w-full bg-[#030305] flex flex-col items-center justify-center overflow-hidden">
      <div className="relative scale-150 mb-12">
        <div className="w-16 h-16 border-[3px] border-cyan-500/10 border-t-cyan-400 rounded-full animate-spin"></div>
        <div className="absolute inset-0 flex items-center justify-center">
            <Globe2 className="w-6 h-6 text-cyan-400 animate-pulse" />
        </div>
      </div>
      <div className="text-white/20 font-black text-xs uppercase tracking-[0.8em] animate-pulse">Initializing Global Uplink</div>
    </div>
  );

  const { styles } = currentTheme;

  return (
    <div className={`flex h-screen w-full ${styles.bgMain} ${styles.font} overflow-hidden relative`}>
      <Sidebar 
        countries={countries} selectedCountry={discoveryTag ? GLOBAL_EXPLORE_COUNTRY : selectedCountry} 
        onSelectCountry={(c) => { setDiscoveryTag(null); setSelectedCountry(c); }}
        isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} mode={mode} onModeChange={setMode}
        themes={THEMES} currentTheme={currentTheme} onThemeChange={handleThemeChange}
        favorites={favorites} onSelectFavorite={handleChannelSelect} history={history}
        onImportM3U={() => {}} settings={{enableSound: true}} onToggleSound={() => {}} 
        reminders={reminders} onDeleteReminder={(id) => {
            const next = reminders.filter(r => r.id !== id);
            setReminders(next); localStorage.setItem('global_reminders', JSON.stringify(next));
        }} onPlayReminder={handleChannelSelect}
      />

      <main className="flex-1 flex flex-col h-full min-w-0 z-10 relative">
        <header className={`shrink-0 px-8 py-5 flex items-center justify-between border-b ${styles.border} ${styles.bgSidebar} backdrop-blur-3xl z-30 shadow-2xl`}>
            <div className="flex items-center gap-6">
                <button onClick={() => setSidebarOpen(true)} className={`md:hidden p-3 rounded-full ${styles.card} ${styles.textMain} active:scale-90 transition-transform`}><Menu className="w-6 h-6" /></button>
                <div className="flex items-center gap-4 group">
                    <div className="relative">
                        <span className="text-3xl drop-shadow-2xl filter saturate-150 transition-transform group-hover:scale-125 group-hover:rotate-12 inline-block">
                            {discoveryTag ? '🛸' : selectedCountry?.flag}
                        </span>
                    </div>
                    <div className="flex flex-col">
                        <h1 className={`text-2xl font-black uppercase italic tracking-tighter leading-none ${styles.textMain} text-gradient`}>
                            {discoveryTag ? `${discoveryTag}` : selectedCountry?.name}
                        </h1>
                        <div className="flex items-center gap-2 mt-1.5">
                            <div className="w-1.5 h-1.5 rounded-full bg-cyan-400 animate-ping"></div>
                            <span className={`text-[9px] font-black tracking-widest uppercase opacity-40 ${styles.textDim}`}>
                                {channels.length} Ground Nodes Active
                            </span>
                        </div>
                    </div>
                </div>
            </div>

            <div className="flex items-center gap-8">
                <div className={`hidden lg:flex flex-col items-end gap-0.5`}>
                    <span className={`text-[9px] font-black uppercase tracking-[0.3em] ${styles.textDim} opacity-40`}>Node Timeline</span>
                    <span className={`text-base font-mono font-black tracking-widest ${styles.textMain} drop-shadow-lg`}>{localTime}</span>
                </div>

                <div className="flex items-center gap-3">
                    <button onClick={() => setShowSchedule(true)} className={`p-3.5 rounded-2xl ${styles.button} hover:scale-110 active:scale-95 transition-all shadow-xl relative group`}>
                        <AlarmClock className="w-5 h-5" />
                        {reminders.length > 0 && <span className="absolute top-2.5 right-2.5 w-2.5 h-2.5 bg-rose-500 rounded-full border-2 border-black animate-pulse"></span>}
                    </button>
                    <button onClick={() => loadContent(true)} className={`p-3.5 rounded-2xl ${styles.button} hover:rotate-180 transition-all duration-700 shadow-xl group ${loadingChannels ? 'animate-spin' : ''}`}>
                        <RefreshCw className="w-5 h-5 group-hover:text-cyan-400" />
                    </button>
                </div>
            </div>
        </header>

        <div className={`flex-1 overflow-y-auto ${currentTheme.type === 'web95' ? 'scrollbar-web95' : 'scrollbar-thin'}`}>
            <div className="px-8 py-10 max-w-[1920px] mx-auto">
                <div className="flex flex-col 2xl:flex-row gap-10">
                    <div className="flex-1 min-w-0 space-y-10">
                        <section className="space-y-8">
                            <VideoPlayer 
                              channel={currentChannel} country={discoveryTag ? GLOBAL_EXPLORE_COUNTRY : selectedCountry} theme={currentTheme}
                              isFavorite={!!currentChannel && favorites.some(f => f.id === currentChannel.id)}
                              onToggleFavorite={() => currentChannel && toggleFavorite(currentChannel)} 
                              onAutoSkip={() => {
                                  if (channels.length > 1) {
                                      const next = channels[Math.floor(Math.random()*channels.length)];
                                      handleChannelSelect(next);
                                  }
                              }}
                            />

                            <FavoritesBar favorites={favorites} currentChannel={currentChannel} onSelectChannel={handleChannelSelect} theme={currentTheme} mode={mode} />
                        </section>

                        <section className="space-y-8">
                            <div className="flex flex-col space-y-8">
                                <div className="flex items-center justify-between">
                                    <div className="flex items-center gap-5">
                                        <div className={`w-2 h-10 bg-gradient-to-b from-cyan-400 via-blue-600 to-purple-600 rounded-full shadow-[0_0_20px_rgba(6,182,212,0.5)] animate-pulse`}></div>
                                        <div className="flex flex-col">
                                            <h2 className={`text-3xl font-black uppercase italic tracking-tighter ${styles.textMain}`}>
                                                Wave Library
                                            </h2>
                                            <span className="text-[9px] font-black uppercase tracking-[0.5em] opacity-30">Scan results for current node</span>
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-2">
                                        <div className="px-4 py-2 bg-white/5 border border-white/5 rounded-full text-[10px] font-black uppercase opacity-40 hover:opacity-100 transition-opacity flex items-center gap-2">
                                            <Command className="w-3 h-3" /> Filters Enabled
                                        </div>
                                    </div>
                                </div>

                                <div className="flex flex-wrap gap-3">
                                    {HOT_TAGS.map(tag => (
                                        <button 
                                            key={tag} 
                                            onClick={() => handleTagClick(tag)} 
                                            className={`
                                              px-6 py-2.5 ${styles.layoutShape} text-[11px] font-black border transition-all duration-300 transform active:scale-90
                                              ${discoveryTag === tag 
                                                  ? styles.buttonActive 
                                                  : `${styles.button} opacity-30 hover:opacity-100 hover:scale-105 hover:bg-white/5`
                                              }
                                            `}
                                        >
                                            # {tag}
                                        </button>
                                    ))}
                                    {(discoveryTag || channelFilter) && (
                                        <button onClick={() => { setDiscoveryTag(null); setChannelFilter(''); }} className="px-6 py-2.5 rounded-full text-[11px] font-black bg-rose-500/10 text-rose-500 border border-rose-500/20 hover:bg-rose-500 hover:text-white transition-all">Clear Search</button>
                                    )}
                                </div>
                            </div>

                            <ChannelGrid 
                                channels={channels} currentChannel={currentChannel} onSelectChannel={handleChannelSelect} 
                                loading={loadingChannels} mode={mode} theme={currentTheme} favorites={favorites} 
                                onToggleFavorite={toggleFavorite} externalFilter={channelFilter} onExternalFilterChange={setChannelFilter}
                            />
                        </section>
                    </div>

                    <div className="2xl:w-[400px] shrink-0 space-y-8">
                        <div className="2xl:sticky 2xl:top-10 space-y-8">
                            <AiChatPet theme={currentTheme} currentChannels={channels} onSelectChannel={handleChannelSelect} />

                            <div className={`${styles.card} p-8 ${styles.layoutShape} border ${styles.border} group overflow-hidden relative shadow-2xl`}>
                                <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-cyan-500/0 via-cyan-500/40 to-cyan-500/0"></div>
                                <h3 className="text-[11px] font-black uppercase tracking-[0.4em] mb-8 opacity-40 flex items-center gap-3"><History className="w-5 h-5 text-cyan-400" /> Temporal Log</h3>
                                <div className="space-y-4">
                                    {history.length > 0 ? history.map(h => (
                                        <div key={h.id} onClick={() => handleChannelSelect(h)} className={`flex items-center gap-5 p-4 rounded-3xl hover:bg-white/5 cursor-pointer group/item transition-all border border-transparent hover:border-white/5 active:scale-95`}>
                                            <div className="w-12 h-12 rounded-2xl bg-black/60 flex items-center justify-center shrink-0 overflow-hidden shadow-2xl border border-white/5 group-hover/item:scale-110 transition-transform">
                                                {h.logo ? <img src={h.logo} className="w-full h-full object-contain p-2" /> : <History className="w-5 h-5 opacity-20" />}
                                            </div>
                                            <div className="flex flex-col min-w-0">
                                                <span className={`text-xs font-black uppercase truncate italic tracking-tighter ${styles.textMain}`}>{h.name}</span>
                                                <span className={`text-[9px] font-black opacity-20 uppercase tracking-widest mt-0.5`}>{h.group || 'Public Wave'}</span>
                                            </div>
                                        </div>
                                    )) : (
                                        <div className="py-12 text-center text-[10px] font-black opacity-10 uppercase italic tracking-widest">History Buffer Empty</div>
                                    )}
                                </div>
                            </div>

                            <button onClick={() => { if(channels.length > 0) handleChannelSelect(channels[Math.floor(Math.random()*channels.length)]) }} className={`w-full py-6 ${styles.buttonPrimary} ${styles.layoutShape} font-black uppercase text-xs flex items-center justify-center gap-4 shadow-2xl hover:translate-y-[-4px] active:translate-y-[2px] transition-all transform saturate-150`}>
                                <Shuffle className="w-5 h-5" /> Sync Random Node
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        </div>
      </main>

      <ScheduleList 
        reminders={reminders} isOpen={showSchedule} onClose={() => setShowSchedule(false)} 
        onDelete={(id) => { const next = reminders.filter(r => r.id !== id); setReminders(next); localStorage.setItem('global_reminders', JSON.stringify(next)); }}
        theme={currentTheme} onPlayChannel={(id) => { const ch = channels.find(c => c.id === id); if(ch) handleChannelSelect(ch); }}
        allChannels={channels}
      />
      <AlarmModal reminder={activeAlarm} onClose={() => setActiveAlarm(null)} onWatch={(id) => { const ch = channels.find(c => c.id === id); if(ch) handleChannelSelect(ch); setActiveAlarm(null); }} theme={currentTheme} />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Country, AppTheme, Channel, AppSettings, Reminder } from '../types';
