                    <Globe className="w-6 h-6" />
                </div>
                <div className="flex flex-col">
                    <h1 className="text-3xl font-black tracking-tighter uppercase italic leading-none">Global</h1>
                    <div className="flex items-center gap-2 mt-2">
                        <span className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></span>
                        <span className="text-[10px] font-black tracking-[0.3em] uppercase opacity-30 mt-0.5">Live Terminal</span>
