                    onClick={() => onModeChange('radio')}
                    className={`flex-1 flex items-center justify-center gap-3 py-4 ${styles.layoutShape} text-[11px] font-black transition-all duration-500 uppercase tracking-widest ${mode === 'radio' ? `${styles.buttonActive}` : `${styles.textDim} hover:bg-white/5`}`}
                >
                    <Radio className="w-4.5 h-4.5" /> Waves
