        <div className={`flex-1 overflow-y-auto px-8 space-y-3 ${currentTheme.type === 'web95' ? 'scrollbar-web95' : 'scrollbar-thin'}`}>
            <div className={`sticky top-0 z-20 pt-2 pb-6 ${styles.bgSidebar}`}>
                <div className={`relative ${styles.input} ${styles.layoutShape} border ${styles.border} flex items-center px-6 py-4.5 transition-all focus-within:ring-4 focus-within:ring-cyan-500/10 group shadow-2xl`}>
                    <Search className={`w-5 h-5 ${styles.textDim} group-focus-within:text-cyan-400 transition-colors`} />
                    <input 
                        type="text" 
                        placeholder="Scan Region Frequencies..." 
                        className="bg-transparent border-none focus:outline-none text-xs w-full ml-5 font-black uppercase tracking-[0.2em] placeholder:opacity-20"
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                    />
                </div>
            </div>

            <div className="space-y-2 pb-12">
                {filteredCountries.map(country => (
                    <button
                        key={country.code}
                        onClick={() => { onSelectCountry(country); if (window.innerWidth < 768) onClose(); }}
                        className={`
                            w-full flex items-center gap-6 p-5 ${styles.layoutShape} transition-all group relative active:scale-95
                            ${selectedCountry?.code === country.code 
                                ? `${styles.buttonActive} shadow-2xl scale-[1.02] border-none` 
                                : `${styles.textDim} hover:bg-white/5 border border-transparent hover:border-white/5`
                            }
                        `}
                    >
                        <span className="text-4xl shrink-0 group-hover:rotate-12 group-hover:scale-125 transition-transform filter drop-shadow-xl">{country.flag}</span>
                        <div className="flex flex-col min-w-0">
                            <span className={`text-sm font-black truncate uppercase tracking-tighter italic ${selectedCountry?.code === country.code ? 'text-black' : styles.textMain}`}>{country.name}</span>
                            <span className={`text-[9px] font-black uppercase tracking-[0.3em] opacity-30 ${selectedCountry?.code === country.code ? 'text-black' : ''}`}>{country.code} Local Link</span>
                        </div>
                        {selectedCountry?.code === country.code && (
                            <div className="ml-auto flex items-center gap-2">
                                <Check className="w-5 h-5 text-black" />
                            </div>
                        )}
                    </button>
                ))}
            </div>
        </div>

        <div className={`p-8 border-t ${styles.border} bg-black/20 space-y-6 relative`}>
            {/* 解决背景全白的主题选择器菜单 */}
            {showThemes && (
                 <div className="absolute bottom-[calc(100%+20px)] left-8 right-8 z-[100] p-4 bg-[#0a0a0f] border border-white/10 rounded-[24px] shadow-[0_30px_100px_rgba(0,0,0,0.8)] animate-in slide-in-from-bottom-6 duration-500 overflow-hidden">
                    <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-cyan-500 to-transparent opacity-50"></div>
                    <div className="text-[10px] font-black uppercase tracking-[0.4em] text-white/40 mb-4 px-3">System Interface Protocol</div>
                    <div className="grid grid-cols-1 gap-2">
                        {themes.map(t => (
                            <button 
                                key={t.id} 
                                onClick={() => { onThemeChange(t); setShowThemes(false); }} 
                                className={`
                                    w-full text-left px-5 py-4 text-[11px] font-black uppercase tracking-widest rounded-xl transition-all flex items-center justify-between
                                    ${currentTheme.id === t.id 
                                        ? 'bg-white text-black shadow-2xl' 
                                        : 'bg-white/5 text-white/60 hover:bg-white/10 hover:text-white'
                                    }
                                `}
                            >
                                {t.name}
                                {currentTheme.id === t.id && <Layers className="w-4 h-4" />}
                            </button>
                        ))}
                    </div>
                 </div>
            )}

            <button onClick={() => fileInputRef.current?.click()} className={`w-full flex items-center justify-center gap-4 py-5 ${styles.layoutShape} border ${styles.border} ${styles.button} text-[11px] font-black uppercase tracking-widest transition-all hover:scale-[1.02] hover:bg-white/5 active:scale-95 shadow-xl`}>
                <Upload className="w-5 h-5" /> Import Node Link
            </button>
            <input type="file" accept=".m3u,.m3u8" ref={fileInputRef} className="hidden" onChange={(e) => {
                const f = e.target.files?.[0];
                if (f) {
                    const r = new FileReader();
                    r.onload = (ev) => { if (ev.target?.result) onImportM3U(ev.target.result as string); };
                    r.readAsText(f);
                }
            }} />

            <div className="flex gap-4">
                <button onClick={() => setShowThemes(!showThemes)} className={`flex-1 flex items-center justify-center gap-3 py-4 text-[11px] font-black uppercase ${styles.button} ${styles.border} ${styles.layoutShape} transition-all hover:scale-105 active:scale-95 shadow-xl ${showThemes ? 'bg-white text-black border-white' : ''}`}>
                    <Palette className="w-5 h-5" /> Visuals
                </button>
                <button className={`p-4 ${styles.button} ${styles.border} ${styles.layoutShape} transition-all hover:scale-105 active:scale-95 shadow-xl`}>
                    <Settings className="w-5 h-5" />
                </button>
            </div>
        </div>
      </aside>
    </>
  );
};

