const FAVORITES_COUNTRY: Country = { name: '收藏信道', code: 'FAVORITES', languages: [], flag: '⭐' };
const GLOBAL_EXPLORE_COUNTRY: Country = { name: '星空漫游', code: 'GLOBAL_EXPLORE', languages: ['en'], flag: '🛸' };
const HOT_TAGS = ['新闻', '体育', '电影', '音乐', '少儿', '探索', '时尚', '风景', '喜剧'];

const TRANSLATIONS = {
  zh: {
    loading: '链路建立中...',
    nodesSynchronized: '个节点已同步',
    nodeTime: '节点时间',
    discoveryTerminal: '频道探索终端',
    activityLog: '活动历史日志',
    logsEmpty: '日志为空',
