    neuralRandomize: 'Random Station',
    reset: 'RESET',
    favoritesTitle: 'Saved',
    global: 'Global'
  }
};

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>(() => (localStorage.getItem('app_lang') as Language) || 'zh');
  const [isAppReady, setIsAppReady] = useState(false);
  const [countries, setCountries] = useState<Country[]>([]);
  const [selectedCountry, setSelectedCountry] = useState<Country | null>(null);
  const [channels, setChannels] = useState<Channel[]>([]);
  const [currentChannel, setCurrentChannel] = useState<Channel | null>(null);
  const [history, setHistory] = useState<Channel[]>([]);
  const [localTime, setLocalTime] = useState('--:--:--');
  const [loadingChannels, setLoadingChannels] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [mode, setMode] = useState<'tv' | 'radio'>('tv');
  const [favorites, setFavorites] = useState<Channel[]>([]);
  const [currentTheme, setCurrentTheme] = useState<AppTheme>(THEMES[0]);
  const [channelFilter, setChannelFilter] = useState('');
  const [discoveryTag, setDiscoveryTag] = useState<string | null>(null);
  const [reminders, setReminders] = useState<Reminder[]>([]);
  const [showSchedule, setShowSchedule] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [activeAlarm, setActiveAlarm] = useState<Reminder | null>(null);
  const [settings, setSettings] = useState<AppSettings>(() => {
    const saved = localStorage.getItem('app_settings');
    return saved ? JSON.parse(saved) : { enableSound: true };
  });

  const t = TRANSLATIONS[lang];

  useEffect(() => {
    localStorage.setItem('app_settings', JSON.stringify(settings));
  }, [settings]);

  useEffect(() => {
    localStorage.setItem('app_lang', lang);
  }, [lang]);

  useEffect(() => {
    const init = async () => {
      const data = await fetchCountries();
      const globalNode = data.find(c => c.code === 'GLOBAL') || GLOBAL_COUNTRY;
      setCountries([FAVORITES_COUNTRY, ...data]);

      const savedThemeId = localStorage.getItem('app_theme_id');
      if (savedThemeId) {
          const th = THEMES.find(th => th.id === savedThemeId);
          if (th) setCurrentTheme(th);
      }

      setSelectedCountry(globalNode);

      const savedFavs = localStorage.getItem('global_favorites');
      if (savedFavs) setFavorites(JSON.parse(savedFavs));
      const savedReminders = localStorage.getItem('global_reminders');
      if (savedReminders) setReminders(JSON.parse(savedReminders));
      const savedHistory = localStorage.getItem('app_history');
      if (savedHistory) setHistory(JSON.parse(savedHistory));

      setIsAppReady(true);
    };
    init();
  }, []);

  useEffect(() => {
    const timer = setInterval(() => {
      try {
        const tz = (selectedCountry && selectedCountry.code !== 'GLOBAL') ? getTimezone(selectedCountry.code) : 'UTC';
        setLocalTime(new Intl.DateTimeFormat('zh-CN', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false, timeZone: tz }).format(new Date()));
        const nowStr = new Date().toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit', hour12: false });
        const trigger = reminders.find(r => r.timeStr === nowStr);
        if (trigger && !activeAlarm) setActiveAlarm(trigger);
      } catch (e) { setLocalTime('扫描中...'); }
    }, 1000);
    return () => clearInterval(timer);
  }, [selectedCountry, reminders, activeAlarm]);

  const loadContent = async (refresh = false) => {
    if (!selectedCountry) return;
    setLoadingChannels(true);
    try {
      let data: Channel[] = [];
      if (discoveryTag) {
        data = await fetchGlobalChannelsByCategory(discoveryTag);
      } else {
        data = mode === 'tv' ? await fetchChannelsByCountry(selectedCountry.code, refresh) : await fetchRadioStations(selectedCountry.code, refresh);
      }
      setChannels(data);
      if (data.length > 0 && (!currentChannel || refresh)) {
          setCurrentChannel(data.find(c => c.url) || data[0]);
      }
    } catch (err) { setChannels([]); }
    finally { setLoadingChannels(false); }
  };

  useEffect(() => { if (isAppReady) loadContent(); }, [selectedCountry, mode, isAppReady, discoveryTag]);

  const handleChannelSelect = (channel: Channel) => {
    setCurrentChannel(channel);
    const newHistory = [channel, ...history.filter(c => c.id !== channel.id)].slice(0, 15);
    setHistory(newHistory);
    localStorage.setItem('app_history', JSON.stringify(newHistory));
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleThemeChange = (theme: AppTheme) => {
    document.body.classList.add('glitch-transition');
    setCurrentTheme(theme);
    localStorage.setItem('app_theme_id', theme.id);
    setTimeout(() => document.body.classList.remove('glitch-transition'), 300);
  };

  const toggleFavorite = (channel: Channel) => {
    setFavorites(prev => {
      const isFav = prev.some(f => f.id === channel.id);
      const next = isFav ? prev.filter(f => f.id !== channel.id) : [...prev, channel];
      localStorage.setItem('global_favorites', JSON.stringify(next));
      return next;
    });
  };

  if (!isAppReady) return (
    <div className="h-screen w-full bg-[#000] flex flex-col items-center justify-center">
      <div className="relative">
        <div className="w-24 h-24 border-b-2 border-cyan-400 rounded-full animate-spin"></div>
        <div className="absolute inset-0 flex items-center justify-center">
            <Terminal className="w-8 h-8 text-cyan-400 animate-pulse" />
        </div>
      </div>
      <div className="mt-12 text-cyan-400 font-mono text-xs uppercase tracking-[1em] animate-pulse">{t.loading}</div>
    </div>
  );

  const { styles } = currentTheme;

  return (
    <div className={`flex h-screen w-full ${styles.bgMain} ${styles.font} overflow-hidden relative`}>
      {styles.bgPattern && <div className={`fixed inset-0 ${styles.bgPattern} pointer-events-none z-[1]`}></div>}

      <Sidebar 
        countries={countries} selectedCountry={discoveryTag ? GLOBAL_EXPLORE_COUNTRY : selectedCountry} 
        onSelectCountry={(c) => { setDiscoveryTag(null); setSelectedCountry(c); }}
        isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} mode={mode} onModeChange={setMode}
        themes={THEMES} currentTheme={currentTheme} onThemeChange={handleThemeChange}
        favorites={favorites} onSelectFavorite={handleChannelSelect} history={history}
        onImportM3U={() => {}} settings={settings} onToggleSound={() => setSettings(s => ({...s, enableSound: !s.enableSound}))} 
        onOpenSettings={() => setShowSettings(true)}
        reminders={reminders} onDeleteReminder={(id) => {
            const next = reminders.filter(r => r.id !== id);
            setReminders(next); localStorage.setItem('global_reminders', JSON.stringify(next));
        }} onPlayReminder={handleChannelSelect}
        lang={lang}
      />

      <main className="flex-1 flex flex-col h-full min-w-0 z-10 relative">
        <header className={`shrink-0 px-10 py-6 flex items-center justify-between border-b ${styles.border} ${styles.bgSidebar} backdrop-blur-3xl z-30 shadow-xl`}>
            <div className="flex items-center gap-6">
                <button onClick={() => setSidebarOpen(true)} className={`md:hidden p-4 rounded-xl ${styles.card} ${styles.textMain}`}><Menu /></button>
                <div className="flex items-center gap-5">
                    <span className="text-4xl filter drop-shadow-2xl">{discoveryTag ? '🛸' : selectedCountry?.flag}</span>
                    <div className="flex flex-col">
                        <h1 className={`text-3xl font-black uppercase italic tracking-tighter leading-none ${styles.textMain} ${currentTheme.id === 'cyber' || currentTheme.id === 'synth' ? 'text-glow' : ''}`}>
                            {discoveryTag ? `${discoveryTag}` : selectedCountry?.name}
                        </h1>
                        <span className={`text-[10px] font-black tracking-widest uppercase opacity-40 mt-1.5 ${styles.textDim}`}>
                            {channels.length} {t.nodesSynchronized}
                        </span>
                    </div>
                </div>
            </div>

            <div className="flex items-center gap-10">
                <button 
                  onClick={() => setLang(lang === 'zh' ? 'en' : 'zh')}
                  className={`flex items-center gap-2 px-5 py-2.5 rounded-full border ${styles.border} ${styles.button} transition-all active:scale-90 shadow-lg`}
                >
                  <Languages className="w-4 h-4" />
                  <span className="text-[10px] font-black uppercase tracking-widest">{lang === 'zh' ? 'EN' : '中文'}</span>
                </button>

                <div className="hidden lg:flex flex-col items-end">
                    <span className={`text-[9px] font-black uppercase tracking-widest ${styles.textDim}`}>{t.nodeTime}</span>
                    <span className={`text-lg font-mono font-black ${styles.textMain}`}>{localTime}</span>
                </div>
                <div className="flex items-center gap-3">
                    <button onClick={() => setShowSchedule(true)} className={`p-4 rounded-2xl ${styles.button} hover:scale-110 active:scale-95 transition-all relative shadow-lg`}>
                        <AlarmClock className="w-5 h-5" />
                        {reminders.length > 0 && <span className="absolute top-3 right-3 w-2.5 h-2.5 bg-rose-500 rounded-full border-2 border-black animate-pulse"></span>}
                    </button>
                    <button onClick={() => loadContent(true)} className={`p-4 rounded-2xl ${styles.button} hover:rotate-180 transition-all duration-1000 shadow-lg ${loadingChannels ? 'animate-spin' : ''}`}>
                        <RefreshCw className="w-5 h-5" />
                    </button>
                </div>
            </div>
        </header>

        <div className={`flex-1 overflow-y-auto ${currentTheme.type === 'web95' ? 'scrollbar-web95' : 'scrollbar-thin'}`}>
            <div className="px-10 py-10 max-w-[1600px] mx-auto">
                <div className="flex flex-col xl:flex-row gap-12">
                    <div className="flex-1 min-w-0 space-y-12">
                        <section className="space-y-10">
                            <VideoPlayer 
                              channel={currentChannel} country={discoveryTag ? GLOBAL_EXPLORE_COUNTRY : selectedCountry} theme={currentTheme}
                              isFavorite={!!currentChannel && favorites.some(f => f.id === currentChannel.id)}
                              onToggleFavorite={() => currentChannel && toggleFavorite(currentChannel)} 
                              onAutoSkip={() => {
                                  if (channels.length > 1) {
                                      const next = channels[Math.floor(Math.random()*channels.length)];
                                      handleChannelSelect(next);
                                  }
                              }}
                              lang={lang}
                            />
                            <FavoritesBar favorites={favorites} currentChannel={currentChannel} onSelectChannel={handleChannelSelect} theme={currentTheme} mode={mode} />
                        </section>

                        <section className="space-y-10">
                            <div className="flex flex-col space-y-8">
                                <h2 className={`text-3xl font-black uppercase italic tracking-tighter ${styles.textMain} flex items-center gap-4`}>
                                    <Sparkles className={styles.accentColor} /> {t.discoveryTerminal}
                                </h2>
                                <div className="flex flex-wrap gap-3">
                                    {HOT_TAGS.map(tag => (
                                        <button 
                                            key={tag} onClick={() => { setDiscoveryTag(tag); setChannelFilter(''); }} 
                                            className={`px-6 py-3 ${styles.layoutShape} text-xs font-black border transition-all duration-300 transform active:scale-90 ${discoveryTag === tag ? styles.buttonActive : `${styles.button} opacity-40 hover:opacity-100`}`}
                                        >
                                            # {tag}
                                        </button>
                                    ))}
                                    {(discoveryTag || channelFilter) && (
                                        <button onClick={() => { setDiscoveryTag(null); setChannelFilter(''); }} className="px-6 py-3 rounded-full text-xs font-black bg-rose-500 text-white shadow-lg hover:bg-rose-600">{t.reset}</button>
                                    )}
                                </div>
                            </div>
                            <ChannelGrid 
                                channels={channels} currentChannel={currentChannel} onSelectChannel={handleChannelSelect} 
                                loading={loadingChannels} mode={mode} theme={currentTheme} favorites={favorites} 
                                onToggleFavorite={toggleFavorite} externalFilter={channelFilter} onExternalFilterChange={setChannelFilter}
                            />
                        </section>
                    </div>

                    <div className="xl:w-[380px] shrink-0 space-y-10">
                        <div className="xl:sticky xl:top-10 space-y-10">
                            <div className={`${styles.card} p-8 ${styles.layoutShape} border ${styles.border} group overflow-hidden relative shadow-2xl transition-all`}>
                                <div className={`absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-${currentTheme.id === 'synth' ? '[#ff00ff]' : 'cyan-500'}/30 to-transparent`}></div>
                                <h3 className="text-[11px] font-black uppercase tracking-[0.4em] mb-8 opacity-40 flex items-center gap-3"><History className={`w-5 h-5 ${styles.accentColor}`} /> {t.activityLog}</h3>
                                <div className="space-y-4 max-h-[320px] overflow-y-auto scrollbar-thin">
                                    {history.length > 0 ? history.map(h => (
                                        <div key={h.id} onClick={() => handleChannelSelect(h)} className={`flex items-center gap-5 p-4 rounded-3xl hover:bg-white/5 cursor-pointer group/item transition-all active:scale-95 border border-transparent hover:border-white/5`}>
                                            <div className="w-12 h-12 rounded-2xl bg-black/40 flex items-center justify-center shrink-0 overflow-hidden shadow-inner group-hover/item:rotate-6 transition-transform">
                                                {h.logo ? <img src={h.logo} className="w-full h-full object-contain p-2" /> : <History className="w-5 h-5 opacity-20" />}
                                            </div>
                                            <div className="flex flex-col min-w-0">
                                                <span className={`text-xs font-black uppercase truncate italic tracking-tighter ${styles.textMain}`}>{h.name}</span>
                                                <span className={`text-[9px] font-bold opacity-30 uppercase tracking-widest`}>{h.group || '频道'}</span>
                                            </div>
                                        </div>
                                    )) : (
                                        <div className="py-12 text-center text-[10px] font-black opacity-10 uppercase italic">{t.logsEmpty}</div>
                                    )}
                                </div>
                            </div>

                            <AiChatPet theme={currentTheme} currentChannels={channels} onSelectChannel={handleChannelSelect} lang={lang} />

                            <button onClick={() => { if(channels.length > 0) handleChannelSelect(channels[Math.floor(Math.random()*channels.length)]) }} className={`w-full py-6 ${styles.buttonPrimary} ${styles.layoutShape} font-black uppercase text-xs flex items-center justify-center gap-4 shadow-2xl hover:translate-y-[-4px] active:translate-y-[2px] transition-all transform`}><Shuffle /> {t.neuralRandomize}</button>
                        </div>
                    </div>
                </div>
            </div>
        </div>
      </main>

      <ScheduleList 
        reminders={reminders} isOpen={showSchedule} onClose={() => setShowSchedule(false)} 
        onDelete={(id) => { const next = reminders.filter(r => r.id !== id); setReminders(next); localStorage.setItem('global_reminders', JSON.stringify(next)); }}
        theme={currentTheme} onPlayChannel={(id) => { const ch = channels.find(c => c.id === id); if(ch) handleChannelSelect(ch); }}
        allChannels={channels}
      />
      <AlarmModal reminder={activeAlarm} onClose={() => setActiveAlarm(null)} onWatch={(id) => { const ch = channels.find(c => c.id === id); if(ch) handleChannelSelect(ch); setActiveAlarm(null); }} theme={currentTheme} />

      <SettingsModal 
        isOpen={showSettings} onClose={() => setShowSettings(false)}
        settings={settings} onToggleSound={() => setSettings(s => ({...s, enableSound: !s.enableSound}))}
        lang={lang} onToggleLang={() => setLang(l => l === 'zh' ? 'en' : 'zh')}
        theme={currentTheme}
        onClearHistory={() => { setHistory([]); localStorage.removeItem('app_history'); }}
        onClearFavorites={() => { setFavorites([]); localStorage.removeItem('global_favorites'); }}
      />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useRef } from 'react';
import { Country, AppTheme, Channel, AppSettings, Reminder, Language } from '../types';
import { Search, Globe, X, Tv, Radio, Palette, Star, Upload, Settings, Check, Volume2, VolumeX } from 'lucide-react';

interface SidebarProps {
  countries: Country[];
  selectedCountry: Country | null;
  onSelectCountry: (country: Country) => void;
  isOpen: boolean;
  onClose: () => void;
  mode: 'tv' | 'radio';
  onModeChange: (mode: 'tv' | 'radio') => void;
  themes: AppTheme[];
  currentTheme: AppTheme;
  onThemeChange: (theme: AppTheme) => void;
  favorites: Channel[];
  onSelectFavorite: (channel: Channel) => void;
  onImportM3U: (content: string) => void;
  settings: AppSettings;
  onToggleSound: () => void;
  onOpenSettings: () => void;
  reminders: Reminder[];
  onDeleteReminder: (id: string) => void;
  onPlayReminder: (channelId: string) => void;
  history: Channel[];
  lang: Language;
}

const TRANSLATIONS = {
  zh: {
    global: '全球频道',
    satellite: '实时电视',
    radio: '广播电台',
    saved: '收藏',
    logs: '历史',
    alert: '提醒',
    emptyLink: '暂无收藏频道',
    scanPlaceholder: '搜索国家或地区...',
    network: '地区节点',
    visuals: '更换主题',
    import: '导入连接',
    uplinkActive: '服务在线'
  },
  en: {
    global: 'Global Link',
    satellite: 'Satellite TV',
    radio: 'Radio',
    saved: 'Saved',
    logs: 'History',
    alert: 'Alerts',
    emptyLink: 'Empty',
    scanPlaceholder: 'Search regions...',
    network: 'Region Node',
    visuals: 'Themes',
    import: 'Import Link',
    uplinkActive: 'Online'
  }
};

export const Sidebar: React.FC<SidebarProps> = ({ 
    countries, selectedCountry, onSelectCountry, isOpen, onClose, mode, onModeChange, themes,
    currentTheme, onThemeChange, favorites, onSelectFavorite, onImportM3U, settings,
    onToggleSound, onOpenSettings, reminders, onDeleteReminder, onPlayReminder, history, lang
}) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [showThemes, setShowThemes] = useState(false);
  const [activeTab, setActiveTab] = useState<'favorites' | 'history' | null>('favorites');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const t = TRANSLATIONS[lang];
  const { styles } = currentTheme;

  const filteredCountries = useMemo(() => {
    if (!searchQuery) return countries;
    const lowerQ = searchQuery.toLowerCase();
    return countries.filter(c => c.name.toLowerCase().includes(lowerQ) || c.code.toLowerCase().includes(lowerQ));
  }, [countries, searchQuery]);

  const modeFavorites = useMemo(() => favorites.filter(c => (c.type || 'tv') === mode), [favorites, mode]);

  return (
    <>
        {isOpen && <div className="fixed inset-0 bg-black/90 z-40 md:hidden backdrop-blur-2xl transition-all" onClick={onClose} />}

        <aside className={`
            fixed md:relative z-50 h-full ${styles.bgSidebar} w-80 flex flex-col min-w-0
            transition-all duration-700 cubic-bezier(0.16, 1, 0.3, 1)
            ${isOpen ? 'translate-x-0' : '-translate-x-full md:translate-x-0'}
            shadow-[0_0_80px_rgba(0,0,0,0.8)]
        `}>

        <div className={`p-8 border-b ${styles.border} flex items-center justify-between shrink-0`}>
            <div className={`flex items-center gap-4 ${styles.textMain}`}>
                <div className="p-3 bg-white text-black rounded-2xl shadow-2xl transition-transform hover:scale-110">
                    <Globe className="w-6 h-6" />
                </div>
                <div>
                    <h1 className="text-2xl font-black tracking-tighter uppercase italic leading-none">{t.global}</h1>
                    <div className="flex items-center gap-2 mt-1">
                        <span className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></span>
                        <span className="text-[8px] font-black tracking-[0.3em] uppercase opacity-30">{t.uplinkActive}</span>
                    </div>
                </div>
            </div>
            <button onClick={onClose} className={`md:hidden ${styles.textDim} p-2 hover:bg-white/5 rounded-full transition-all`}>
                <X className="w-6 h-6" />
            </button>
        </div>

        <div className="p-6 space-y-6 shrink-0">
            <div className={`flex p-1 ${styles.layoutShape} bg-black/40 border ${styles.border} shadow-inner`}>
                {(['tv', 'radio'] as const).map(m => (
                    <button 
                        key={m} onClick={() => onModeChange(m)}
                        className={`flex-1 flex items-center justify-center gap-2 py-3 ${styles.layoutShape} text-[10px] font-black transition-all duration-300 uppercase tracking-widest ${mode === m ? `${styles.buttonActive} shadow-lg` : `${styles.textDim} hover:bg-white/5`}`}
                    >
                        {m === 'tv' ? <Tv className="w-4 h-4" /> : <Radio className="w-4 h-4" />}
                        {m === 'tv' ? t.satellite : t.radio}
                    </button>
                ))}
            </div>

            <div className="flex gap-2">
                {(['favorites', 'history'] as const).map((tab) => (
                    <button 
                        key={tab} onClick={() => setActiveTab(activeTab === tab ? null : tab)}
                        className={`
                            flex-1 flex flex-col items-center justify-center py-3 ${styles.layoutShape} transition-all border
                            ${activeTab === tab ? styles.buttonActive : `${styles.card} border-transparent opacity-40 hover:opacity-100`}
                        `}
                    >
                        <span className="text-[9px] font-black uppercase tracking-widest">
                            {tab === 'favorites' ? t.saved : t.logs}
                        </span>
                    </button>
                ))}
            </div>

            {activeTab && (
                <div className={`p-4 ${styles.card} ${styles.layoutShape} border ${styles.border} space-y-2 max-h-48 overflow-y-auto animate-in slide-in-from-top-4 duration-500`}>
                    {activeTab === 'favorites' ? (
                        modeFavorites.length > 0 ? modeFavorites.map(ch => (
                            <button key={ch.id} onClick={() => { onSelectFavorite(ch); if (window.innerWidth < 768) onClose(); }} className={`w-full flex items-center gap-4 p-3 ${styles.layoutShape} hover:bg-white/10 text-left transition-all border border-transparent`}>
                                <div className="w-8 h-8 rounded-lg bg-black/60 shrink-0 flex items-center justify-center overflow-hidden border border-white/10">
                                    {ch.logo ? <img src={ch.logo} className="w-full h-full object-contain p-1" /> : <Star className="w-4 h-4 opacity-20" />}
                                </div>
                                <span className={`text-[10px] font-black truncate uppercase tracking-tight italic ${styles.textMain}`}>{ch.name}</span>
                            </button>
                        )) : <div className="py-8 text-center text-[9px] font-black opacity-20 uppercase">{t.emptyLink}</div>
                    ) : (
                        history.length > 0 ? history.map(ch => (
                            <button key={ch.id} onClick={() => { onSelectFavorite(ch); if (window.innerWidth < 768) onClose(); }} className={`w-full flex items-center gap-4 p-3 ${styles.layoutShape} hover:bg-white/10 text-left transition-all border border-transparent`}>
                                <div className="w-8 h-8 rounded-lg bg-black/60 shrink-0 flex items-center justify-center overflow-hidden border border-white/10">
                                    {ch.logo ? <img src={ch.logo} className="w-full h-full object-contain p-1" /> : <Star className="w-4 h-4 opacity-20" />}
                                </div>
                                <span className={`text-[10px] font-black truncate uppercase tracking-tight italic ${styles.textMain}`}>{ch.name}</span>
                            </button>
                        )) : <div className="py-8 text-center text-[9px] font-black opacity-20 uppercase">暂无历史记录</div>
                    )}
                </div>
            )}
        </div>

        <div className={`flex-1 overflow-y-auto px-6 space-y-2 ${currentTheme.type === 'web95' ? 'scrollbar-web95' : 'scrollbar-thin'}`}>
            <div className={`sticky top-0 z-20 pt-2 pb-4 ${styles.bgSidebar}`}>
                <div className={`relative ${styles.input} ${styles.layoutShape} border ${styles.border} flex items-center px-4 py-3 shadow-xl`}>
                    <Search className={`w-4 h-4 ${styles.textDim}`} />
                    <input 
                        type="text" placeholder={t.scanPlaceholder}
                        className="bg-transparent border-none focus:outline-none text-[10px] w-full ml-3 font-black uppercase tracking-widest placeholder:opacity-20"
                        value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)}
                    />
                </div>
            </div>

            <div className="space-y-1.5 pb-12">
                {filteredCountries.map(country => (
                    <button
                        key={country.code} onClick={() => { onSelectCountry(country); if (window.innerWidth < 768) onClose(); }}
                        className={`
                            w-full flex items-center gap-4 p-4 ${styles.layoutShape} transition-all group relative
                            ${selectedCountry?.code === country.code 
                                ? `${styles.buttonActive} shadow-xl scale-[1.02] border-none` 
                                : `${styles.textDim} hover:bg-white/5 border border-transparent`
                            }
                        `}
                    >
                        <span className="text-2xl shrink-0 group-hover:scale-125 transition-transform">{country.flag}</span>
                        <div className="flex flex-col min-w-0">
                            <span className={`text-[11px] font-black truncate uppercase tracking-tighter italic ${selectedCountry?.code === country.code ? 'text-black' : styles.textMain}`}>{country.name}</span>
                            <span className={`text-[8px] font-black uppercase tracking-[0.1em] opacity-30 ${selectedCountry?.code === country.code ? 'text-black' : ''}`}>{country.code} {t.network}</span>
                        </div>
                    </button>
                ))}
            </div>
        </div>

        <div className={`p-6 border-t ${styles.border} bg-black/40 space-y-4 relative`}>
            {showThemes && (
                 <div className="absolute bottom-[calc(100%+16px)] left-6 right-6 z-[100] p-4 bg-[#0a0a10] border-2 border-white/10 rounded-3xl shadow-[0_40px_100px_rgba(0,0,0,0.9)] animate-in slide-in-from-bottom-4 duration-500">
                    <div className="grid grid-cols-1 gap-2">
                        {themes.map(t => (
                            <button 
                                key={t.id} onClick={() => { onThemeChange(t); setShowThemes(false); }} 
                                className={`
                                    w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all flex items-center justify-between
                                    ${currentTheme.id === t.id ? 'bg-white text-black' : 'bg-white/5 text-white/40 hover:bg-white/10 hover:text-white'}
                                `}
                            >
                                <div className="flex items-center gap-3">
                                    <div className={`w-2 h-2 rounded-full ${
                                        t.id === 'cyber' ? 'bg-cyan-400' : 
                                        t.id === 'candy' ? 'bg-rose-400' : 
                                        t.id === 'acid' ? 'bg-[#ccff00]' : 
                                        t.id === 'synth' ? 'bg-[#ff00ff]' :
                                        t.id === 'swiss' ? 'bg-red-600' : 'bg-gray-400'
                                    }`}></div>
                                    {t.name[lang]}
                                </div>
                                {currentTheme.id === t.id && <Check className="w-4 h-4" />}
                            </button>
                        ))}
                    </div>
                 </div>
            )}

            <button onClick={() => fileInputRef.current?.click()} className={`w-full flex items-center justify-center gap-3 py-4 ${styles.layoutShape} border ${styles.border} ${styles.button} text-[10px] font-black uppercase tracking-widest transition-all hover:bg-white/5 active:scale-95`}>
                <Upload className="w-4 h-4" /> {t.import}
            </button>
            <input type="file" accept=".m3u,.m3u8" ref={fileInputRef} className="hidden" onChange={(e) => {
                const f = e.target.files?.[0];
                if (f) {
                    const r = new FileReader();
                    r.onload = (ev) => { if (ev.target?.result) onImportM3U(ev.target.result as string); };
                    r.readAsText(f);
                }
            }} />

            <div className="flex gap-2">
                <button onClick={() => setShowThemes(!showThemes)} className={`flex-1 flex items-center justify-center gap-2 py-4 text-[10px] font-black uppercase ${styles.button} ${styles.border} ${styles.layoutShape} shadow-2xl ${showThemes ? 'bg-white text-black border-white' : ''}`}>
                    <Palette className="w-4 h-4" /> {t.visuals}
                </button>
                <button onClick={onOpenSettings} className={`p-4 ${styles.button} ${styles.border} ${styles.layoutShape} hover:bg-white/10 transition-all`}>
                    <Settings className="w-4 h-4" />
                </button>
            </div>
        </div>
      </aside>
    </>
  );
};

import React, { useEffect, useRef, useState, useCallback } from 'react';
import Hls from 'hls.js';
import { Play, RefreshCw, Square, Star, Volume2, VolumeX, Maximize, Clock, Zap, Circle, AlertTriangle, Shuffle, WifiOff, Globe, ShieldAlert, Camera, Terminal } from 'lucide-react';
import { AppTheme, Channel, Country, Language } from '../types';

interface VideoPlayerProps {
  channel: Channel | null;
  country: Country | null; 
  theme: AppTheme;
  isFavorite: boolean;
  onToggleFavorite: () => void;
  onAutoSkip?: () => void;
  lang: Language;
}

const TRANSLATIONS = {
  zh: {
    uplinkFailed: '连接失败',
    uplinkFailedDesc: '无法连接到目标服务器，请检查网络或更换频道。',
    signalTimeout: '信号超时',
    signalTimeoutDesc: '响应时间过长，网络拥堵或源地址已失效。',
    frequencyLost: '无法获取信号',
    frequencyLostDesc: '当前频道信号已中断或连接已关闭。',
    forceRelink: '重试连接',
    jumpNode: '换个频道',
    recording: '正在录制',
    syncing: '正在同步画面...',
    live: '直播',
    searching: '搜索中...',
    global: '全球',
    public: '公共'
  },
  en: {
    uplinkFailed: 'Connection Failed',
    uplinkFailedDesc: 'Could not establish connection to the host server.',
    signalTimeout: 'Signal Timeout',
    signalTimeoutDesc: 'Station is taking too long to respond. Network congestion.',
    frequencyLost: 'Frequency Lost',
    frequencyLostDesc: 'The carrier wave for this node has been disconnected.',
    forceRelink: 'Retry',
    jumpNode: 'Next Channel',
    recording: 'Recording',
    syncing: 'Syncing Stream...',
    live: 'Live',
    searching: 'Searching...',
    global: 'Global',
    public: 'Public'
  }
};

export const VideoPlayer: React.FC<VideoPlayerProps> = ({ 
    channel, country, theme, isFavorite, onToggleFavorite, onAutoSkip, lang
}) => {
  const [activePlayerIndex, setActivePlayerIndex] = useState(0);
  const videoRefs = [useRef<HTMLVideoElement>(null), useRef<HTMLVideoElement>(null)];
  const hlsRefs = useRef<(Hls | null)[]>([null, null]);

  const [loading, setLoading] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const [volume, setVolume] = useState(1);
  const [errorState, setErrorState] = useState<'none' | 'timeout' | 'fatal' | 'network'>('none');
  const retryCountRef = useRef(0);
  const MAX_RETRIES = 5; 

  const [isRecording, setIsRecording] = useState(false);
  const [recordingDuration, setRecordingDuration] = useState(0);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);
  const recordingTimerRef = useRef<number | null>(null);
  const loadTimeoutRef = useRef<number | null>(null);

  const t = TRANSLATIONS[lang];

  const killAllPlayers = useCallback(() => {
    videoRefs.forEach(ref => {
      if (ref.current) {
        ref.current.pause();
        ref.current.removeAttribute('src');
        ref.current.load();
      }
    });
    hlsRefs.current.forEach((hls, idx) => {
      if (hls) {
        hls.destroy();
        hlsRefs.current[idx] = null;
      }
    });
  }, []);

  const resetState = () => {
    setErrorState('none');
    setLoading(true);
    retryCountRef.current = 0;
    if (loadTimeoutRef.current) clearTimeout(loadTimeoutRef.current);
  };

  useEffect(() => {
    videoRefs.forEach(ref => {
      if (ref.current) ref.current.volume = volume;
    });
  }, [volume]);

  useEffect(() => {
    const url = channel?.url;
    if (!url) return;
    if (isRecording) stopRecording();
    killAllPlayers();
    resetState();

    const nextIndex = (activePlayerIndex + 1) % 2;
    const nextVideo = videoRefs[nextIndex].current;
    if (!nextVideo) return;

    loadTimeoutRef.current = window.setTimeout(() => {
        if (loading || !isPlaying) {
            setErrorState('timeout');
            setLoading(false);
        }
    }, 20000);

    if (url.includes('.m3u8') && Hls.isSupported()) {
      const hls = new Hls({
        maxBufferLength: 30,
        enableWorker: true,
        xhrSetup: (xhr) => { xhr.withCredentials = false; }
      });
      hlsRefs.current[nextIndex] = hls;
      hls.loadSource(url);
      hls.attachMedia(nextVideo);
      hls.on(Hls.Events.MANIFEST_PARSED, () => {
        if (loadTimeoutRef.current) clearTimeout(loadTimeoutRef.current);
        videoRefs.forEach((ref, idx) => { if (idx !== nextIndex && ref.current) ref.current.pause(); });
        nextVideo.play().catch(() => { setIsPlaying(false); });
        setLoading(false);
        setIsPlaying(true);
        setErrorState('none');
        setActivePlayerIndex(nextIndex);
        retryCountRef.current = 0;
      });
      hls.on(Hls.Events.ERROR, (event, data) => {
        if (data.fatal) {
            if (retryCountRef.current < MAX_RETRIES) {
                retryCountRef.current++;
                setTimeout(() => {
                  if (!hlsRefs.current[nextIndex]) return;
                  if (data.type === Hls.ErrorTypes.NETWORK_ERROR) hls.startLoad();
                  else hls.recoverMediaError();
                }, Math.pow(2, retryCountRef.current) * 500);
            } else {
                setErrorState(data.type === Hls.ErrorTypes.NETWORK_ERROR ? 'network' : 'fatal');
                setLoading(false);
                if (loadTimeoutRef.current) clearTimeout(loadTimeoutRef.current);
            }
        }
      });
    } else {
      nextVideo.src = url;
      nextVideo.oncanplay = () => {
        if (loadTimeoutRef.current) clearTimeout(loadTimeoutRef.current);
        nextVideo.play().catch(() => { setIsPlaying(false); });
        setLoading(false);
        setIsPlaying(true);
        setErrorState('none');
        setActivePlayerIndex(nextIndex);
      };
      nextVideo.onerror = () => { setErrorState('network'); setLoading(false); };
    }
    return () => { if (loadTimeoutRef.current) clearTimeout(loadTimeoutRef.current); };
  }, [channel?.url]);

  useEffect(() => { return () => killAllPlayers(); }, [killAllPlayers]);

  const takeScreenshot = () => {
    const video = videoRefs[activePlayerIndex].current;
    if (!video || errorState !== 'none' || loading) return;
    const canvas = document.createElement('canvas');
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
    const link = document.createElement('a');
    link.href = canvas.toDataURL('image/png');
    link.download = `Live_Snap_${channel?.name}_${Date.now()}.png`;
    link.click();
  };

  const startRecording = () => {
    const video = videoRefs[activePlayerIndex].current;
    if (!video) return;
    const stream = (video as any).captureStream ? (video as any).captureStream() : null;
    if (!stream) return;
    const recorder = new MediaRecorder(stream, { mimeType: 'video/webm' });
    mediaRecorderRef.current = recorder;
    chunksRef.current = [];
    recorder.ondataavailable = (e) => chunksRef.current.push(e.data);
    recorder.onstop = () => {
        const url = URL.createObjectURL(new Blob(chunksRef.current, { type: 'video/webm' }));
        const a = document.createElement('a'); a.href = url; a.download = `Record_${channel?.name}.webm`; a.click();
    };
    recorder.start();
    setIsRecording(true);
    setRecordingDuration(0);
    recordingTimerRef.current = window.setInterval(() => setRecordingDuration(p => p + 1), 1000);
  };

  const stopRecording = () => {
    mediaRecorderRef.current?.stop();
    setIsRecording(false);
    if (recordingTimerRef.current) clearInterval(recordingTimerRef.current);
  };

  const { styles } = theme;
  const getErrorDisplay = () => {
      if (errorState === 'network') return { icon: <WifiOff className="w-12 h-12 text-amber-500" />, title: t.uplinkFailed, desc: t.uplinkFailedDesc };
      if (errorState === 'timeout') return { icon: <Clock className="w-12 h-12 text-cyan-500 animate-pulse" />, title: t.signalTimeout, desc: t.signalTimeoutDesc };
      return { icon: <AlertTriangle className="w-12 h-12 text-rose-500" />, title: t.frequencyLost, desc: t.frequencyLostDesc };
  };

  const display = getErrorDisplay();

  return (
    <div className="relative w-full group">
      <div className={`relative w-full aspect-video bg-black ${styles.layoutShape} overflow-hidden border ${styles.border} shadow-[0_40px_120px_rgba(0,0,0,0.9)]`}>

        <div className="absolute inset-0 bg-gradient-to-tr from-cyan-500/10 via-transparent to-purple-500/10 opacity-50"></div>

        {errorState !== 'none' && (
            <div className="absolute inset-0 z-40 flex flex-col items-center justify-center text-center p-12 bg-black/95 backdrop-blur-[40px]">
                <div className="relative z-10 flex flex-col items-center space-y-8 animate-in fade-in zoom-in slide-in-from-bottom-8 duration-1000">
                    <div className="w-28 h-28 rounded-full bg-white/5 flex items-center justify-center border border-white/10 shadow-[0_0_80px_rgba(255,255,255,0.05)] relative group">
                        {display.icon}
                        <div className="absolute -inset-6 rounded-full border border-white/5 animate-ping opacity-10"></div>
                    </div>
                    <div>
                        <h3 className="text-white font-black text-4xl uppercase italic tracking-tighter mb-4">{display.title}</h3>
                        <p className="text-white/40 text-[11px] max-w-xs mx-auto leading-relaxed font-bold uppercase tracking-widest">{display.desc}</p>
                    </div>
                    <div className="flex flex-col sm:flex-row gap-4 pt-4">
                        <button onClick={() => window.location.reload()} className="px-12 py-4 bg-white text-black text-[11px] font-black uppercase rounded-full hover:bg-cyan-400 transition-all active:scale-90 flex items-center gap-3">
                            <RefreshCw className="w-4 h-4" /> {t.forceRelink}
                        </button>
                        <button onClick={onAutoSkip} className="px-12 py-4 bg-white/5 text-white text-[11px] font-black uppercase rounded-full border border-white/10 hover:bg-white/10 transition-all active:scale-90 flex items-center gap-3">
                            <Shuffle className="w-4 h-4" /> {t.jumpNode}
                        </button>
                    </div>
                </div>
            </div>
        )}

        {[0, 1].map((index) => (
            <video
                key={index} ref={videoRefs[index]} playsInline muted={isMuted}
                className={`absolute inset-0 w-full h-full object-contain transition-opacity duration-1000 ${activePlayerIndex === index && errorState === 'none' ? 'opacity-100' : 'opacity-0'}`}
            />
        ))}

        <div className="absolute inset-0 pointer-events-none opacity-[0.03] bg-[linear-gradient(rgba(18,16,16,0)_50%,rgba(0,0,0,0.25)_50%),linear-gradient(90deg,rgba(255,0,0,0.06),rgba(0,255,0,0.02),rgba(0,0,255,0.06))] bg-[length:100%_4px,3px_100%]"></div>

        {isRecording && (
          <div className="absolute top-8 left-8 z-40 flex items-center gap-4 bg-black/60 backdrop-blur-2xl px-5 py-2.5 rounded-full border border-red-500/40 shadow-2xl">
             <div className="w-3 h-3 bg-red-600 rounded-full animate-pulse shadow-[0_0_15px_#dc2626]"></div>
             <span className="text-white text-[11px] font-black tracking-widest uppercase italic">{t.recording}</span>
             <span className="text-red-400 font-mono text-xs font-black border-l border-white/10 pl-4">
                 {Math.floor(recordingDuration/60).toString().padStart(2,'0')}:{(recordingDuration%60).toString().padStart(2,'0')}
             </span>
          </div>
        )}

        {loading && errorState === 'none' && (
             <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/80 backdrop-blur-xl z-20 space-y-6">
                <div className="relative w-20 h-20">
                    <div className="absolute inset-0 border-[6px] border-cyan-500/10 rounded-full"></div>
                    <div className="absolute inset-0 border-[6px] border-t-cyan-500 rounded-full animate-spin"></div>
                    <Terminal className="absolute inset-0 m-auto w-6 h-6 text-cyan-500 animate-pulse" />
                </div>
                <div className="text-[11px] text-cyan-500 font-mono font-black uppercase tracking-[0.5em] animate-pulse">{t.syncing}</div>
             </div>
        )}

        {/* Console UI */}
        <div className={`absolute inset-x-8 bottom-8 p-6 bg-black/60 backdrop-blur-[50px] rounded-[32px] border border-white/10 transition-all duration-700 shadow-2xl ${errorState !== 'none' ? 'opacity-0 translate-y-8' : 'opacity-0 translate-y-4 group-hover:opacity-100 group-hover:translate-y-0'}`}>
            <div className="flex flex-col md:flex-row items-center justify-between gap-6">
                <div className="flex items-center gap-6 min-w-0">
                    <button onClick={() => {
                        const v = videoRefs[activePlayerIndex].current;
                        if (isPlaying) v?.pause(); else v?.play();
                        setIsPlaying(!isPlaying);
                    }} className="w-16 h-16 bg-white text-black rounded-full flex items-center justify-center transition-all hover:scale-110 hover:bg-cyan-400 active:scale-95 shadow-[0_15px_40px_rgba(255,255,255,0.2)]">
                        {isPlaying ? <Square className="w-6 h-6 fill-current" /> : <Play className="w-6 h-6 fill-current ml-1" />}
                    </button>
                    <div className="min-w-0">
                        <div className="flex items-center gap-3 mb-1">
                            <span className="px-2 py-0.5 bg-gradient-to-r from-red-600 to-rose-500 text-[9px] font-black text-white rounded shadow-lg uppercase tracking-widest animate-pulse">{t.live}</span>
                            <h4 className="text-white font-black text-xl tracking-tighter truncate max-w-md uppercase italic leading-none">
                                {channel?.name || t.searching}
                            </h4>
                        </div>
                        <div className="flex items-center gap-3 text-white/30 text-[10px] font-black uppercase tracking-widest mt-2">
                            <div className="flex items-center gap-1.5"><Zap className="w-3.5 h-3.5 text-cyan-400" /> {channel?.group || t.public}</div>
                            <div className="w-1 h-1 rounded-full bg-white/20"></div>
                            <div className="flex items-center gap-1.5"><Globe className="w-3.5 h-3.5" /> {country?.name || t.global}</div>
                        </div>
                    </div>
                </div>

                <div className="flex items-center gap-2">
                    <button 
                        onClick={onToggleFavorite} 
                        className={`p-4 rounded-[20px] transition-all active:scale-90 shadow-xl ${isFavorite ? 'bg-amber-400 text-black shadow-amber-500/30' : 'bg-white/5 text-white hover:bg-white/10 border border-white/5'}`}
                        title="收藏"
                    >
                        <Star className={`w-5 h-5 ${isFavorite ? 'fill-current' : ''}`} />
                    </button>

                    <button onClick={takeScreenshot} title="截屏" className="p-4 bg-white/5 text-white hover:bg-white/10 border border-white/5 rounded-[20px] transition-all active:scale-90 shadow-xl">
                        <Camera className="w-5 h-5" />
                    </button>

                    <button onClick={isRecording ? stopRecording : startRecording} title="录制" className={`p-4 rounded-[20px] transition-all shadow-xl ${isRecording ? 'bg-red-600 text-white animate-pulse' : 'bg-white/5 text-white hover:bg-white/10 border border-white/5'}`}>
                        <Circle className={`w-5 h-5 ${isRecording ? 'fill-current' : ''}`} />
                    </button>

                    <div className="h-10 w-[1px] bg-white/10 mx-2"></div>

                    <div className="flex items-center group/vol">
                      <button onClick={() => setIsMuted(!isMuted)} className="p-4 bg-white/5 border border-white/5 hover:bg-white/10 rounded-[20px] text-white transition-all shadow-xl">
                          {isMuted || volume === 0 ? <VolumeX className="w-5 h-5 text-rose-500" /> : <Volume2 className="w-5 h-5" />}
                      </button>
                      <div className="w-0 overflow-hidden group-hover/vol:w-32 group-hover/vol:ml-4 transition-all duration-500 flex items-center">
                          <input type="range" min="0" max="1" step="0.01" value={isMuted ? 0 : volume} onChange={(e) => { const v = parseFloat(e.target.value); setVolume(v); if (v > 0) setIsMuted(false); }} className="w-28 h-1.5 accent-cyan-500 bg-white/10 rounded-full appearance-none cursor-pointer" />
                      </div>
                    </div>

                    <button onClick={() => videoRefs[activePlayerIndex].current?.requestFullscreen()} title="全屏" className="p-4 bg-white/5 border border-white/5 hover:bg-white/10 rounded-[20px] text-white transition-all shadow-xl">
                        <Maximize className="w-5 h-5" />
                    </button>
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Channel, AppTheme } from '../types';
import { Tv, Search, Radio, Star, Play, Activity, Globe2, X, Command } from 'lucide-react';

interface ChannelGridProps {
  channels: Channel[];
  currentChannel: Channel | null;
  onSelectChannel: (channel: Channel) => void;
  loading: boolean;
  mode: 'tv' | 'radio';
  theme: AppTheme;
  favorites: Channel[];
  onToggleFavorite: (channel: Channel) => void;
  externalFilter?: string;
  onExternalFilterChange?: (filter: string) => void;
}

export const ChannelGrid: React.FC<ChannelGridProps> = ({ 
    channels, currentChannel, onSelectChannel, loading, mode, theme, favorites, onToggleFavorite,
    externalFilter = '', onExternalFilterChange
}) => {
  const [internalFilter, setInternalFilter] = useState('');
  const { styles } = theme;

  useEffect(() => { if (externalFilter) setInternalFilter(''); }, [externalFilter]);

  const filteredChannels = useMemo(() => {
    const activeFilter = (externalFilter || internalFilter).toLowerCase();
    if (!activeFilter) return channels;
    return channels.filter(c => c.name.toLowerCase().includes(activeFilter) || (c.group && c.group.toLowerCase().includes(activeFilter)));
  }, [channels, externalFilter, internalFilter]);

  if (loading) {
    return (
      <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 gap-4">
        {Array.from({ length: 18 }).map((_, i) => (
            <div key={i} className={`h-32 bg-white/5 ${styles.layoutShape} animate-pulse relative overflow-hidden`}>
                <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/[0.05] to-transparent animate-shimmer"></div>
            </div>
        ))}
      </div>
    );
  }

  return (
    <div className="space-y-8">
      <div className={`flex items-center gap-4 p-4 ${styles.input} ${styles.layoutShape} border ${styles.border} shadow-2xl group transition-all`}>
        <Search className={`w-5 h-5 ${styles.textDim} group-focus-within:text-cyan-400 transition-colors`} />
        <input 
            type="text"
            placeholder={externalFilter ? `标签搜索: ${externalFilter}` : "搜索频道名称、类型或关键词..."}
            className="bg-transparent border-none focus:outline-none text-[13px] font-bold w-full placeholder:opacity-30 uppercase tracking-widest"
            value={internalFilter}
            onChange={(e) => {
                setInternalFilter(e.target.value);
                if (onExternalFilterChange) onExternalFilterChange('');
            }}
        />
        <div className="hidden md:flex items-center gap-1 opacity-20 group-focus-within:opacity-0 transition-opacity">
            <Command className="w-3 h-3" /> <span className="text-[9px] font-black">S</span>
        </div>
        {(internalFilter || externalFilter) && (
            <button onClick={() => { setInternalFilter(''); if (onExternalFilterChange) onExternalFilterChange(''); }} className="p-2 hover:bg-rose-500/20 text-rose-500 rounded-full transition-colors">
                <X className="w-4 h-4" />
            </button>
        )}
      </div>

      <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 gap-4">
          {filteredChannels.length > 0 ? filteredChannels.map(channel => {
              const isActive = currentChannel?.id === channel.id;
              const isFav = favorites.some(f => f.id === channel.id);

              return (
                  <div
                      key={channel.id}
                      onClick={() => onSelectChannel(channel)}
                      className={`
                        group relative p-5 flex flex-col items-center justify-center text-center transition-all duration-500 cursor-pointer
                        border ${styles.layoutShape} min-w-0 active:scale-95
                        ${isActive 
                            ? `${styles.buttonActive} shadow-[0_20px_40px_rgba(0,0,0,0.4)] scale-105 z-10 border-transparent` 
                            : `${styles.card} ${styles.cardHover} hover:scale-105`}
                      `}
